/**
 * audio.js - Web Audio API Sound Generator & Voice Guidance System
 * Kịch bản "Cùng Bé Bin Đi Máy Bay" (8 Level: Mẹ, Bố, Bé Bin, Tiếp viên)
 */

class KidAudioManager {
    constructor() {
        this.ctx = null;
        this.isMuted = false;
        this.volume = 0.85;
        this.engineGain = null;
        this.engineSource = null;
        this.engineDrone = null;
        this.isEngineRunning = false;
        this.voiceEnabled = true;
        this.bubbleTimer = null;
        this.initAudioContext();
    }

    initAudioContext() {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (AudioCtx) {
            this.ctx = new AudioCtx();
        }
    }

    ensureContext() {
        if (!this.ctx) {
            this.initAudioContext();
        }
        if (this.ctx && this.ctx.state === 'suspended') {
            this.ctx.resume();
        }
    }

    // --- PROCEDURAL SOUND EFFECTS (WEB AUDIO API) ---

    // 1. Âm thanh "Ting!" ngọt ngào khi chọn đúng
    playTing() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;
        const osc1 = this.ctx.createOscillator();
        const osc2 = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc1.type = 'sine';
        osc2.type = 'triangle';

        osc1.frequency.setValueAtTime(1318.51, now);
        osc1.frequency.exponentialRampToValueAtTime(1320, now + 0.6);

        osc2.frequency.setValueAtTime(1975.53, now);
        osc2.frequency.exponentialRampToValueAtTime(2000, now + 0.4);

        gain.gain.setValueAtTime(0.3 * this.volume, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.7);

        osc1.connect(gain);
        osc2.connect(gain);
        gain.connect(this.ctx.destination);

        osc1.start(now);
        osc2.start(now);
        osc1.stop(now + 0.75);
        osc2.stop(now + 0.75);
    }

    // 2. Âm thanh "Boing / Cạch cạch" lò xo khi chọn đồ sai hoặc đồ cấm
    playBoing() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc.type = 'sine';
        osc.frequency.setValueAtTime(190, now);
        osc.frequency.linearRampToValueAtTime(420, now + 0.1);
        osc.frequency.linearRampToValueAtTime(210, now + 0.22);
        osc.frequency.linearRampToValueAtTime(360, now + 0.34);
        osc.frequency.linearRampToValueAtTime(180, now + 0.48);

        gain.gain.setValueAtTime(0.35 * this.volume, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.52);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start(now);
        osc.stop(now + 0.53);
    }

    // 3. Âm thanh "CẠCH!" khóa đai an toàn kim loại (Level 5)
    playClack() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;

        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(700, now);
        osc.frequency.exponentialRampToValueAtTime(140, now + 0.07);
        gain.gain.setValueAtTime(0.55 * this.volume, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.08);

        const oscSub = this.ctx.createOscillator();
        const gainSub = this.ctx.createGain();
        oscSub.type = 'sine';
        oscSub.frequency.setValueAtTime(200, now + 0.01);
        oscSub.frequency.exponentialRampToValueAtTime(45, now + 0.16);
        gainSub.gain.setValueAtTime(0.65 * this.volume, now + 0.01);
        gainSub.gain.exponentialRampToValueAtTime(0.001, now + 0.2);

        osc.connect(gain);
        gain.connect(this.ctx.destination);
        oscSub.connect(gainSub);
        gainSub.connect(this.ctx.destination);

        osc.start(now);
        osc.stop(now + 0.09);
        oscSub.start(now + 0.01);
        oscSub.stop(now + 0.22);
    }

    // 4. Âm thanh "TÁCH!" nhấc lẫy mở đai an toàn (Level 8)
    playUnbuckle() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc.type = 'sine';
        osc.frequency.setValueAtTime(400, now);
        osc.frequency.exponentialRampToValueAtTime(950, now + 0.08);
        osc.frequency.exponentialRampToValueAtTime(300, now + 0.15);

        gain.gain.setValueAtTime(0.4 * this.volume, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start(now);
        osc.stop(now + 0.2);
    }

    // 5. Âm thanh "Bíp boong!" cổng từ an ninh (Level 3)
    playBeepBoop() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;

        const osc1 = this.ctx.createOscillator();
        const gain1 = this.ctx.createGain();
        osc1.type = 'sine';
        osc1.frequency.setValueAtTime(1046.50, now);
        gain1.gain.setValueAtTime(0.3 * this.volume, now);
        gain1.gain.exponentialRampToValueAtTime(0.01, now + 0.15);
        osc1.connect(gain1);
        gain1.connect(this.ctx.destination);
        osc1.start(now);
        osc1.stop(now + 0.16);

        const osc2 = this.ctx.createOscillator();
        const gain2 = this.ctx.createGain();
        osc2.type = 'sine';
        osc2.frequency.setValueAtTime(1567.98, now + 0.18);
        gain2.gain.setValueAtTime(0.35 * this.volume, now + 0.18);
        gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.6);
        osc2.connect(gain2);
        gain2.connect(this.ctx.destination);
        osc2.start(now + 0.18);
        osc2.stop(now + 0.65);
    }

    // 6. Âm thanh "Bling bling!" phép thuật khi mây biến hình (Level 6)
    playBling() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;
        const freqs = [784, 988, 1175, 1568, 1976];
        freqs.forEach((f, i) => {
            const t = now + i * 0.08;
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(f, t);
            gain.gain.setValueAtTime(0.25 * this.volume, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.4);
            osc.connect(gain);
            gain.connect(this.ctx.destination);
            osc.start(t);
            osc.stop(t + 0.45);
        });
    }

    // 7. Âm thanh uống nước "Ực ực" + chuông giảm ù tai (Level 5)
    playDrinkWater() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;

        // 2 tiếng ực ực nhẹ
        [0, 0.22].forEach((offset) => {
            const t = now + offset;
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(320, t);
            osc.frequency.exponentialRampToValueAtTime(140, t + 0.12);
            gain.gain.setValueAtTime(0.3 * this.volume, t);
            gain.gain.exponentialRampToValueAtTime(0.01, t + 0.14);
            osc.connect(gain);
            gain.connect(this.ctx.destination);
            osc.start(t);
            osc.stop(t + 0.15);
        });

        // Chuông ngân du dương báo hiệu tai êm
        const chimeTime = now + 0.45;
        const oscC = this.ctx.createOscillator();
        const gainC = this.ctx.createGain();
        oscC.type = 'sine';
        oscC.frequency.setValueAtTime(1046.5, chimeTime);
        oscC.frequency.exponentialRampToValueAtTime(1318.5, chimeTime + 0.4);
        gainC.gain.setValueAtTime(0.35 * this.volume, chimeTime);
        gainC.gain.exponentialRampToValueAtTime(0.001, chimeTime + 0.8);
        oscC.connect(gainC);
        gainC.connect(this.ctx.destination);
        oscC.start(chimeTime);
        oscC.stop(chimeTime + 0.85);
    }

    // 8. Âm thanh "Poom pít!" chuông thông báo buồng lái (Level 7)
    playPoomPit() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;
        const notes = [659.25, 880.00]; // E5, A5
        notes.forEach((freq, idx) => {
            const t = now + idx * 0.2;
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(freq, t);
            gain.gain.setValueAtTime(0.28 * this.volume, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.6);
            osc.connect(gain);
            gain.connect(this.ctx.destination);
            osc.start(t);
            osc.stop(t + 0.65);
        });
    }

    // 9. Âm thanh vỗ tay chúc mừng
    playClap() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;
        for (let i = 0; i < 5; i++) {
            const t = now + i * 0.1 + Math.random() * 0.03;
            const bufferSize = this.ctx.sampleRate * 0.08;
            const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
            const data = buffer.getChannelData(0);
            for (let j = 0; j < bufferSize; j++) {
                data[j] = (Math.random() * 2 - 1) * Math.exp(-j / (bufferSize * 0.3));
            }
            const noise = this.ctx.createBufferSource();
            noise.buffer = buffer;
            const filter = this.ctx.createBiquadFilter();
            filter.type = 'bandpass';
            filter.frequency.value = 1200;
            const gain = this.ctx.createGain();
            gain.gain.setValueAtTime(0.3 * this.volume, t);
            noise.connect(filter);
            filter.connect(gain);
            gain.connect(this.ctx.destination);
            noise.start(t);
            noise.stop(t + 0.1);
        }
    }

    // 10. Âm thanh động cơ máy bay âm trầm êm ái
    startEngineSound(level = 0.22) {
        if (this.isEngineRunning || this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        try {
            const bufferSize = this.ctx.sampleRate * 2;
            const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
            const data = buffer.getChannelData(0);
            let lastOut = 0.0;
            for (let i = 0; i < bufferSize; i++) {
                const white = Math.random() * 2 - 1;
                data[i] = (lastOut + (0.02 * white)) / 1.02;
                lastOut = data[i];
                data[i] *= 3.5;
            }

            this.engineSource = this.ctx.createBufferSource();
            this.engineSource.buffer = buffer;
            this.engineSource.loop = true;

            const filter = this.ctx.createBiquadFilter();
            filter.type = 'lowpass';
            filter.frequency.value = 160;
            filter.Q.value = 1.2;

            const droneOsc = this.ctx.createOscillator();
            droneOsc.type = 'sine';
            droneOsc.frequency.value = 85;

            this.engineGain = this.ctx.createGain();
            this.engineGain.gain.setValueAtTime(0.001, this.ctx.currentTime);
            this.engineGain.gain.linearRampToValueAtTime(level * this.volume, this.ctx.currentTime + 1.0);

            this.engineSource.connect(filter);
            filter.connect(this.engineGain);
            droneOsc.connect(this.engineGain);
            this.engineGain.connect(this.ctx.destination);

            this.engineSource.start();
            droneOsc.start();
            this.engineDrone = droneOsc;
            this.isEngineRunning = true;
        } catch (e) {
            console.warn('Engine sound error:', e);
        }
    }

    stopEngineSound() {
        if (!this.isEngineRunning || !this.engineGain) return;
        try {
            const now = this.ctx.currentTime;
            this.engineGain.gain.linearRampToValueAtTime(0.001, now + 0.5);
            setTimeout(() => {
                if (this.engineSource) {
                    this.engineSource.stop();
                    this.engineSource.disconnect();
                }
                if (this.engineDrone) {
                    this.engineDrone.stop();
                    this.engineDrone.disconnect();
                }
                this.isEngineRunning = false;
            }, 550);
        } catch (e) {
            this.isEngineRunning = false;
        }
    }

    // 11. Fanfare chúc mừng chiến thắng
    playFanfare() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;
        const notes = [523.25, 659.25, 783.99, 1046.50, 1318.51];
        const times = [0, 0.12, 0.24, 0.38, 0.55];
        const durations = [0.15, 0.15, 0.15, 0.2, 0.9];

        notes.forEach((freq, idx) => {
            const t = now + times[idx];
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();

            osc.type = 'triangle';
            osc.frequency.setValueAtTime(freq, t);

            gain.gain.setValueAtTime(0.35 * this.volume, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + durations[idx]);

            osc.connect(gain);
            gain.connect(this.ctx.destination);

            osc.start(t);
            osc.stop(t + durations[idx] + 0.05);
        });
    }

    playPop() {
        if (this.isMuted) return;
        this.ensureContext();
        if (!this.ctx) return;

        const now = this.ctx.currentTime;
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc.type = 'sine';
        osc.frequency.setValueAtTime(520, now);
        osc.frequency.exponentialRampToValueAtTime(90, now + 0.08);

        gain.gain.setValueAtTime(0.25 * this.volume, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start(now);
        osc.stop(now + 0.09);
    }

    // --- VOICE-OVER & DIALOGUE SYSTEM (Mẹ, Bố, Bin, Tiếp viên) ---
    speak(speakerName, text, onComplete) {
        if (!this.voiceEnabled) {
            if (onComplete) onComplete();
            return;
        }

        this.showSpeakerBubble(speakerName, text);

        if (!('speechSynthesis' in window)) {
            if (onComplete) setTimeout(onComplete, 2500);
            return;
        }

        window.speechSynthesis.cancel();

        const utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = 'vi-VN';

        // Tùy chỉnh cao độ & tốc độ theo nhân vật
        if (speakerName.includes('Mẹ')) {
            utterance.pitch = 1.2;
            utterance.rate = 0.92;
        } else if (speakerName.includes('Bố')) {
            utterance.pitch = 0.95;
            utterance.rate = 0.95;
        } else if (speakerName.includes('Bin')) {
            utterance.pitch = 1.35;
            utterance.rate = 0.95;
        } else {
            utterance.pitch = 1.15;
            utterance.rate = 0.95;
        }

        const voices = window.speechSynthesis.getVoices();
        const viVoice = voices.find(v => v.lang.includes('vi') || v.name.includes('Vietnamese') || v.name.includes('An') || v.name.includes('Linh'));
        if (viVoice) {
            utterance.voice = viVoice;
        }

        utterance.onend = () => { if (onComplete) onComplete(); };
        utterance.onerror = () => { if (onComplete) onComplete(); };

        window.speechSynthesis.speak(utterance);
    }

    showSpeakerBubble(speakerName, text) {
        const bubble = document.getElementById('family-speech-bubble');
        const speakerSpan = document.getElementById('speaker-name-badge');
        const textSpan = document.getElementById('speaker-speech-text');
        const avatar = document.getElementById('speaker-avatar-icon');

        if (bubble && textSpan && speakerSpan) {
            speakerSpan.textContent = speakerName;
            textSpan.textContent = text;

            if (avatar) {
                if (speakerName.includes('Mẹ')) avatar.textContent = '👩';
                else if (speakerName.includes('Bố')) avatar.textContent = '👨';
                else if (speakerName.includes('Bin')) avatar.textContent = '🧒';
                else if (speakerName.includes('Tiếp viên')) avatar.textContent = '👩‍✈️';
                else avatar.textContent = '🌟';
            }

            bubble.classList.remove('hidden');
            bubble.classList.add('pop-in');

            clearTimeout(this.bubbleTimer);
            this.bubbleTimer = setTimeout(() => {
                bubble.classList.remove('pop-in');
                bubble.classList.add('pop-out');
                setTimeout(() => {
                    bubble.classList.add('hidden');
                    bubble.classList.remove('pop-out');
                }, 300);
            }, Math.max(3800, text.length * 115));
        }
    }
}

window.audioMgr = new KidAudioManager();

/**
 * effects.js - Canvas Particle System, Fireworks, Confetti, Hearts & Musical Notes
 * Tối ưu hóa hiệu ứng 60fps cho ứng dụng "Cùng Bé Bin Đi Máy Bay"
 */

class KidEffectsManager {
    constructor() {
        this.canvas = null;
        this.ctx = null;
        this.particles = [];
        this.animationFrame = null;
        this.isRunning = false;
    }

    init() {
        this.canvas = document.getElementById('effects-canvas');
        if (!this.canvas) return;
        this.ctx = this.canvas.getContext('2d');
        this.resize();
        window.addEventListener('resize', () => this.resize());
    }

    resize() {
        if (!this.canvas) return;
        this.canvas.width = window.innerWidth;
        this.canvas.height = window.innerHeight;
    }

    // 1. Pháo hoa & Confetti toàn màn hình khi chiến thắng
    startCelebrationFireworks(durationMs = 7000) {
        this.init();
        if (!this.canvas || !this.ctx) return;

        this.particles = [];
        this.isRunning = true;

        const colors = [
            '#FF5252', '#FF4081', '#E040FB', '#7C4DFF', 
            '#536DFE', '#40C4FF', '#18FFFF', '#64FFDA', 
            '#69F0AE', '#B2FF59', '#EEFF41', '#FFFF00', 
            '#FFD740', '#FFAB40', '#FF6E40'
        ];

        let fireworkTimer = setInterval(() => {
            if (!this.isRunning) {
                clearInterval(fireworkTimer);
                return;
            }
            const x = Math.random() * this.canvas.width * 0.8 + this.canvas.width * 0.1;
            const y = Math.random() * this.canvas.height * 0.45 + this.canvas.height * 0.1;
            this.createFireworkBurst(x, y, colors);
            if (window.audioMgr) window.audioMgr.playTing();
        }, 450);

        for (let i = 0; i < 80; i++) {
            this.particles.push({
                x: Math.random() * this.canvas.width,
                y: -Math.random() * this.canvas.height,
                vx: (Math.random() - 0.5) * 3.5,
                vy: Math.random() * 3.5 + 2,
                size: Math.random() * 11 + 8,
                color: colors[Math.floor(Math.random() * colors.length)],
                rotation: Math.random() * 360,
                vRot: (Math.random() - 0.5) * 12,
                shape: Math.random() > 0.4 ? 'rect' : 'star',
                alpha: 1
            });
        }

        this.loop();

        setTimeout(() => {
            clearInterval(fireworkTimer);
            setTimeout(() => { this.stop(); }, 3000);
        }, durationMs);
    }

    createFireworkBurst(x, y, colors) {
        const count = 48;
        for (let i = 0; i < count; i++) {
            const angle = (Math.PI * 2 / count) * i + (Math.random() * 0.2);
            const speed = Math.random() * 6.5 + 3;
            this.particles.push({
                x: x,
                y: y,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                size: Math.random() * 8 + 4,
                color: colors[Math.floor(Math.random() * colors.length)],
                alpha: 1,
                decay: Math.random() * 0.02 + 0.015,
                gravity: 0.09,
                shape: 'circle'
            });
        }
    }

    // 2. Chùm sao sáng tức thì tại vị trí chạm / kéo thả đúng
    burstStarsAt(x, y) {
        this.init();
        if (!this.canvas || !this.ctx) return;

        const starColors = ['#FFD700', '#FFA500', '#FF69B4', '#00E5FF', '#76FF03'];
        for (let i = 0; i < 22; i++) {
            const angle = Math.random() * Math.PI * 2;
            const speed = Math.random() * 5.5 + 2;
            this.particles.push({
                x: x,
                y: y,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed - 1.5,
                size: Math.random() * 9 + 6,
                color: starColors[Math.floor(Math.random() * starColors.length)],
                alpha: 1,
                decay: 0.03,
                gravity: 0.1,
                shape: 'star',
                rotation: Math.random() * 360,
                vRot: (Math.random() - 0.5) * 15
            });
        }

        if (!this.isRunning) {
            this.isRunning = true;
            this.loop();
        }
    }

    // 3. Trái tim bay lên (Level 7 khi hành khách vui mừng)
    spawnFloatingHeartsAt(x, y) {
        this.init();
        if (!this.canvas || !this.ctx) return;

        for (let i = 0; i < 12; i++) {
            const angle = (Math.random() - 0.5) * 1.5;
            this.particles.push({
                x: x + (Math.random() - 0.5) * 40,
                y: y + (Math.random() - 0.5) * 20,
                vx: Math.sin(angle) * 2,
                vy: -Math.random() * 3.5 - 2,
                size: Math.random() * 14 + 16,
                color: '#FF1744',
                alpha: 1,
                decay: 0.018,
                shape: 'heart'
            });
        }

        if (!this.isRunning) {
            this.isRunning = true;
            this.loop();
        }
    }

    // 4. Nốt nhạc bay quanh tai khi hết ù tai (Level 5)
    spawnMusicNotesAt(x, y) {
        this.init();
        if (!this.canvas || !this.ctx) return;

        const noteSymbols = ['🎵', '🎶', '✨', '⭐'];
        for (let i = 0; i < 10; i++) {
            this.particles.push({
                x: x + (Math.random() - 0.5) * 60,
                y: y + (Math.random() - 0.5) * 40,
                vx: (Math.random() - 0.5) * 3,
                vy: -Math.random() * 3 - 2,
                size: Math.random() * 10 + 20,
                symbol: noteSymbols[Math.floor(Math.random() * noteSymbols.length)],
                alpha: 1,
                decay: 0.02,
                shape: 'text'
            });
        }

        if (!this.isRunning) {
            this.isRunning = true;
            this.loop();
        }
    }

    loop() {
        if (!this.isRunning) return;

        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

        for (let i = this.particles.length - 1; i >= 0; i--) {
            const p = this.particles[i];
            p.x += p.vx;
            p.y += p.vy;
            if (p.gravity) p.vy += p.gravity;
            if (p.decay) p.alpha -= p.decay;
            if (p.vRot) p.rotation += p.vRot;

            if (p.alpha <= 0 || p.y > this.canvas.height + 25) {
                this.particles.splice(i, 1);
                continue;
            }

            this.ctx.save();
            this.ctx.globalAlpha = Math.max(0, p.alpha);

            if (p.shape === 'star') {
                this.ctx.fillStyle = p.color;
                this.drawStar(p.x, p.y, 5, p.size, p.size / 2, (p.rotation || 0) * Math.PI / 180);
            } else if (p.shape === 'rect') {
                this.ctx.fillStyle = p.color;
                this.ctx.translate(p.x, p.y);
                this.ctx.rotate((p.rotation || 0) * Math.PI / 180);
                this.ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
            } else if (p.shape === 'heart') {
                this.ctx.font = `${p.size}px sans-serif`;
                this.ctx.textAlign = 'center';
                this.ctx.textBaseline = 'middle';
                this.ctx.fillText('❤️', p.x, p.y);
            } else if (p.shape === 'text') {
                this.ctx.font = `${p.size}px sans-serif`;
                this.ctx.textAlign = 'center';
                this.ctx.textBaseline = 'middle';
                this.ctx.fillText(p.symbol, p.x, p.y);
            } else {
                this.ctx.fillStyle = p.color;
                this.ctx.beginPath();
                this.ctx.arc(p.x, p.y, p.size / 2, 0, Math.PI * 2);
                this.ctx.fill();
            }

            this.ctx.restore();
        }

        if (this.particles.length > 0) {
            this.animationFrame = requestAnimationFrame(() => this.loop());
        } else {
            this.isRunning = false;
        }
    }

    drawStar(cx, cy, spikes, outerRadius, innerRadius, angleOffset = 0) {
        let rot = Math.PI / 2 * 3 + angleOffset;
        let x = cx;
        let y = cy;
        const step = Math.PI / spikes;

        this.ctx.beginPath();
        this.ctx.moveTo(cx, cy - outerRadius);
        for (let i = 0; i < spikes; i++) {
            x = cx + Math.cos(rot) * outerRadius;
            y = cy + Math.sin(rot) * outerRadius;
            this.ctx.lineTo(x, y);
            rot += step;

            x = cx + Math.cos(rot) * innerRadius;
            y = cy + Math.sin(rot) * innerRadius;
            this.ctx.lineTo(x, y);
            rot += step;
        }
        this.ctx.lineTo(cx, cy - outerRadius);
        this.ctx.closePath();
        this.ctx.fill();
    }

    stop() {
        this.isRunning = false;
        if (this.animationFrame) {
            cancelAnimationFrame(this.animationFrame);
        }
        if (this.ctx && this.canvas) {
            this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
        }
        this.particles = [];
    }
}

