/* ==========================================================================
   SCREENS VIEWPORT
   ========================================================================== */
.screens-viewport {
    flex: 1;
    position: relative;
    width: 100%;
    height: calc(100vh - 72px);
    overflow: hidden;
}

.screen {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    visibility: hidden;
    transform: scale(0.96) translateY(20px);
    transition: opacity 0.4s ease, transform 0.4s cubic-bezier(0.34, 1.25, 0.64, 1), visibility 0.4s;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 10px 20px 90px 20px;
}

.screen.active {
    opacity: 1;
    visibility: visible;
    transform: scale(1) translateY(0);
}

.screen-header {
    text-align: center;
    margin-bottom: 12px;
}

.screen-title {
