    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.morph-cloud-card:active {
    transform: scale(1.25);
}

.morph-cloud-card.morphed {
    background: #FFF9C4;
    border: 4px solid #FFD54F;
    box-shadow: 0 0 25px #FFD54F;
    animation: gentle-bounce 0.6s infinite alternate;
}

/* ==========================================================================
   LEVEL 7: MÓN QUÀ LỊCH SỰ
   ========================================================================== */
.etiquette-cabin-grid {
    width: 100%;
    max-width: 900px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
}

.etiquette-card {
    background: rgba(255, 255, 255, 0.88);
    backdrop-filter: blur(8px);
    border-radius: 28px;
    padding: 18px;
    border: 4px solid #B3E5FC;
    box-shadow: var(--shadow-pop);
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 12px;
}

.volume-whisper-slider {
    width: 180px;
    height: 32px;
    cursor: pointer;
}

/* ==========================================================================
   LEVEL 8: BĂNG CHUYỀN & HUY HIỆU DỰ THƯỞNG
   ========================================================================== */
.carousel-final-arena {
    width: 100%;
    max-width: 920px;
    height: 340px;
    background: rgba(255, 255, 255, 0.88);
    backdrop-filter: blur(8px);
    border-radius: var(--radius-kid);
    border: 4px solid #FFD54F;
    box-shadow: var(--shadow-pop);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
}

.unbuckle-latch-zone {
    background: #FFF;
    border: 3px dashed #78909C;
    padding: 10px 20px;
    border-radius: 20px;
    cursor: pointer;
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 10px;
}

.unbuckle-latch-zone:active {
    transform: scale(1.08);
}

.golden-badge-modal {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) scale(0.8);
    opacity: 0;
    visibility: hidden;
    width: 90%;
    max-width: 600px;
    background: linear-gradient(135deg, #FFFDE7 0%, #FFF9C4 100%);
    border-radius: 36px;
    border: 8px solid #FFD54F;
    box-shadow: 0 20px 60px rgba(0,0,0,0.3);
    padding: 28px;
    text-align: center;
    z-index: 200;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.golden-badge-modal.show {
    opacity: 1;
    visibility: visible;
    transform: translate(-50%, -50%) scale(1);
}

.toy-airplane-model {
    font-size: 80px;
    animation: gentle-sway 2s infinite alternate;
    filter: drop-shadow(0 10px 14px rgba(0,0,0,0.2));
}

/* ==========================================================================
   PARENT GATE MODAL
   ========================================================================== */
.parent-modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.55);
    backdrop-filter: blur(6px);
    z-index: 999;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
}

.parent-modal-overlay.open {
    opacity: 1;
    visibility: visible;
}

.parent-card {
    width: 90%;
    max-width: 520px;
    background: #FFFFFF;
    border-radius: 32px;
    padding: 26px;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.25);
    border: 4px solid #FF8A65;
}

.parent-tip-item {
    background: #FFF3E0;
    border-left: 5px solid #FF9800;
    padding: 10px 14px;
    border-radius: 12px;
    margin-bottom: 10px;
    font-size: 15px;
    line-height: 1.4;
    color: #4E342E;
}

.settings-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin: 14px 0;
    font-size: 17px;
    font-weight: 700;
}

/* ==========================================================================
   KEYFRAME ANIMATIONS
   ========================================================================== */
@keyframes gentle-sway {
    0%, 100% { transform: rotate(-3deg); }
    50% { transform: rotate(3deg); }
}

@keyframes gentle-bounce {
    0% { transform: translateY(0); }
    100% { transform: translateY(-8px); }
}

@keyframes gentle-pulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.12); }
}

.pop-in {
    animation: popIn 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.pop-out {
    animation: popOut 0.25s ease forwards;
}

@keyframes popIn {
    0% { transform: scale(0.6); opacity: 0; }
    100% { transform: scale(1); opacity: 1; }
}

@keyframes popOut {
    0% { transform: scale(1); opacity: 1; }
    100% { transform: scale(0.6); opacity: 0; }
}

.hidden {
    display: none !important;
}

@media (max-width: 768px) {
    .closet-arena, .safety-seat-arena, .etiquette-cabin-grid, .suitcase-arena {
        grid-template-columns: 1fr;
        flex-direction: column;
    }
    .xray-stage-grid {
        grid-template-columns: 1fr;
    }
    .family-bubble-container {
        left: 10px;
        bottom: 10px;
    }
    .speaker-speech-card {
        max-width: 230px;
    }
    .speaker-speech-text {
        font-size: 14px;
    }
    .speaker-avatar-circle {
        width: 64px;
        height: 64px;
        font-size: 34px;
    }
}

/**
 * app.js - Main Game Controller for "Cùng Bé Bin Đi Máy Bay" (8 Levels)
 * Tối ưu hóa phản xạ mầm non 3-4 tuổi (Tap & Drag, Voice-over Bố & Mẹ)
 */

class KidFlightApp {
    constructor() {
        this.currentScreen = 1;
        this.totalScreens = 8;

        // Trạng thái các Level
        this.level1Dressed = { shirt: false, pants: false, shoes: false };
        this.level2Packed = 0;
        this.level3Steps = { checkin: false, xrayCount: 0, gate: false };
        this.level4Gate = false;
        this.level5Belt = { inserted: false, tightened: false, earRelieved: false };
        this.level6Clouds = { c1: false, c2: false, c3: false, c4: false };
        this.level7Tasks = { volume: false, leg: false };
        this.level8Tasks = { unbuckle: false, baggage: false };

        this.parentHoldStart = 0;
        this.parentHoldReqId = null;

        this.init();
    }

    init() {
        this.bindGlobalEvents();
        this.initLevel1();
        this.showScreen(1);
    }

    // --- SCREEN NAVIGATION & SPEECH TRIGGER ---
    showScreen(screenNum) {
        if (screenNum < 1 || screenNum > this.totalScreens) return;

        if (this.currentScreen === 5 && screenNum !== 5) {
            if (window.audioMgr) window.audioMgr.stopEngineSound();
        }

        this.currentScreen = screenNum;

        // Cập nhật DOM screen
        document.querySelectorAll('.screen').forEach((scr, idx) => {
            if (idx + 1 === screenNum) {
                scr.classList.add('active');
            } else {
                scr.classList.remove('active');
            }
        });

        // Cập nhật Stage dots
        document.querySelectorAll('.stage-dot').forEach((dot, idx) => {
            dot.classList.remove('active');
            if (idx + 1 === screenNum) {
                dot.classList.add('active');
            }
            if (idx + 1 < screenNum) {
                dot.classList.add('completed');
            }
        });

        this.triggerScreenVoice(screenNum);
    }

    triggerScreenVoice(screenNum) {
        if (!window.audioMgr) return;

        switch (screenNum) {
            case 1:
                window.audioMgr.speak('Mẹ', 'Bin ơi, hôm nay mình đi máy bay cả ngày đấy. Con hãy chọn những bộ quần áo thật thoải mái và dễ cởi để mặc nhé!');
                break;
            case 2:
                window.audioMgr.speak('Bố', 'Bin giúp Mẹ xếp đồ vào vali nhé, món nào cấm thì mình để lại nhà nha!');
                break;
            case 3:
                window.audioMgr.speak('Mẹ', 'Mình gửi vali qua máy soi chiếu nhé. Vali chỉ đi chơi một chút rồi quay lại ngay thôi!');
                break;
            case 4:
                window.audioMgr.speak('Bố', 'Nhìn qua cửa kính kìa Bin, máy bay đang đợi! Cùng tìm đúng Cửa 03 trên vé nào!');
                break;
            case 5:
                window.audioMgr.speak('Mẹ', 'Bin ngồi vào ghế rồi! Mình cùng thắt đai an toàn để thành Hiệp sĩ bay vững vàng nhé!');
                break;
            case 6:
                window.audioMgr.speak('Bố', 'Máy bay đang bay giữa bầu trời xanh rồi! Bin nhìn qua cửa sổ xem những đám mây giống hình gì nhé!');
                break;
            case 7:
                window.audioMgr.speak('Mẹ', 'Mọi người đang nghỉ ngơi, Bin làm hành khách nhí lịch sự nhé!');
                break;
            case 8:
                window.audioMgr.speak('Bố', 'Máy bay hạ cánh rồi! Mở đai và ra lấy vali dán hình gấu thôi nào!');
                break;
        }
    }

    // --- GLOBAL EVENTS & PARENT GATE ---
    bindGlobalEvents() {
        const btnVoice = document.getElementById('btn-repeat-voice');
        if (btnVoice) {
            btnVoice.addEventListener('click', () => {
                if (window.audioMgr) {
                    window.audioMgr.playPop();
                    this.triggerScreenVoice(this.currentScreen);
                }
            });
        }

        const avatarSpeaker = document.getElementById('speaker-avatar-icon');
        if (avatarSpeaker) {
            avatarSpeaker.addEventListener('click', () => {
                if (window.audioMgr) {
                    window.audioMgr.playPop();
                    this.triggerScreenVoice(this.currentScreen);
                }
            });
        }

        // Cổng Phụ Huynh: Giữ 3 giây
        const parentBtn = document.getElementById('btn-parent-gate');
        const holdCircle = document.getElementById('parent-ring-circle');
        const modal = document.getElementById('parent-modal');
        const closeModalBtn = document.getElementById('btn-close-parent');

        if (parentBtn && holdCircle) {
            const startHold = (e) => {
                e.preventDefault();
                this.parentHoldStart = Date.now();
                const totalHold = 3000;

                const updateRing = () => {
                    const elapsed = Date.now() - this.parentHoldStart;
                    const progress = Math.min(1, elapsed / totalHold);
                    const offset = 175 - (175 * progress);
                    holdCircle.style.strokeDashoffset = offset;

                    if (progress >= 1) {
                        if (window.audioMgr) window.audioMgr.playTing();
                        modal.classList.add('open');
                        resetHold();
                    } else {
                        this.parentHoldReqId = requestAnimationFrame(updateRing);
                    }
                };

                this.parentHoldReqId = requestAnimationFrame(updateRing);
            };

            const resetHold = () => {
                if (this.parentHoldReqId) cancelAnimationFrame(this.parentHoldReqId);
                holdCircle.style.strokeDashoffset = 175;
            };

            parentBtn.addEventListener('pointerdown', startHold);
            parentBtn.addEventListener('pointerup', resetHold);
            parentBtn.addEventListener('pointerleave', resetHold);
            parentBtn.addEventListener('pointercancel', resetHold);
        }

        if (closeModalBtn && modal) {
            closeModalBtn.addEventListener('click', () => {
                if (window.audioMgr) window.audioMgr.playPop();
                modal.classList.remove('open');
            });
        }

        const volSlider = document.getElementById('setting-volume');
        if (volSlider) {
            volSlider.addEventListener('input', (e) => {
                if (window.audioMgr) window.audioMgr.volume = parseFloat(e.target.value);
            });
        }

        const voiceToggle = document.getElementById('setting-voice');
        if (voiceToggle) {
            voiceToggle.addEventListener('change', (e) => {
                if (window.audioMgr) window.audioMgr.voiceEnabled = e.target.checked;
            });
        }

        // Chuyển màn hình qua Stage dots
        document.querySelectorAll('.stage-dot').forEach((dot) => {
            dot.addEventListener('click', (e) => {
                const targetScreen = parseInt(dot.getAttribute('data-screen'), 10);
                if (targetScreen) {
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.initLevel(targetScreen);
                    this.showScreen(targetScreen);
                }
            });
        });
    }

    initLevel(levelNum) {
        switch (levelNum) {
            case 1: this.initLevel1(); break;
            case 2: this.initLevel2(); break;
            case 3: this.initLevel3(); break;
            case 4: this.initLevel4(); break;
            case 5: this.initLevel5(); break;
            case 6: this.initLevel6(); break;
            case 7: this.initLevel7(); break;
            case 8: this.initLevel8(); break;
        }
    }

    // ==========================================================================
    // LEVEL 1: TRANG PHỤC BAY THOẢI MÁI
    // ==========================================================================
    initLevel1() {
        const clothes = document.querySelectorAll('.clothes-item-btn');
        const binFigure = document.getElementById('bin-dress-target');
        const btnNext1 = document.getElementById('btn-next-level-1');

        clothes.forEach(item => {
            let startX = 0, startY = 0;
            let isDragging = false;

            const onDown = (e) => {
                if (item.classList.contains('worn')) return;
                isDragging = true;
                item.setPointerCapture(e.pointerId);
                startX = e.clientX;
                startY = e.clientY;
                item.style.zIndex = '999';
            };

            const onMove = (e) => {
                if (!isDragging) return;
                const dx = e.clientX - startX;
                const dy = e.clientY - startY;
                item.style.transform = `translate(${dx}px, ${dy}px) scale(1.2)`;
            };

            const onUp = (e) => {
                if (!isDragging) return;
                isDragging = false;
                item.releasePointerCapture(e.pointerId);

                const itemRect = item.getBoundingClientRect();
                const binRect = binFigure.getBoundingClientRect();

                const isOver = !(
                    itemRect.right < binRect.left ||
                    itemRect.left > binRect.right ||
                    itemRect.bottom < binRect.top ||
                    itemRect.top > binRect.bottom
                );

                const isCorrect = item.getAttribute('data-correct') === 'true';
                const type = item.getAttribute('data-type');

                if (isOver) {
                    if (isCorrect) {
                        // Mặc đúng!
                        item.classList.add('worn');
                        item.style.display = 'none';

                        // Cập nhật trang phục trên người Bin
                        if (type === 'shirt') {
                            document.getElementById('bin-slot-shirt').textContent = '👕';
                            this.level1Dressed.shirt = true;
                        } else if (type === 'pants') {
                            document.getElementById('bin-slot-pants').textContent = '🩳';
                            this.level1Dressed.pants = true;
                        } else if (type === 'shoes') {
                            document.getElementById('bin-slot-shoes').textContent = '👟';
                            this.level1Dressed.shoes = true;
                        }

                        if (window.effectsMgr) {
                            window.effectsMgr.burstStarsAt(binRect.left + binRect.width / 2, binRect.top + binRect.height / 2);
                        }
                        if (window.audioMgr) window.audioMgr.playTing();

                        // Kiểm tra hoàn thành
                        if (this.level1Dressed.shirt && this.level1Dressed.pants && this.level1Dressed.shoes) {
                            binFigure.classList.add('gentle-bounce');
                            if (window.audioMgr) {
                                setTimeout(() => {
                                    window.audioMgr.speak('Mẹ', 'Bin chọn đồ giỏi quá, vừa thoải mái vừa ấm áp khi lên máy bay đấy!');
                                }, 500);
                            }
                            if (btnNext1) {
                                btnNext1.classList.remove('hidden');
                                btnNext1.classList.add('pop-in');
                            }
                        }
                    } else {
                        // Chọn sai/bất tiện: nảy lại kèm lời nhắc của Bố
                        item.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
                        item.style.transform = 'translate(0px, 0px)';
                        if (window.audioMgr) {
                            window.audioMgr.playBoing();
                            window.audioMgr.speak('Bố', 'Quần bó và giày nhiều dây này sẽ làm Bin hơi khó chịu khi ngồi lâu đấy, mình chọn đồ thun mềm nhé!');
                        }
                    }
                } else {
                    item.style.transition = 'transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)';
                    item.style.transform = 'translate(0px, 0px)';
                }
            };

            item.addEventListener('pointerdown', onDown);
            item.addEventListener('pointermove', onMove);
            item.addEventListener('pointerup', onUp);
            item.addEventListener('pointercancel', onUp);
        });

        if (btnNext1) {
            btnNext1.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.initLevel2();
                this.showScreen(2);
            };
        }
    }

    // ==========================================================================
    // LEVEL 2: CHIẾC VALI KỲ DIỆU
    // ==========================================================================
    initLevel2() {
        const luggageItems = document.querySelectorAll('.luggage-item-lvl2');
        const suitcase = document.getElementById('suitcase-target-lvl2');
        const suitcaseInner = document.getElementById('suitcase-inner-lvl2');
        const btnNext2 = document.getElementById('btn-next-level-2');

        luggageItems.forEach(item => {
            let startX = 0, startY = 0;
            let isDragging = false;

            const onDown = (e) => {
                if (item.classList.contains('packed')) return;
                isDragging = true;
                item.setPointerCapture(e.pointerId);
                startX = e.clientX;
                startY = e.clientY;
                item.style.zIndex = '999';
            };

            const onMove = (e) => {
                if (!isDragging) return;
                const dx = e.clientX - startX;
                const dy = e.clientY - startY;
                item.style.transform = `translate(${dx}px, ${dy}px) scale(1.2)`;
            };

            const onUp = (e) => {
                if (!isDragging) return;
                isDragging = false;
                item.releasePointerCapture(e.pointerId);

                const itemRect = item.getBoundingClientRect();
                const suitcaseRect = suitcase.getBoundingClientRect();

                const isOver = !(
                    itemRect.right < suitcaseRect.left ||
                    itemRect.left > suitcaseRect.right ||
                    itemRect.bottom < suitcaseRect.top ||
                    itemRect.top > suitcaseRect.bottom
                );

                const isForbidden = item.getAttribute('data-forbidden') === 'true';

                if (isOver) {
                    if (isForbidden) {
                        item.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
                        item.style.transform = 'translate(0px, 0px)';
                        if (window.audioMgr) {
                            window.audioMgr.playBoing();
                            window.audioMgr.speak('Bố', 'Chai nước to và kéo nhọn không được mang lên máy bay đâu Bin ơi!');
                        }
                    } else {
                        item.classList.add('packed');
                        item.style.display = 'none';

                        const iconSpan = document.createElement('span');
                        iconSpan.textContent = item.querySelector('.item-icon').textContent;
                        iconSpan.style.fontSize = '34px';
                        iconSpan.className = 'pop-in';
                        suitcaseInner.appendChild(iconSpan);

                        this.level2Packed++;

                        if (window.effectsMgr) {
                            window.effectsMgr.burstStarsAt(suitcaseRect.left + suitcaseRect.width / 2, suitcaseRect.top + suitcaseRect.height / 2);
                        }
                        if (window.audioMgr) window.audioMgr.playTing();

                        if (this.level2Packed >= 3) {
                            if (window.audioMgr) {
                                setTimeout(() => {
                                    window.audioMgr.speak('Mẹ', 'Vali đã xếp gọn gàng rồi, gia đình mình cùng ra sân bay nào!');
                                }, 500);
                            }
                            if (btnNext2) {
                                btnNext2.classList.remove('hidden');
                                btnNext2.classList.add('pop-in');
                            }
                        }
                    }
                } else {
                    item.style.transition = 'transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)';
                    item.style.transform = 'translate(0px, 0px)';
                }
            };

            item.addEventListener('pointerdown', onDown);
            item.addEventListener('pointermove', onMove);
            item.addEventListener('pointerup', onUp);
            item.addEventListener('pointercancel', onUp);
        });

        if (btnNext2) {
            btnNext2.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.initLevel3();
                this.showScreen(3);
            };
        }
    }

    // ==========================================================================
    // LEVEL 3: CỬA SỔ X-QUANG THẦN KỲ
    // ==========================================================================
    initLevel3() {
        const passCard = document.getElementById('pass-card-lvl3');
        const stampBadge = document.getElementById('stamp-badge-lvl3');
        const xrayBoxes = document.querySelectorAll('.xray-glow-box');
        const trayItem = document.getElementById('tray-shoes-jacket-lvl3');
        const gate = document.getElementById('gate-detector-lvl3');
        const lamps = document.querySelectorAll('.gate-lamp-lvl3');
        const binWalker = document.getElementById('bin-walker-lvl3');
        const btnNext3 = document.getElementById('btn-next-level-3');

        // Bước 1: Check-in trao vé
        if (passCard) {
            passCard.onclick = () => {
                if (this.level3Steps.checkin) return;
                this.level3Steps.checkin = true;
                if (stampBadge) stampBadge.classList.add('stamped');
                if (window.audioMgr) {
                    window.audioMgr.playStamp();
                    setTimeout(() => {
                        window.audioMgr.speak('Tiếp viên', 'Chào gia đình bé Bin! Mời gia đình cho vali qua máy soi chiếu nhé!');
                    }, 400);
                }
                this.checkLevel3Completion();
            };
        }

        // Bước 2: Chạm khối màu X-quang
        xrayBoxes.forEach(box => {
            box.onclick = () => {
                if (box.getAttribute('data-revealed') === 'true') return;
                box.setAttribute('data-revealed', 'true');
                box.textContent = box.getAttribute('data-item');
                box.style.background = '#FFF9C4';
                this.level3Steps.xrayCount++;

                if (window.audioMgr) window.audioMgr.playTing();
                if (window.effectsMgr) {
                    const r = box.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }

                if (this.level3Steps.xrayCount >= 3) {
                    if (window.audioMgr) {
                        setTimeout(() => {
                            window.audioMgr.speak('Mẹ', 'Đồ vật bên trong sáng lung linh chưa kìa! Bin để áo khoác lên khay và qua cổng từ nhé!');
                        }, 400);
                    }
                    this.checkLevel3Completion();
                }
            };
        });

        // Bước 3: Cởi áo khoác lên khay và bước qua cổng từ
        if (trayItem) {
            trayItem.onclick = () => {
                trayItem.style.background = '#81C784';
                trayItem.innerHTML = '<span>🧥👟 Đã đặt lên khay ✓</span>';
                if (window.audioMgr) window.audioMgr.playPop();
            };
        }

        if (gate) {
            gate.onclick = () => {
                if (this.level3Steps.gate) return;
                this.level3Steps.gate = true;

                lamps.forEach(l => l.classList.add('green-flash'));
                if (binWalker) binWalker.style.transform = 'translateY(-18px) scale(1.15)';

                if (window.audioMgr) {
                    window.audioMgr.playBeepBoop();
                    window.audioMgr.playClap();
                    setTimeout(() => {
                        window.audioMgr.speak('Bố', 'Hoan hô Bin! Qua cổng an ninh an toàn rồi!');
                    }, 500);
                }
                this.checkLevel3Completion();
            };
        }

        if (btnNext3) {
            btnNext3.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.initLevel4();
                this.showScreen(4);
            };
        }
    }

    checkLevel3Completion() {
        const btnNext3 = document.getElementById('btn-next-level-3');
        if (this.level3Steps.checkin && this.level3Steps.xrayCount >= 3 && this.level3Steps.gate) {
            if (btnNext3) {
                btnNext3.classList.remove('hidden');
                btnNext3.classList.add('pop-in');
            }
        }
    }

    // ==========================================================================
    // LEVEL 4: SỐ MẤY LÊN MÁY BAY (GATE 03)
    // ==========================================================================
    initLevel4() {
        const gateCards = document.querySelectorAll('.gate-card-btn');
        const jetBridge = document.getElementById('jet-bridge-walkway');
        const binWalker = document.getElementById('bin-bridge-walker');
        const btnNext4 = document.getElementById('btn-next-level-4');

        gateCards.forEach(card => {
            card.onclick = () => {
                const gateNum = card.getAttribute('data-gate');

                if (gateNum === '03') {
                    if (this.level4Gate) return;
                    this.level4Gate = true;
                    card.classList.add('correct-gate');

                    if (window.effectsMgr) {
                        const r = card.getBoundingClientRect();
                        window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                    }
                    if (window.audioMgr) {
                        window.audioMgr.playTing();
                        window.audioMgr.speak('Bố', 'Đúng rồi! Cổng 03 đây rồi, cùng bước qua ống lồng vào máy bay nào!');
                    }

                    if (jetBridge) {
                        jetBridge.style.borderColor = '#00E676';
                    }
                } else {
                    if (window.audioMgr) {
                        window.audioMgr.playBoing();
                        window.audioMgr.speak('Bố', 'Xem kỹ lại số trên vé nha Bin, vé ghi Cửa 03 nè!');
                    }
                }
            };
        });

        if (jetBridge) {
            jetBridge.onclick = () => {
                if (!this.level4Gate) {
                    if (window.audioMgr) window.audioMgr.speak('Mẹ', 'Bin tìm đúng Cổng 03 trước nhé!');
                    return;
                }

                if (binWalker) {
                    binWalker.style.transform = 'translateX(220px)';
