                        window.audioMgr.speak('Tiếp viên', 'Chào mừng bé Bin và gia đình lên máy bay!');
                    }, 400);
                }

                if (btnNext4) {
                    btnNext4.classList.remove('hidden');
                    btnNext4.classList.add('pop-in');
                }
            };
        }

        if (btnNext4) {
            btnNext4.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.initLevel5();
                this.showScreen(5);
            };
        }
    }

    // ==========================================================================
    // LEVEL 5: HIỆP SĨ ĐAI AN TOÀN & XỬ LÝ Ù TAI
    // ==========================================================================
    initLevel5() {
        const strapLeft = document.getElementById('seatbelt-strap-lvl5');
        const puzzleBox = document.getElementById('seatbelt-puzzle-lvl5');
        const indicator = document.getElementById('safety-indicator-lvl5');
        const cape = document.getElementById('bin-knight-cape');
        const btnWater = document.getElementById('btn-drink-water-lvl5');
        const earWaves = document.querySelectorAll('.ear-soundwave');
        const btnNext5 = document.getElementById('btn-next-level-5');

        // Kéo cài đai an toàn
        if (strapLeft && puzzleBox) {
            let isDragging = false;
            let startX = 0;

            const onDown = (e) => {
                if (this.level5Belt.inserted) return;
                isDragging = true;
                strapLeft.setPointerCapture(e.pointerId);
                startX = e.clientX;
            };

            const onMove = (e) => {
                if (!isDragging || this.level5Belt.inserted) return;
                const dx = Math.max(0, Math.min(45, e.clientX - startX));
                strapLeft.style.transform = `translateX(${dx}px)`;

                if (dx >= 35) {
                    // Cài chốt CẠCH!
                    this.level5Belt.inserted = true;
                    this.level5Belt.tightened = true;
                    puzzleBox.classList.add('seatbelt-buckled');

                    if (indicator) indicator.classList.add('green-safe');
                    if (cape) cape.classList.add('active');

                    if (window.audioMgr) {
                        window.audioMgr.playClack();
                        window.audioMgr.startEngineSound(0.28);
                        setTimeout(() => {
                            window.audioMgr.speak('Mẹ', 'CẠCH! Bin đã thắt đai an toàn và biến thành Hiệp sĩ bay rồi!');
                        }, 300);
                    }

                    if (window.effectsMgr) {
                        const r = puzzleBox.getBoundingClientRect();
                        window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                    }

                    // Hiện sóng âm ù tai sau 3 giây
                    setTimeout(() => {
                        earWaves.forEach(w => w.classList.remove('hidden'));
                        if (btnWater) btnWater.classList.remove('hidden');
                        if (window.audioMgr) {
                            window.audioMgr.speak('Mẹ', 'Máy bay đang bay lên mây đấy! Nếu Bin thấy tai hơi u u, con hãy uống một ngụm nước nhé!');
                        }
                    }, 3500);
                }
            };

            const onUp = (e) => {
                if (!isDragging) return;
                isDragging = false;
                strapLeft.releasePointerCapture(e.pointerId);
                if (!this.level5Belt.inserted) {
                    strapLeft.style.transform = 'translateX(0px)';
                }
            };

            strapLeft.addEventListener('pointerdown', onDown);
            strapLeft.addEventListener('pointermove', onMove);
            strapLeft.addEventListener('pointerup', onUp);
        }

        // Chạm ly nước cho Bin uống
        if (btnWater) {
            btnWater.onclick = () => {
                if (this.level5Belt.earRelieved) return;
                this.level5Belt.earRelieved = true;

                earWaves.forEach(w => w.classList.add('hidden'));

                if (window.effectsMgr) {
                    const binHead = document.getElementById('bin-seat-head');
                    if (binHead) {
                        const r = binHead.getBoundingClientRect();
                        window.effectsMgr.spawnMusicNotesAt(r.left + r.width / 2, r.top);
                    }
                }

                if (window.audioMgr) {
                    window.audioMgr.playDrinkWater();
                    setTimeout(() => {
                        window.audioMgr.speak('Bin', 'Hết ù tai rồi, thích quá Bố Mẹ ơi!');
                    }, 900);
                }

                if (btnNext5) {
                    btnNext5.classList.remove('hidden');
                    btnNext5.classList.add('pop-in');
                }
            };
        }

        if (btnNext5) {
            btnNext5.onclick = () => {
                if (window.audioMgr) {
                    window.audioMgr.stopEngineSound();
                    window.audioMgr.playPop();
                }
                this.initLevel6();
                this.showScreen(6);
            };
        }
    }

    // ==========================================================================
    // LEVEL 6: NGẮM VÀ TƯỞNG TƯỢNG ĐÁM MÂY
    // ==========================================================================
    initLevel6() {
        const cloudCards = document.querySelectorAll('.morph-cloud-card');
        const btnNext6 = document.getElementById('btn-next-level-6');

        cloudCards.forEach(card => {
            card.onclick = () => {
                if (card.classList.contains('morphed')) return;
                card.classList.add('morphed');

                const targetType = card.getAttribute('data-morph');
                const icon = card.querySelector('.cloud-icon');
                const label = card.querySelector('.cloud-label');

                if (targetType === 'bunny') {
                    icon.textContent = '🐰';
                    label.textContent = 'Chú thỏ nhảy';
                    this.level6Clouds.c1 = true;
                    if (window.audioMgr) {
                        window.audioMgr.playBling();
                        window.audioMgr.speak('Bin', 'Kìa, một chú thỏ mây kìa Bố Mẹ ơi!');
                    }
                } else if (targetType === 'car') {
                    icon.textContent = '🚗';
                    label.textContent = 'Ô tô bon bon';
                    this.level6Clouds.c2 = true;
                    if (window.audioMgr) {
                        window.audioMgr.playBling();
                        window.audioMgr.speak('Bin', 'Oa, một chiếc ô tô mây đang chạy kìa!');
                    }
                } else if (targetType === 'watermelon') {
                    icon.textContent = '🍉';
                    label.textContent = 'Dưa hấu mây';
                    this.level6Clouds.c3 = true;
                    if (window.audioMgr) {
                        window.audioMgr.playBling();
                        window.audioMgr.speak('Bin', 'Miếng dưa hấu mây ngọt lịm ngon quá!');
                    }
                } else if (targetType === 'bear') {
                    icon.textContent = '🐻';
                    label.textContent = 'Chú gấu vẫy tay';
                    this.level6Clouds.c4 = true;
                    if (window.audioMgr) {
                        window.audioMgr.playBling();
                        window.audioMgr.speak('Bin', 'Chú gấu bông mây vẫy tay chào Bin kìa!');
                    }
                }

                if (window.effectsMgr) {
                    const r = card.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }

                if (this.level6Clouds.c1 && this.level6Clouds.c2 && this.level6Clouds.c3 && this.level6Clouds.c4) {
                    if (btnNext6) {
                        btnNext6.classList.remove('hidden');
                        btnNext6.classList.add('pop-in');
                    }
                }
            };
        });

        if (btnNext6) {
            btnNext6.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.initLevel7();
                this.showScreen(7);
            };
        }
    }

    // ==========================================================================
    // LEVEL 7: MÓN QUÀ LỊCH SỰ
    // ==========================================================================
    initLevel7() {
        const slider = document.getElementById('volume-whisper-slider');
        const sliderLabel = document.getElementById('whisper-status-label');
        const legTarget = document.getElementById('bin-leg-target');
        const legLabel = document.getElementById('leg-status-label');
        const btnNext7 = document.getElementById('btn-next-level-7');

        // Tình huống 1: Kéo âm lượng nói thầm
        if (slider) {
            slider.addEventListener('input', (e) => {
                const val = parseInt(e.target.value, 10);
                if (val <= 25) {
                    if (!this.level7Tasks.volume) {
                        this.level7Tasks.volume = true;
                        if (sliderLabel) sliderLabel.textContent = '🤫 Bin nói thầm nhẹ nhàng ✓';
                        slider.disabled = true;

                        if (window.effectsMgr) {
                            const r = slider.getBoundingClientRect();
                            window.effectsMgr.spawnFloatingHeartsAt(r.left + r.width / 2, r.top);
                        }

                        if (window.audioMgr) {
                            window.audioMgr.playTing();
                            window.audioMgr.speak('Bin', 'Chúng mình nói khẽ cho mọi người nghỉ ngơi nhé!');
                        }
                        this.checkLevel7Completion();
                    }
                }
            });
        }

        // Tình huống 2: Thu chân không đạp ghế trước
        if (legTarget) {
            legTarget.onclick = () => {
                if (this.level7Tasks.leg) return;
                this.level7Tasks.leg = true;
                legTarget.style.transform = 'translateY(15px)';
                if (legLabel) legLabel.textContent = '🪑 Chân đã thu lại ngay ngắn ✓';

                if (window.effectsMgr) {
                    const r = legTarget.getBoundingClientRect();
                    window.effectsMgr.spawnFloatingHeartsAt(r.left + r.width / 2, r.top);
                }

                if (window.audioMgr) {
                    window.audioMgr.playTing();
                    window.audioMgr.speak('Bố', 'Bin ngồi ngoan lắm, không đạp vào lưng ghế phía trước là rất lịch sự!');
                }
                this.checkLevel7Completion();
            };
        }

        if (btnNext7) {
            btnNext7.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.initLevel8();
                this.showScreen(8);
            };
        }
    }

    checkLevel7Completion() {
        const btnNext7 = document.getElementById('btn-next-level-7');
        if (this.level7Tasks.volume && this.level7Tasks.leg) {
            if (btnNext7) {
                btnNext7.classList.remove('hidden');
                btnNext7.classList.add('pop-in');
            }
        }
    }

    // ==========================================================================
    // LEVEL 8: BĂNG CHUYỀN VUI NHỘN & HUY HIỆU DỰ THƯỞNG
    // ==========================================================================
    initLevel8() {
        const unbuckleLatch = document.getElementById('unbuckle-latch-btn');
        const baggageCarousel = document.getElementById('baggage-carousel-lvl8');
        const bags = document.querySelectorAll('.carousel-bag-lvl8');
        const badgeModal = document.getElementById('golden-badge-modal');
        const btnReplay = document.getElementById('btn-replay-adventure');

        // Bước 1: Mở lẫy đai an toàn
        if (unbuckleLatch) {
            unbuckleLatch.onclick = () => {
                if (this.level8Tasks.unbuckle) return;
                this.level8Tasks.unbuckle = true;
                unbuckleLatch.innerHTML = '<span>🔓 Đã mở khóa đai an toàn ✓</span>';
                unbuckleLatch.style.borderColor = '#00E676';

                if (window.audioMgr) {
                    window.audioMgr.playUnbuckle();
                    setTimeout(() => {
                        window.audioMgr.speak('Bố', 'Tách! Đai đã mở, giờ gia đình mình ra băng chuyền lấy vali dán hình gấu nhé!');
                    }, 300);
                }

                if (baggageCarousel) baggageCarousel.classList.remove('hidden');
            };
        }

        // Bước 2: Bắt đúng vali đỏ hình gấu
        bags.forEach(bag => {
            bag.onclick = () => {
                if (!this.level8Tasks.unbuckle) {
                    if (window.audioMgr) window.audioMgr.speak('Mẹ', 'Bin mở đai an toàn trước nhé!');
                    return;
                }

                const isBinBag = bag.getAttribute('data-is-bin') === 'true';

                if (isBinBag) {
                    this.level8Tasks.baggage = true;
                    bag.style.transform = 'scale(1.4) translateY(-20px)';
                    document.querySelector('.carousel-suitcases').classList.add('paused');

                    if (window.effectsMgr) {
                        window.effectsMgr.startCelebrationFireworks(8000);
                    }

                    if (window.audioMgr) {
                        window.audioMgr.playFanfare();
                        setTimeout(() => {
                            window.audioMgr.speak('Mẹ', 'Hoan hô bé Bin! Chúc mừng Hành khách nhí xuất sắc của Bố Mẹ!');
                        }, 500);
                    }

                    setTimeout(() => {
                        if (badgeModal) badgeModal.classList.add('show');
                    }, 1200);
                } else {
                    if (window.audioMgr) {
                        window.audioMgr.playBoing();
                        window.audioMgr.speak('Bố', 'Vali này của bạn khác rồi, Bin tìm chiếc vali màu đỏ có dán hình gấu nhé!');
                    }
                }
            };
        });

        if (btnReplay) {
            btnReplay.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                window.location.reload();
            };
        }
    }
}

