// Dialogue Manager dành cho hiển thị bong bóng thoại Ba Mẹ đọc (KHÔNG tự ẩn, KHÔNG speech synthesis)
class DialogueManager {
    show(speakerName, text, avatarEmoji = null) {
        const textSpan = document.getElementById('parent-prompt-text');
        const iconSpan = document.getElementById('parent-prompt-icon');
        const bubbleCard = document.querySelector('.parent-prompt-signboard');

        if (textSpan) {
            textSpan.textContent = text;
        }

        if (iconSpan) {
            if (avatarEmoji) {
                iconSpan.textContent = avatarEmoji;
            } else if (speakerName.includes('Mẹ')) {
                iconSpan.textContent = '👩';
            } else if (speakerName.includes('Bố')) {
                iconSpan.textContent = '👨';
            } else if (speakerName.includes('Bin')) {
                iconSpan.textContent = '🧒';
            } else if (speakerName.includes('Tiếp viên')) {
                iconSpan.textContent = '👩‍✈️';
            }
        }

        if (bubbleCard) {
            bubbleCard.classList.remove('pop-in');
            void bubbleCard.offsetWidth;
            bubbleCard.classList.add('pop-in');
        }
    }
}

