// Parent Prompt & Dialogue Manager: Hiển thị câu thoại tĩnh trên biển báo phía trên
class DialogueManager {
    show(speaker, text, avatarEmoji = null) {
        const textSpan = document.getElementById('parent-prompt-text');
        const iconSpan = document.getElementById('parent-prompt-icon');
        const bubbleCard = document.querySelector('.parent-prompt-signboard');

        if (textSpan) {
            textSpan.textContent = text;
        }

        if (iconSpan) {
            if (avatarEmoji) {
                iconSpan.textContent = avatarEmoji;
            } else if (speaker.includes('Mẹ')) {
                iconSpan.textContent = '👩';
            } else if (speaker.includes('Bố')) {
                iconSpan.textContent = '👨';
            } else if (speaker.includes('Bin')) {
                iconSpan.textContent = '🧒';
            } else if (speaker.includes('Tiếp viên')) {
                iconSpan.textContent = '👩‍✈️';
            }
        }

        if (bubbleCard) {
            bubbleCard.classList.remove('pop-in');
            void bubbleCard.offsetWidth;
            bubbleCard.classList.add('pop-in');
        }
    }
}

window.dialogueMgr = new DialogueManager();

/**
 * effects.js - Canvas Particle System & Animations
 * Đảm bảo chỉ khởi tạo 1 lần và hỗ trợ triệt để Giảm hiệu ứng chuyển động (Reduced Motion)
 */

class KidEffectsManager {
    constructor() {
        this.canvas = null;
        this.ctx = null;
        this.particles = [];
        this.animationFrame = null;
        this.isRunning = false;
        this.reducedMotion = false;
        this.initialized = false;
        this.boundResize = this.resize.bind(this);
    }

    init() {
        if (this.initialized) return;
        this.canvas = document.getElementById('effects-canvas');
        if (!this.canvas) return;
        this.ctx = this.canvas.getContext('2d');
        this.resize();
        window.addEventListener('resize', this.boundResize);
        this.initialized = true;
    }

    resize() {
        if (!this.canvas) return;
        this.canvas.width = window.innerWidth;
        this.canvas.height = window.innerHeight;
    }

    // 1. Pháo hoa chúc mừng chiến thắng (Level 8 - rút ngắn 3s, nhẹ nhàng)
    startCelebrationFireworks(durationMs = 3000) {
        if (this.reducedMotion) {
            // Chế độ giảm chuyển động: Chỉ bung một vài ngôi sao nhẹ ở tâm
            this.burstStarsAt(window.innerWidth / 2, window.innerHeight / 2);
            return;
        }

        this.init();
        if (!this.canvas || !this.ctx) return;

        this.particles = [];
        this.isRunning = true;

        const colors = [
            '#FF5252', '#FF4081', '#E040FB', '#7C4DFF', 
            '#536DFE', '#40C4FF', '#18FFFF', '#64FFDA', 
            '#69F0AE', '#B2FF59', '#EEFF41', '#FFFF00', 
            '#FFD740', '#FFAB40', '#FF6E40'
        ];

        let fireworkTimer = setInterval(() => {
            if (!this.isRunning) {
                clearInterval(fireworkTimer);
                return;
            }
            const x = Math.random() * this.canvas.width * 0.8 + this.canvas.width * 0.1;
            const y = Math.random() * this.canvas.height * 0.45 + this.canvas.height * 0.1;
            this.createFireworkBurst(x, y, colors);
            if (window.audioMgr) window.audioMgr.playTing();
        }, 400);

        for (let i = 0; i < 40; i++) {
            this.particles.push({
                x: Math.random() * this.canvas.width,
                y: -Math.random() * this.canvas.height,
                vx: (Math.random() - 0.5) * 3,
                vy: Math.random() * 3 + 2,
                size: Math.random() * 9 + 6,
                color: colors[Math.floor(Math.random() * colors.length)],
                rotation: Math.random() * 360,
                vRot: (Math.random() - 0.5) * 10,
                shape: Math.random() > 0.4 ? 'rect' : 'star',
                alpha: 1
            });
        }

        this.loop();

        setTimeout(() => {
            clearInterval(fireworkTimer);
            setTimeout(() => { this.stop(); }, 1200);
        }, durationMs);
    }

    createFireworkBurst(x, y, colors) {
        const count = 30;
        for (let i = 0; i < count; i++) {
            const angle = (Math.PI * 2 / count) * i + (Math.random() * 0.2);
            const speed = Math.random() * 5 + 2;
            this.particles.push({
                x: x,
                y: y,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed,
                size: Math.random() * 6 + 3,
                color: colors[Math.floor(Math.random() * colors.length)],
                alpha: 1,
                decay: Math.random() * 0.025 + 0.02,
                gravity: 0.09,
                shape: 'circle'
            });
        }
    }

    // 2. Chùm sao sáng tức thì tại vị trí chạm / kéo thả đúng
    burstStarsAt(x, y) {
        this.init();
        if (!this.canvas || !this.ctx) return;

        const starColors = ['#FFD700', '#FFA500', '#FF69B4', '#00E5FF', '#76FF03'];
        const count = this.reducedMotion ? 6 : 16;

        for (let i = 0; i < count; i++) {
            const angle = Math.random() * Math.PI * 2;
            const speed = Math.random() * 4 + 1.8;
            this.particles.push({
                x: x,
                y: y,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed - 1.2,
                size: Math.random() * 7 + 5,
                color: starColors[Math.floor(Math.random() * starColors.length)],
                alpha: 1,
                decay: 0.035,
                gravity: 0.1,
                shape: 'star',
                rotation: Math.random() * 360,
                vRot: (Math.random() - 0.5) * 12
            });
        }

        if (!this.isRunning) {
            this.isRunning = true;
            this.loop();
        }
    }

    // 3. Trái tim bay lên (Level 7)
    spawnFloatingHeartsAt(x, y) {
        this.init();
        if (!this.canvas || !this.ctx) return;

        const count = this.reducedMotion ? 4 : 10;
        for (let i = 0; i < count; i++) {
            const angle = (Math.random() - 0.5) * 1.5;
            this.particles.push({
                x: x + (Math.random() - 0.5) * 35,
                y: y + (Math.random() - 0.5) * 15,
                vx: Math.sin(angle) * 1.8,
                vy: -Math.random() * 3 - 1.8,
                size: Math.random() * 12 + 16,
                alpha: 1,
                decay: 0.022,
                shape: 'heart'
            });
        }

        if (!this.isRunning) {
            this.isRunning = true;
            this.loop();
        }
    }

    // 4. Nốt nhạc bay quanh tai khi uống nước (Level 5)
    spawnMusicNotesAt(x, y) {
        this.init();
        if (!this.canvas || !this.ctx) return;

        const noteSymbols = ['🎵', '🎶', '✨', '⭐'];
        const count = this.reducedMotion ? 3 : 8;
        for (let i = 0; i < count; i++) {
            this.particles.push({
                x: x + (Math.random() - 0.5) * 50,
                y: y + (Math.random() - 0.5) * 30,
                vx: (Math.random() - 0.5) * 2.5,
                vy: -Math.random() * 2.5 - 1.8,
                size: Math.random() * 8 + 18,
                symbol: noteSymbols[Math.floor(Math.random() * noteSymbols.length)],
                alpha: 1,
                decay: 0.025,
                shape: 'text'
            });
        }

        if (!this.isRunning) {
            this.isRunning = true;
            this.loop();
        }
    }

    loop() {
        if (!this.isRunning) return;

        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

        for (let i = this.particles.length - 1; i >= 0; i--) {
            const p = this.particles[i];
            p.x += p.vx;
            p.y += p.vy;
            if (p.gravity) p.vy += p.gravity;
            if (p.decay) p.alpha -= p.decay;
            if (p.vRot) p.rotation += p.vRot;

            if (p.alpha <= 0 || p.y > this.canvas.height + 25) {
                this.particles.splice(i, 1);
                continue;
            }

            this.ctx.save();
            this.ctx.globalAlpha = Math.max(0, p.alpha);

            if (p.shape === 'star') {
                this.ctx.fillStyle = p.color;
                this.drawStar(p.x, p.y, 5, p.size, p.size / 2, (p.rotation || 0) * Math.PI / 180);
            } else if (p.shape === 'rect') {
                this.ctx.fillStyle = p.color;
                this.ctx.translate(p.x, p.y);
                this.ctx.rotate((p.rotation || 0) * Math.PI / 180);
                this.ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
            } else if (p.shape === 'heart') {
                this.ctx.font = `${p.size}px sans-serif`;
                this.ctx.textAlign = 'center';
                this.ctx.textBaseline = 'middle';
                this.ctx.fillText('❤️', p.x, p.y);
            } else if (p.shape === 'text') {
                this.ctx.font = `${p.size}px sans-serif`;
                this.ctx.textAlign = 'center';
                this.ctx.textBaseline = 'middle';
                this.ctx.fillText(p.symbol, p.x, p.y);
            } else {
                this.ctx.fillStyle = p.color;
                this.ctx.beginPath();
                this.ctx.arc(p.x, p.y, p.size / 2, 0, Math.PI * 2);
                this.ctx.fill();
            }

            this.ctx.restore();
        }

        if (this.particles.length > 0) {
            this.animationFrame = requestAnimationFrame(() => this.loop());
        } else {
            this.isRunning = false;
        }
    }

    drawStar(cx, cy, spikes, outerRadius, innerRadius, angleOffset = 0) {
        let rot = Math.PI / 2 * 3 + angleOffset;
        let x = cx;
        let y = cy;
        const step = Math.PI / spikes;

        this.ctx.beginPath();
        this.ctx.moveTo(cx, cy - outerRadius);
        for (let i = 0; i < spikes; i++) {
            x = cx + Math.cos(rot) * outerRadius;
            y = cy + Math.sin(rot) * outerRadius;
            this.ctx.lineTo(x, y);
            rot += step;

            x = cx + Math.cos(rot) * innerRadius;
            y = cy + Math.sin(rot) * innerRadius;
            this.ctx.lineTo(x, y);
            rot += step;
        }
        this.ctx.lineTo(cx, cy - outerRadius);
        this.ctx.closePath();
        this.ctx.fill();
    }

    stop() {
        this.isRunning = false;
        if (this.animationFrame) {
            cancelAnimationFrame(this.animationFrame);
        }
        if (this.ctx && this.canvas) {
            this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
        }
        this.particles = [];
    }
}

window.effectsMgr = new KidEffectsManager();

/**
 * app.js - Main Controller for "Cùng Bé Bin Đi Máy Bay" (8 Levels)
 * Đồng bộ toàn diện 100% với HTML/CSS/Audio/Effects
 * Tuân thủ mô hình Sách Tương Tác Ba Mẹ Đọc Cho Bé (Parent-Co-Play)
 */

class KidFlightApp {
    constructor() {
        this.currentScreen = 1;
        this.totalScreens = 8;
        this.maxUnlockedLevel = 1;

        // Ngăn chặn duplicate event listeners khi quay lại màn
        this.levelInitialized = {
            1: false, 2: false, 3: false, 4: false,
            5: false, 6: false, 7: false, 8: false
        };

        // Trạng thái các Level
        this.level1Dressed = { shirt: false, pants: false, shoes: false };
        this.level2Packed = 0;
        this.level3Steps = { checkin: false, xrayCount: 0, gate: false };
        this.level4Completed = false;
        this.level5Belt = { inserted: false, earRelieved: false };
        this.level6Clouds = { c1: false, c2: false, c3: false, c4: false };
        this.level7Tasks = { volume: false, leg: false };
        this.level8State = { planeStopped: false, unbuckled: false, baggage: false };

        this.parentHoldStart = 0;
        this.parentHoldReqId = null;

        this.init();
    }

    init() {
        this.bindGlobalEvents();
        this.initLevel(1);
        this.showScreen(1);
    }

    // --- PARENT PROMPT API (HIỂN THỊ CÂU THOẠI TRÊN BIỂN BÁO BA MẸ ĐỌC) ---
    showParentPrompt(speaker, text, avatarEmoji = null) {
        if (window.dialogueMgr) {
            window.dialogueMgr.show(speaker, text, avatarEmoji);
        }
    }

    // --- NAVIGATION & STAGE LOCKING CONTROLLER ---
    unlockLevel(levelNum) {
        if (levelNum > this.maxUnlockedLevel && levelNum <= this.totalScreens) {
            this.maxUnlockedLevel = levelNum;
            const dot = document.querySelector(`.stage-dot[data-screen="${levelNum}"]`);
            if (dot) {
                dot.classList.remove('locked');
            }
        }
    }

    showScreen(screenNum) {
        if (screenNum < 1 || screenNum > this.totalScreens) return;

        // Dừng động cơ máy bay nếu rời Level 5
        if (this.currentScreen === 5 && screenNum !== 5) {
            if (window.audioMgr) window.audioMgr.stopEngineSound();
        }

        this.currentScreen = screenNum;
        this.unlockLevel(screenNum);

        // Cập nhật DOM screen
        document.querySelectorAll('.screen').forEach((scr, idx) => {
            if (idx + 1 === screenNum) {
                scr.classList.add('active');
            } else {
                scr.classList.remove('active');
            }
        });

        // Cập nhật Stage dots (chỉ mở khóa màn đã chơi hoặc hiện tại)
        document.querySelectorAll('.stage-dot').forEach((dot, idx) => {
            const level = idx + 1;
            dot.classList.remove('active', 'completed', 'locked');

            if (level === screenNum) {
                dot.classList.add('active');
            } else if (level < screenNum || level <= this.maxUnlockedLevel) {
                dot.classList.add('completed');
            } else {
                dot.classList.add('locked');
            }
        });

        // Khởi tạo sự kiện màn nếu chưa khởi tạo
        this.initLevel(screenNum);

        // Hiển thị lời thoại ban đầu chuẩn của màn chơi
        this.setInitialScreenDialogue(screenNum);
    }

    setInitialScreenDialogue(screenNum) {
        switch (screenNum) {
            case 1:
                this.showParentPrompt('Mẹ', '“Bin sắp đi máy bay rồi. Con chọn bộ đồ nào giúp Bin dễ vận động nhé!”', '👩');
                break;
            case 2:
                this.showParentPrompt('Bố', '“Bin mang gì đi máy bay nhỉ? Con xếp vali giúp Bin nhé!”', '👨');
                break;
            case 3:
                this.showParentPrompt('Mẹ', '“Đến chỗ kiểm tra an ninh rồi. Bin đi cùng Ba Mẹ và làm theo hướng dẫn nhé!”', '👩');
                break;
            case 4:
                this.showParentPrompt('Bố', '“Vé của Bin ghi số 03. Con tìm cổng số 03 nhé!”', '👨');
                break;
            case 5:
                this.showParentPrompt('Mẹ', '“Con giúp Bin cài dây an toàn nhé!”', '👩');
                break;
            case 6:
                this.showParentPrompt('Bin', '“Bin thấy đám mây giống hình gì nhỉ? Con nhìn cùng Bin nhé!”', '🧒');
                break;
            case 7:
                this.showParentPrompt('Mẹ', '“Trên máy bay mình nói nhỏ vừa đủ nghe nhé. Con giúp Bin nào!”', '👩');
                break;
            case 8:
                // Level 8: SAFETY BLOCKER - Máy bay chạy vào chỗ đỗ trước
                this.level8State.planeStopped = false;
                this.level8State.unbuckled = false;
                this.showParentPrompt('Bố', '“Máy bay đang chạy vào chỗ đỗ. Bin vẫn ngồi yên và giữ dây an toàn nhé!”', '👨');

                const unbuckleBtn = document.getElementById('unbuckle-latch-btn');
                if (unbuckleBtn) {
                    unbuckleBtn.setAttribute('disabled', 'true');
                    unbuckleBtn.style.opacity = '0.6';
                    unbuckleBtn.style.borderColor = '#FF5252';
                    unbuckleBtn.innerHTML = '<span>⏳ Máy bay đang chạy vào bãi đỗ...</span>';
                }

                setTimeout(() => {
                    this.level8State.planeStopped = true;
                    if (unbuckleBtn) {
                        unbuckleBtn.removeAttribute('disabled');
                        unbuckleBtn.style.opacity = '1';
                        unbuckleBtn.style.borderColor = '#00E676';
                        unbuckleBtn.innerHTML = '<span>🔓 Máy bay đã dừng hẳn — Mở dây an toàn</span>';
                    }
                    this.showParentPrompt('Mẹ', '“Máy bay dừng hẳn rồi. Bây giờ mình mới mở dây nhé!”', '👩');
                }, 2600);
                break;
        }
    }

    // --- GLOBAL EVENTS & CỔNG BA MẸ CONTROLLER ---
    bindGlobalEvents() {
        const parentBtn = document.getElementById('btn-parent-gate');
        const holdCircle = document.getElementById('parent-ring-circle');
        const modal = document.getElementById('parent-modal');
        const closeModalBtn = document.getElementById('btn-close-parent');

        // Cổng Ba Mẹ: Giữ 3 giây
        if (parentBtn && holdCircle) {
            const startHold = (e) => {
                e.preventDefault();
                this.parentHoldStart = Date.now();
                const totalHold = 3000;

                const updateRing = () => {
                    const elapsed = Date.now() - this.parentHoldStart;
                    const progress = Math.min(1, elapsed / totalHold);
                    const offset = 175 - (175 * progress);
                    holdCircle.style.strokeDashoffset = offset;

                    if (progress >= 1) {
                        if (window.audioMgr) window.audioMgr.playTing();
                        modal.classList.add('open');
                        resetHold();
                    } else {
                        this.parentHoldReqId = requestAnimationFrame(updateRing);
                    }
                };

                this.parentHoldReqId = requestAnimationFrame(updateRing);
            };

            const resetHold = () => {
                if (this.parentHoldReqId) cancelAnimationFrame(this.parentHoldReqId);
                holdCircle.style.strokeDashoffset = 175;
            };

            parentBtn.addEventListener('pointerdown', startHold);
            parentBtn.addEventListener('pointerup', resetHold);
            parentBtn.addEventListener('pointerleave', resetHold);
            parentBtn.addEventListener('pointercancel', resetHold);
        }

        if (closeModalBtn && modal) {
            closeModalBtn.addEventListener('click', () => {
                if (window.audioMgr) window.audioMgr.playPop();
                modal.classList.remove('open');
            });
        }

        // Tùy chỉnh trong Cổng Ba Mẹ
        const volSlider = document.getElementById('setting-volume');
        if (volSlider) {
            volSlider.addEventListener('input', (e) => {
                if (window.audioMgr) window.audioMgr.volume = parseFloat(e.target.value);
            });
        }

        const motionToggle = document.getElementById('setting-reduced-motion');
        if (motionToggle) {
            motionToggle.addEventListener('change', (e) => {
                if (window.effectsMgr) window.effectsMgr.reducedMotion = e.target.checked;
            });
        }

        const resetBtn = document.getElementById('btn-reset-app');
        if (resetBtn) {
            resetBtn.addEventListener('click', () => {
                window.location.reload();
            });
        }

        // Nút chọn nhanh màn chơi trong Cổng Ba Mẹ (Ba Mẹ được quyền nhảy tự do)
        document.querySelectorAll('.jump-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const target = parseInt(btn.getAttribute('data-level'), 10);
                if (target) {
                    if (window.audioMgr) window.audioMgr.playPop();
                    modal.classList.remove('open');
                    this.unlockLevel(target);
                    this.showScreen(target);
                }
            });
        });

        // Stage dots điều hướng: Chỉ cho phép click màn hiện tại và màn đã mở khóa
        document.querySelectorAll('.stage-dot').forEach((dot) => {
            dot.addEventListener('click', () => {
                const targetScreen = parseInt(dot.getAttribute('data-screen'), 10);
                if (!dot.classList.contains('locked') && targetScreen && targetScreen <= this.maxUnlockedLevel) {
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.showScreen(targetScreen);
                }
            });
        });
    }

    initLevel(levelNum) {
        if (this.levelInitialized[levelNum]) return;
        this.levelInitialized[levelNum] = true;

        switch (levelNum) {
            case 1: this.initLevel1(); break;
            case 2: this.initLevel2(); break;
            case 3: this.initLevel3(); break;
            case 4: this.initLevel4(); break;
            case 5: this.initLevel5(); break;
            case 6: this.initLevel6(); break;
            case 7: this.initLevel7(); break;
            case 8: this.initLevel8(); break;
        }
    }

    // ==========================================================================
    // LEVEL 1: TRANG PHỤC THOẢI MÁI (#screen-1 [data-clothing-item="true"])
    // ==========================================================================
    initLevel1() {
        const clothesTiles = document.querySelectorAll('#screen-1 [data-clothing-item="true"]');
        const binAvatar = document.getElementById('bin-dress-target');
        const btnNext1 = document.getElementById('btn-next-level-1');

        const tryDressItem = (tile) => {
            if (tile.classList.contains('worn')) return;
            const isFit = tile.getAttribute('data-fit') === 'soft';
            const type = tile.getAttribute('data-type');
            const binRect = binAvatar.getBoundingClientRect();

            if (isFit) {
                tile.classList.add('worn');
                tile.style.display = 'none';

                if (type === 'shirt') {
                    document.getElementById('bin-slot-shirt').textContent = '👕';
                    this.level1Dressed.shirt = true;
                } else if (type === 'pants') {
                    document.getElementById('bin-slot-pants').textContent = '🩳';
                    this.level1Dressed.pants = true;
                } else if (type === 'shoes') {
                    document.getElementById('bin-slot-shoes').textContent = '👟';
                    this.level1Dressed.shoes = true;
                }

                if (window.effectsMgr) {
                    window.effectsMgr.burstStarsAt(binRect.left + binRect.width / 2, binRect.top + binRect.height / 2);
                }
                if (window.audioMgr) window.audioMgr.playTing();

                this.showParentPrompt('Mẹ', '“Đúng rồi! Bộ này mềm và dễ vận động.”', '👩');

                if (this.level1Dressed.shirt && this.level1Dressed.pants && this.level1Dressed.shoes) {
                    binAvatar.classList.add('gentle-bounce');
                    this.showParentPrompt('Mẹ', '“Bin mặc đồ xong rồi, cùng đi xếp vali nào!”', '👩');
                    this.unlockLevel(2);
                    if (btnNext1) {
                        btnNext1.classList.remove('hidden');
                        btnNext1.classList.add('pop-in');
                    }
                }
            } else {
                tile.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
                tile.style.transform = 'translate(0px, 0px)';
                if (window.audioMgr) window.audioMgr.playBoing();
                this.showParentPrompt('Bố', '“Món này hơi bất tiện. Con thử món khác nhé!”', '👨');
            }
        };

        clothesTiles.forEach(tile => {
            let startX = 0, startY = 0;
            let isDragging = false;

            const onDown = (e) => {
                if (tile.classList.contains('worn')) return;
                isDragging = true;
                tile.setPointerCapture(e.pointerId);
                startX = e.clientX;
                startY = e.clientY;
                tile.style.zIndex = '999';
            };

            const onMove = (e) => {
                if (!isDragging) return;
                const dx = e.clientX - startX;
                const dy = e.clientY - startY;
                tile.style.transform = `translate(${dx}px, ${dy}px) scale(1.18)`;
            };

            const onUp = (e) => {
                if (!isDragging) return;
                isDragging = false;
                tile.releasePointerCapture(e.pointerId);

                const tileRect = tile.getBoundingClientRect();
                const binRect = binAvatar.getBoundingClientRect();

                const isOver = !(
                    tileRect.right < binRect.left ||
                    tileRect.left > binRect.right ||
                    tileRect.bottom < binRect.top ||
                    tileRect.top > binRect.bottom
                );

                if (isOver) {
                    tryDressItem(tile);
                } else {
                    tile.style.transition = 'transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)';
                    tile.style.transform = 'translate(0px, 0px)';
                }
            };

            tile.addEventListener('pointerdown', onDown);
            tile.addEventListener('pointermove', onMove);
            tile.addEventListener('pointerup', onUp);
            tile.addEventListener('pointercancel', onUp);

            tile.addEventListener('click', () => {
                if (!tile.classList.contains('worn')) {
                    tryDressItem(tile);
                }
            });
        });

        if (btnNext1) {
            btnNext1.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(2);
            };
        }
    }

    // ==========================================================================
    // LEVEL 2: CHIẾC VALI KỲ DIỆU (#screen-2 [data-luggage-item="true"])
    // ==========================================================================
    initLevel2() {
        const luggageItems = document.querySelectorAll('#screen-2 [data-luggage-item="true"]');
        const suitcase = document.getElementById('suitcase-target-lvl2');
        const suitcaseInner = document.getElementById('suitcase-inner-lvl2');
        const btnNext2 = document.getElementById('btn-next-level-2');

        const tryPackLuggage = (item) => {
            if (item.classList.contains('packed')) return;
            const category = item.getAttribute('data-category');
            const suitcaseRect = suitcase.getBoundingClientRect();

            if (category === 'PACK') {
                item.classList.add('packed');
                item.style.display = 'none';

                const iconSpan = document.createElement('span');
                iconSpan.textContent = item.querySelector('.item-icon').textContent;
                iconSpan.style.fontSize = '34px';
                iconSpan.className = 'pop-in';
                suitcaseInner.appendChild(iconSpan);

                this.level2Packed++;

                if (window.effectsMgr) {
                    window.effectsMgr.burstStarsAt(suitcaseRect.left + suitcaseRect.width / 2, suitcaseRect.top + suitcaseRect.height / 2);
                }
                if (window.audioMgr) window.audioMgr.playTing();

                this.showParentPrompt('Mẹ', '“Ừ! Món này mình xếp vào vali nhé.”', '👩');

                if (this.level2Packed >= 3) {
                    this.showParentPrompt('Mẹ', '“Vali của Bin đã sẵn sàng rồi! Cùng đến sân bay thôi!”', '👩');
                    this.unlockLevel(3);
                    if (btnNext2) {
                        btnNext2.classList.remove('hidden');
                        btnNext2.classList.add('pop-in');
                    }
                }
            } else if (category === 'ASK_PARENT') {
                item.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
                item.style.transform = 'translate(0px, 0px)';
                if (window.audioMgr) window.audioMgr.playPop();
                this.showParentPrompt('Bố', '“Món này mình hỏi Ba Mẹ trước nhé!”', '👨');
            } else {
                // LEAVE_HOME
                item.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
                item.style.transform = 'translate(0px, 0px)';
                if (window.audioMgr) window.audioMgr.playBoing();
                this.showParentPrompt('Bố', '“Món này để Ba Mẹ giúp mình xử lý nhé.”', '👨');
            }
        };

        luggageItems.forEach(item => {
            let startX = 0, startY = 0;
            let isDragging = false;

            const onDown = (e) => {
                if (item.classList.contains('packed')) return;
                isDragging = true;
                item.setPointerCapture(e.pointerId);
                startX = e.clientX;
                startY = e.clientY;
                item.style.zIndex = '999';
            };

            const onMove = (e) => {
                if (!isDragging) return;
                const dx = e.clientX - startX;
                const dy = e.clientY - startY;
                item.style.transform = `translate(${dx}px, ${dy}px) scale(1.18)`;
            };

            const onUp = (e) => {
                if (!isDragging) return;
                isDragging = false;
                item.releasePointerCapture(e.pointerId);

                const itemRect = item.getBoundingClientRect();
                const suitcaseRect = suitcase.getBoundingClientRect();

                const isOver = !(
                    itemRect.right < suitcaseRect.left ||
                    itemRect.left > suitcaseRect.right ||
                    itemRect.bottom < suitcaseRect.top ||
                    itemRect.top > suitcaseRect.bottom
                );

                if (isOver) {
                    tryPackLuggage(item);
                } else {
                    item.style.transition = 'transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)';
                    item.style.transform = 'translate(0px, 0px)';
                }
            };

            item.addEventListener('pointerdown', onDown);
            item.addEventListener('pointermove', onMove);
            item.addEventListener('pointerup', onUp);
            item.addEventListener('pointercancel', onUp);

            item.addEventListener('click', () => {
                if (!item.classList.contains('packed')) {
                    tryPackLuggage(item);
                }
            });
        });

        if (btnNext2) {
            btnNext2.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(3);
            };
        }
    }

    // ==========================================================================
    // LEVEL 3: KIỂM TRA AN NINH
    // ==========================================================================
    initLevel3() {
        const passCard = document.getElementById('pass-card-lvl3');
        const stampBadge = document.getElementById('stamp-badge-lvl3');
        const xrayBoxes = document.querySelectorAll('#screen-3 .xray-tap-box');
        const gate = document.getElementById('gate-detector-lvl3');
        const lamps = document.querySelectorAll('#screen-3 .gate-lamp-led');
        const binWalker = document.getElementById('bin-walker-lvl3');
        const btnNext3 = document.getElementById('btn-next-level-3');

        // Bước 1: Kiểm tra vé
        if (passCard) {
            passCard.onclick = () => {
                if (this.level3Steps.checkin) return;
                this.level3Steps.checkin = true;
                if (stampBadge) stampBadge.classList.add('stamped');
                if (window.audioMgr) window.audioMgr.playStamp();
                this.showParentPrompt('Tiếp viên', '“Vé của Bin xong rồi! Giờ soi chiếu vali nhé.”', '👩‍✈️');
                this.checkLevel3Completion();
            };
        }

        // Bước 2: Chạm 3 khối máy soi X-quang
        xrayBoxes.forEach(box => {
            box.onclick = () => {
                if (box.getAttribute('data-revealed') === 'true') return;
                box.setAttribute('data-revealed', 'true');
                box.textContent = box.getAttribute('data-item');
                box.style.background = '#FFF9C4';
                this.level3Steps.xrayCount++;

                if (window.audioMgr) window.audioMgr.playTing();
                if (window.effectsMgr) {
                    const r = box.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }

                if (this.level3Steps.xrayCount >= 3) {
                    this.showParentPrompt('Mẹ', '“Vali của Bin an toàn rồi! Chạm để Bin qua cổng nhé.”', '👩');
                    this.checkLevel3Completion();
                }
            };
        });

        // Bước 3: Cổng an ninh
        if (gate) {
            gate.onclick = () => {
                if (this.level3Steps.gate) return;
                this.level3Steps.gate = true;

                lamps.forEach(l => l.classList.add('green-flash'));
                if (binWalker) binWalker.style.transform = 'translateY(-18px) scale(1.15)';

                if (window.audioMgr) window.audioMgr.playBeepBoop();
                this.showParentPrompt('Mẹ', '“Bíp boong! Bin qua cửa an toàn rồi!”', '👩');
                this.checkLevel3Completion();
            };
        }

        if (btnNext3) {
            btnNext3.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(4);
            };
        }
    }

    checkLevel3Completion() {
        const btnNext3 = document.getElementById('btn-next-level-3');
        if (this.level3Steps.checkin && this.level3Steps.xrayCount >= 3 && this.level3Steps.gate) {
            this.unlockLevel(4);
            if (btnNext3) {
                btnNext3.classList.remove('hidden');
                btnNext3.classList.add('pop-in');
            }
        }
    }

    // ==========================================================================
    // LEVEL 4: RA CỔNG BAY (TẬP TRUNG TÌM CỔNG 03)
    // ==========================================================================
    initLevel4() {
        const gatePillars = document.querySelectorAll('#screen-4 .gate-pillar');
        const btnNext4 = document.getElementById('btn-next-level-4');

        gatePillars.forEach(pillar => {
            pillar.onclick = () => {
                const targetGate = pillar.getAttribute('data-gate');

                if (targetGate === '03') {
                    this.level4Completed = true;
                    pillar.classList.add('matched');

                    if (window.effectsMgr) {
                        const r = pillar.getBoundingClientRect();
                        window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                    }
                    if (window.audioMgr) window.audioMgr.playConnect();

                    this.showParentPrompt('Tiếp viên', '“Đúng Cổng 03 rồi! Chào mừng Bin lên máy bay!”', '👩‍✈️');
                    this.unlockLevel(5);

                    if (btnNext4) {
                        btnNext4.classList.remove('hidden');
                        btnNext4.classList.add('pop-in');
                    }
                } else {
                    if (window.audioMgr) window.audioMgr.playBoing();
                    this.showParentPrompt('Bố', '“Chưa đúng số trên vé rồi, con tìm lại nhé!”', '👨');
                }
            };
        });

        if (btnNext4) {
            btnNext4.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(5);
            };
        }
    }

    // ==========================================================================
    // LEVEL 5: HIỆP SĨ ĐAI AN TOÀN & UỐNG NƯỚC
    // ==========================================================================
    initLevel5() {
        const strapLeft = document.getElementById('seatbelt-strap-lvl5');
        const puzzleBox = document.getElementById('seatbelt-puzzle-lvl5');
        const safetySign = document.getElementById('safety-sign-lvl5');
        const knightCape = document.getElementById('bin-knight-cape');
        const btnWater = document.getElementById('btn-drink-water-lvl5');
        const earWaves = document.querySelectorAll('#screen-5 .ear-soundwave');
        const btnNext5 = document.getElementById('btn-next-level-5');

        const tryBuckleBelt = () => {
            if (this.level5Belt.inserted) return;
            this.level5Belt.inserted = true;
            puzzleBox.classList.add('seatbelt-buckled');

            if (safetySign) safetySign.classList.add('green-safe');
            if (knightCape) knightCape.classList.add('active');

            if (window.audioMgr) {
                window.audioMgr.playClack();
                window.audioMgr.startEngineSound(0.22);
            }

            if (window.effectsMgr) {
                const r = puzzleBox.getBoundingClientRect();
                window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
            }

            this.showParentPrompt('Mẹ', '“CẠCH! Dây an toàn chắc chắn rồi!”', '👩');

            setTimeout(() => {
                earWaves.forEach(w => w.classList.remove('hidden'));
                if (btnWater) btnWater.classList.remove('hidden');
                this.showParentPrompt('Mẹ', '“Tai Bin hơi khó chịu. Bin uống một ngụm nước nhé.”', '👩');
            }, 3000);
        };

        if (strapLeft && puzzleBox) {
            let isDragging = false;
            let startX = 0;

            const onDown = (e) => {
                if (this.level5Belt.inserted) return;
                isDragging = true;
                strapLeft.setPointerCapture(e.pointerId);
                startX = e.clientX;
            };

            const onMove = (e) => {
                if (!isDragging || this.level5Belt.inserted) return;
                const dx = Math.max(0, Math.min(45, e.clientX - startX));
                strapLeft.style.transform = `translateX(${dx}px)`;

                if (dx >= 35) {
                    tryBuckleBelt();
                }
            };

            const onUp = (e) => {
                if (!isDragging) return;
                isDragging = false;
                strapLeft.releasePointerCapture(e.pointerId);
                if (!this.level5Belt.inserted) {
                    strapLeft.style.transform = 'translateX(0px)';
                }
            };

            strapLeft.addEventListener('pointerdown', onDown);
            strapLeft.addEventListener('pointermove', onMove);
            strapLeft.addEventListener('pointerup', onUp);

            puzzleBox.addEventListener('click', () => {
                tryBuckleBelt();
            });
        }

        if (btnWater) {
            btnWater.onclick = () => {
                if (this.level5Belt.earRelieved) return;
                this.level5Belt.earRelieved = true;

                earWaves.forEach(w => w.classList.add('hidden'));

                if (window.effectsMgr) {
                    const binHead = document.getElementById('bin-seat-head');
                    if (binHead) {
                        const r = binHead.getBoundingClientRect();
                        window.effectsMgr.spawnMusicNotesAt(r.left + r.width / 2, r.top);
                    }
                }

                if (window.audioMgr) window.audioMgr.playDrinkWater();
                this.showParentPrompt('Bin', '“Tai Bin dễ chịu hơn rồi!”', '🧒');
                this.unlockLevel(6);

                if (btnNext5) {
                    btnNext5.classList.remove('hidden');
                    btnNext5.classList.add('pop-in');
                }
            };
        }

        if (btnNext5) {
            btnNext5.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(6);
            };
        }
    }

    // ==========================================================================
    // LEVEL 6: NGẮM MÂY BIẾN HÌNH (LỜI THOẠI MỞ)
    // ==========================================================================
    initLevel6() {
        const cloudTiles = document.querySelectorAll('#screen-6 .morph-cloud-tile');
        const btnNext6 = document.getElementById('btn-next-level-6');

        cloudTiles.forEach(tile => {
            tile.onclick = () => {
                if (tile.classList.contains('morphed')) return;
                tile.classList.add('morphed');

                const morphType = tile.getAttribute('data-morph');
                const icon = tile.querySelector('.cloud-icon');
                const label = tile.querySelector('.cloud-label');

                if (morphType === 'bunny') {
                    icon.textContent = '🐰';
                    label.textContent = 'Chú thỏ';
                    this.level6Clouds.c1 = true;
                    this.showParentPrompt('Bin', '“Bin thấy giống chú thỏ! Còn con thấy giống gì?”', '🧒');
                } else if (morphType === 'car') {
                    icon.textContent = '🚗';
                    label.textContent = 'Chiếc ô tô';
                    this.level6Clouds.c2 = true;
                    this.showParentPrompt('Bin', '“Bin thấy giống ô tô chạy! Còn con thấy giống gì?”', '🧒');
                } else if (morphType === 'watermelon') {
                    icon.textContent = '🍉';
                    label.textContent = 'Miếng dưa hấu';
                    this.level6Clouds.c3 = true;
                    this.showParentPrompt('Bin', '“Bin thấy giống miếng dưa hấu! Còn con thấy giống gì?”', '🧒');
                } else if (morphType === 'bear') {
                    icon.textContent = '🐻';
                    label.textContent = 'Chú gấu';
                    this.level6Clouds.c4 = true;
                    this.showParentPrompt('Bin', '“Bin thấy giống chú gấu vẫy tay! Còn con thấy giống gì?”', '🧒');
                }

                if (window.effectsMgr) {
                    const r = tile.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }
                if (window.audioMgr) window.audioMgr.playBling();

                if (this.level6Clouds.c1 && this.level6Clouds.c2 && this.level6Clouds.c3 && this.level6Clouds.c4) {
                    this.unlockLevel(7);
                    if (btnNext6) {
                        btnNext6.classList.remove('hidden');
                        btnNext6.classList.add('pop-in');
                    }
                }
            };
        });

        if (btnNext6) {
            btnNext6.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(7);
            };
        }
    }

    // ==========================================================================
    // LEVEL 7: MÓN QUÀ LỊCH SỰ (3 NÚT ÂM LƯỢNG TRỰC QUAN)
    // ==========================================================================
    initLevel7() {
        const emotionBtns = document.querySelectorAll('#screen-7 .volume-emotion-btn');
        const legTarget = document.getElementById('bin-leg-target');
        const legLabel = document.getElementById('leg-status-label');
        const btnNext7 = document.getElementById('btn-next-level-7');

        emotionBtns.forEach(btn => {
            btn.onclick = () => {
                emotionBtns.forEach(b => b.classList.remove('selected'));
                btn.classList.add('selected');
                const level = btn.getAttribute('data-level');

                if (level === 'loud') {
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.showParentPrompt('Mẹ', '“Ơ, hơi to rồi. Con thử nhỏ hơn nhé!”', '👩');
                } else if (level === 'medium') {
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.showParentPrompt('Mẹ', '“Nhỏ hơn một chút nữa nhé!”', '👩');
                } else if (level === 'whisper') {
                    this.level7Tasks.volume = true;
                    if (window.effectsMgr) {
                        const r = btn.getBoundingClientRect();
                        window.effectsMgr.spawnFloatingHeartsAt(r.left + r.width / 2, r.top);
                    }
                    if (window.audioMgr) window.audioMgr.playTing();
                    this.showParentPrompt('Bin', '“Đúng rồi! Mình nói nhỏ vừa đủ nghe nhé.”', '🧒');
                    this.checkLevel7Completion();
                }
            };
        });

        if (legTarget) {
            legTarget.onclick = () => {
                if (this.level7Tasks.leg) return;
                this.level7Tasks.leg = true;
                legTarget.style.transform = 'translateY(16px)';
                if (legLabel) legLabel.textContent = 'Chân Bin đã thu lại ngay ngắn ✓';

                if (window.effectsMgr) {
                    const r = legTarget.getBoundingClientRect();
                    window.effectsMgr.spawnFloatingHeartsAt(r.left + r.width / 2, r.top);
                }

                if (window.audioMgr) window.audioMgr.playTing();
                this.showParentPrompt('Bố', '“Bin ngồi ngoan, không đạp ghế trước!”', '👨');
                this.checkLevel7Completion();
            };
        }

        if (btnNext7) {
            btnNext7.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(8);
            };
        }
    }

    checkLevel7Completion() {
        const btnNext7 = document.getElementById('btn-next-level-7');
        if (this.level7Tasks.volume && this.level7Tasks.leg) {
            this.unlockLevel(8);
            if (btnNext7) {
                btnNext7.classList.remove('hidden');
                btnNext7.classList.add('pop-in');
            }
        }
    }

    // ==========================================================================
    // LEVEL 8: LẤY VALI & NHẬN PHẦN THƯỞNG (SAFETY BLOCKER)
    // ==========================================================================
    initLevel8() {
        const unbuckleLatch = document.getElementById('unbuckle-latch-btn');
        const baggageCarousel = document.getElementById('baggage-carousel-lvl8');
        const bags = document.querySelectorAll('#screen-8 .carousel-bag-tile');
        const medalModal = document.getElementById('golden-medal-modal');
        const btnReplay = document.getElementById('btn-replay-adventure');

        // Bước 1: Máy bay dừng hẳn mới cho phép mở đai
        if (unbuckleLatch) {
            unbuckleLatch.onclick = () => {
                if (!this.level8State.planeStopped) {
                    this.showParentPrompt('Bố', '“Máy bay đang chạy vào chỗ đỗ. Bin vẫn ngồi yên và giữ dây an toàn nhé!”', '👨');
                    return;
                }

                if (this.level8State.unbuckled) return;
                this.level8State.unbuckled = true;
                unbuckleLatch.innerHTML = '<span>🔓 Đai an toàn đã mở ✓</span>';
                unbuckleLatch.style.borderColor = '#00E676';

                if (window.audioMgr) window.audioMgr.playUnbuckle();
                this.showParentPrompt('Bố', '“Con tìm chiếc vali đỏ có hình gấu của Bin nhé!”', '👨');

                if (baggageCarousel) baggageCarousel.classList.remove('hidden');
            };
        }

        // Bước 2: Bắt đúng vali đỏ dán hình gấu
        bags.forEach(bag => {
            bag.onclick = () => {
                if (!this.level8State.unbuckled) {
                    this.showParentPrompt('Mẹ', '“Máy bay dừng hẳn rồi. Bây giờ mình mới mở dây an toàn nhé!”', '👩');
                    return;
                }

                const isBinBag = bag.getAttribute('data-is-bin') === 'true';

                if (isBinBag) {
                    this.level8State.baggage = true;
                    bag.style.transform = 'scale(1.4) translateY(-18px)';
                    const track = document.querySelector('.carousel-suitcases-track');
                    if (track) track.classList.add('paused');

                    if (window.effectsMgr) {
                        window.effectsMgr.startCelebrationFireworks(3000);
                    }

                    if (window.audioMgr) window.audioMgr.playFanfare();
                    this.showParentPrompt('Mẹ', '“Hoan hô! Bin tìm đúng vali rồi!”', '👩');

                    setTimeout(() => {
                        if (medalModal) medalModal.classList.add('show');
                    }, 1200);
                } else {
                    if (window.audioMgr) window.audioMgr.playBoing();
                    this.showParentPrompt('Bố', '“Vali của bạn khác rồi, con tìm chiếc màu đỏ dán hình gấu nhé!”', '👨');
                }
            };
        });

        if (btnReplay) {
            btnReplay.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                window.location.reload();
            };
        }
    }
}

document.addEventListener('DOMContentLoaded', () => {
    window.kidFlightApp = new KidFlightApp();
});

/* ==========================================================================
   CÙNG BÉ BIN ĐI MÁY BAY - RICH COLORFUL 3D TYCOON DESIGN SYSTEM
   - Font Offline Fallback: Nunito -> Arial Rounded MT Bold -> system-ui -> sans-serif
   - Tươi sáng, độ bão hòa cao, bo tròn đồ chơi, viền đáy 3D đậm, đổ bóng đa tầng
   - Mô hình Parent-Co-Play: Chữ to rõ ràng $\ge 22px$, giao diện tương tác cực đại
   ========================================================================== */

:root {
    --color-sky-blue: #29B6F6;
    --color-sky-deep: #0288D1;
    --color-sun-yellow: #FFD54F;
    --color-sun-orange: #FF9800;
    --color-candy-red: #FF5252;
    --color-candy-red-deep: #D50000;
    --color-mint-green: #69F0AE;
    --color-emerald: #00E676;
    --color-royal-blue: #1976D2;
    --color-purple: #BA68C8;
    --color-warm-wood: #8D6E63;
    --text-dark: #1A237E;
    --text-muted: #455A64;
    --shadow-chunky: 0 8px 0 rgba(0, 0, 0, 0.16), 0 16px 28px rgba(0, 0, 0, 0.12);
    --shadow-glow: 0 0 25px rgba(255, 213, 79, 0.8);
    --radius-toy: 32px;
    --radius-round: 9999px;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    -webkit-tap-highlight-color: transparent;
    user-select: none;
    -webkit-user-select: none;
}

body, html {
    width: 100%;
    height: 100%;
    overflow: hidden;
    font-family: "Nunito", "Arial Rounded MT Bold", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: linear-gradient(135deg, #4FC3F7 0%, #81D4FA 35%, #FFE082 70%, #FF8A65 100%);
    color: var(--text-dark);
    touch-action: manipulation;
}

#app-root {
    width: 100vw;
    height: 100vh;
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
}

#effects-canvas {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1000;
}

/* ==========================================================================
   TOP BAR: 8 STAGE ICONS RỰC RỠ & CỔNG BA MẸ
   ========================================================================== */
.top-nav {
    height: 68px;
    padding: 8px 16px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    z-index: 50;
}

.stage-indicators {
    display: flex;
    gap: 8px;
    background: rgba(255, 255, 255, 0.94);
    backdrop-filter: blur(12px);
    padding: 6px 14px;
    border-radius: var(--radius-round);
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.12);
    border: 3px solid #FFF;
}

.stage-dot {
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: #ECEFF1;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    box-shadow: inset 0 -4px 0 #CFD8DC;
    border: none;
}

.stage-dot.active {
    background: linear-gradient(180deg, #FFEB3B 0%, #FFC107 100%);
    transform: scale(1.2);
    box-shadow: 0 6px 16px rgba(255, 193, 7, 0.5), inset 0 -4px 0 #FF8F00;
}

.stage-dot.completed {
    background: linear-gradient(180deg, #69F0AE 0%, #00E676 100%);
    box-shadow: inset 0 -4px 0 #00BFA5;
}

.stage-dot.locked {
    opacity: 0.38;
    cursor: not-allowed;
    filter: grayscale(0.85);
}

/* NÚT BẤM BILLIONAIR 3D CHUNKY */
.tycoon-btn {
    min-width: 60px;
    min-height: 52px;
    padding: 10px 22px;
    border: none;
    border-radius: var(--radius-round);
    background: #FFFFFF;
    color: var(--text-dark);
    font-weight: 900;
    font-size: 18px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    cursor: pointer;
    box-shadow: 0 7px 0 #B0BEC5, 0 12px 20px rgba(0, 0, 0, 0.15);
    transition: all 0.12s ease;
    touch-action: manipulation;
}

.tycoon-btn:active:not(:disabled) {
    transform: translateY(5px);
    box-shadow: 0 2px 0 #B0BEC5, 0 4px 8px rgba(0, 0, 0, 0.1);
}

.tycoon-btn:disabled {
    cursor: not-allowed;
    opacity: 0.6;
    filter: grayscale(0.3);
}

.tycoon-btn-primary {
    background: linear-gradient(180deg, #FFD54F 0%, #FFA000 100%);
    color: #4E342E;
    box-shadow: 0 7px 0 #E65100, 0 12px 22px rgba(230, 81, 0, 0.35);
}

.tycoon-btn-primary:active:not(:disabled) {
    box-shadow: 0 2px 0 #E65100;
}

.tycoon-btn-green {
    background: linear-gradient(180deg, #69F0AE 0%, #00E676 100%);
    color: #004D40;
    box-shadow: 0 7px 0 #00897B, 0 12px 22px rgba(0, 137, 123, 0.35);
}

.tycoon-btn-green:active:not(:disabled) {
    box-shadow: 0 2px 0 #00897B;
}

/* Cổng Ba Mẹ: Vòng giữ 3 giây */
.parent-gate-btn {
    position: relative;
    overflow: hidden;
}

.parent-hold-ring {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    transform: rotate(-90deg);
}

.parent-hold-ring circle {
    fill: none;
    stroke: #FF5722;
    stroke-width: 5;
    stroke-dasharray: 175;
    stroke-dashoffset: 175;
    transition: stroke-dashoffset 0.1s linear;
}

/* ==========================================================================
   BIỂN BÁO LỜI THOẠI BA MẸ ĐỌC (PARENT PROMPT SIGNBOARD)
   - Chữ to $\ge 22px$, dễ đọc trong 2 giây, rực rỡ phong cách BillionAir
   ========================================================================== */
.parent-prompt-container {
    width: 100%;
    max-width: 860px;
    margin: 4px auto 10px auto;
    padding: 0 16px;
    z-index: 40;
}

.parent-prompt-signboard {
    background: linear-gradient(135deg, #FFFFFF 0%, #FFFDE7 100%);
    border-radius: 28px;
    padding: 12px 24px;
    border: 4px solid #FFCA28;
    box-shadow: 0 8px 0 #FFA000, var(--shadow-chunky);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    text-align: center;
    position: relative;
}

.prompt-icon-badge {
    font-size: 34px;
    flex-shrink: 0;
    animation: gentle-sway 2.5s infinite;
}

.prompt-speech-text {
    font-size: 23px;
    font-weight: 900;
    color: #1A237E;
    line-height: 1.35;
    text-shadow: 0 1px 0 rgba(255,255,255,0.8);
}

/* ==========================================================================
   SCREENS VIEWPORT & THEMED BACKGROUNDS (8 MÀN CHƠI)
   ========================================================================== */
.screens-viewport {
    flex: 1;
    position: relative;
    width: 100%;
    height: calc(100vh - 150px);
    overflow: hidden;
}

.screen {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    visibility: hidden;
    transform: scale(0.96) translateY(20px);
    transition: opacity 0.35s ease, transform 0.35s cubic-bezier(0.34, 1.25, 0.64, 1), visibility 0.35s;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 6px 16px 20px 16px;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    border-radius: 36px;
}

.screen.active {
    opacity: 1;
    visibility: visible;
    transform: scale(1) translateY(0);
}

#screen-1 {
    background: radial-gradient(circle at center, #FFF9C4 0%, #FFE082 50%, #FFCC80 100%);
}

#screen-2 {
    background: radial-gradient(circle at center, #FFF3E0 0%, #FFE0B2 50%, #FFAB91 100%);
}

#screen-3 {
    background: radial-gradient(circle at center, #E0F7FA 0%, #B2EBF2 50%, #80DEEA 100%);
}

#screen-4 {
    background: radial-gradient(circle at center, #E1F5FE 0%, #B3E5FC 50%, #81D4FA 100%);
}

#screen-5 {
    background: radial-gradient(circle at center, #E8EAF6 0%, #C5CAE9 50%, #9FA8DA 100%);
}

#screen-6 {
    background: radial-gradient(circle at center, #E1F5FE 0%, #81D4FA 50%, #29B6F6 100%);
}

#screen-7 {
    background: radial-gradient(circle at center, #EDE7F6 0%, #D1C4E9 50%, #B39DDB 100%);
}

#screen-8 {
    background: radial-gradient(circle at center, #FFFDE7 0%, #FFF59D 50%, #FFE082 100%);
}

.screen.has-bg-slice {
    background-size: cover !important;
    background-position: center !important;
}

/* ==========================================================================
   LEVEL 1: TRANG PHỤC THOẢI MÁI
   ========================================================================== */
.wardrobe-arena {
    width: 100%;
    max-width: 900px;
    display: grid;
    grid-template-columns: 1.3fr 1fr;
    gap: 20px;
    align-items: center;
}

.wardrobe-cabinet {
    background: linear-gradient(180deg, #FFE082 0%, #FFCA28 100%);
    border: 6px solid #FFA000;
    border-radius: 36px;
    padding: 16px;
    box-shadow: 0 10px 0 #E65100, var(--shadow-chunky);
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
}

.clothes-tile {
    width: 100%;
    height: 96px;
    background: #FFFFFF;
    border-radius: 24px;
    border: 3px solid #FFF;
    box-shadow: 0 7px 0 #CFD8DC, 0 10px 16px rgba(0,0,0,0.08);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: grab;
    touch-action: none;
    transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.clothes-tile:active {
    cursor: grabbing;
    transform: scale(1.18) rotate(4deg);
    z-index: 100;
}

.bin-avatar-card {
    width: 200px;
    height: 280px;
    background: #FFFFFF;
    border-radius: 38px;
    border: 6px solid #FFCA28;
    box-shadow: 0 10px 0 #FFA000, var(--shadow-chunky);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-around;
    padding: 14px;
    margin: 0 auto;
    position: relative;
}

.bin-slot-item {
    font-size: 42px;
    transition: transform 0.3s;
}

/* ==========================================================================
   LEVEL 2: CHIẾC VALI KỲ DIỆU
   ========================================================================== */
.suitcase-arena {
    width: 100%;
    max-width: 880px;
    display: flex;
    gap: 20px;
    align-items: center;
    justify-content: center;
}

.suitcase-box-red {
    width: 280px;
    height: 300px;
    background: linear-gradient(135deg, #FF5252 0%, #D50000 100%);
    border-radius: 38px;
    border: 6px solid #8E0000;
    box-shadow: 0 12px 0 #5f0000, var(--shadow-chunky);
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 12px;
    position: relative;
}

.suitcase-inner-grid {
    width: 100%;
    flex: 1;
    background: #FFCDD2;
    border-radius: 26px;
    border: 3px dashed #B71C1C;
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-template-rows: repeat(2, 1fr);
    gap: 8px;
    padding: 8px;
    align-items: center;
    justify-items: center;
}

.suitcase-bear-badge {
    position: absolute;
    bottom: 12px;
    right: 12px;
    font-size: 44px;
    animation: gentle-pulse 2s infinite;
}

/* ==========================================================================
   LEVEL 3: KIỂM TRA AN NINH
   ========================================================================== */
.security-station-grid {
    width: 100%;
    max-width: 900px;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
}

.station-pod {
    background: rgba(255, 255, 255, 0.95);
    border-radius: 30px;
    border: 4px solid #B3E5FC;
    padding: 16px;
    box-shadow: 0 8px 0 #81D4FA, var(--shadow-chunky);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
}

.boarding-pass-chunky {
    width: 160px;
    height: 95px;
    background: #FFF9C4;
    border-radius: 20px;
    border: 3px dashed #FFB300;
    box-shadow: 0 6px 14px rgba(0,0,0,0.12);
    padding: 8px;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    transition: transform 0.2s;
    position: relative;
}

.boarding-pass-chunky:active {
    transform: scale(1.1) rotate(-3deg);
}

.stamp-badge {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) rotate(-15deg) scale(0);
    border: 4px solid #00E676;
    color: #00E676;
    font-weight: 900;
    font-size: 19px;
    padding: 4px 12px;
    border-radius: 10px;
    opacity: 0;
    background: #E8F5E9;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.stamp-badge.stamped {
    opacity: 1;
    transform: translate(-50%, -50%) rotate(-15deg) scale(1.15);
}

.xray-screen-neon {
    width: 180px;
    height: 110px;
    background: #00251A;
    border-radius: 18px;
    border: 3px solid #00E676;
    box-shadow: inset 0 0 18px rgba(0, 230, 118, 0.5);
    display: flex;
    align-items: center;
    justify-content: space-around;
    padding: 6px;
}

.xray-tap-box {
    width: 48px;
    height: 48px;
    background: #00E676;
    border-radius: 14px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 26px;
    cursor: pointer;
    box-shadow: 0 0 12px #00E676;
    transition: transform 0.2s;
}

.xray-tap-box:active {
    transform: scale(1.2);
}

.gate-detector-chunky {
    width: 140px;
    height: 180px;
    border: 14px solid #78909C;
    border-bottom: none;
    border-radius: 24px 24px 0 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-end;
    cursor: pointer;
    background: rgba(236, 239, 241, 0.6);
    position: relative;
}

.gate-lamps-row {
    position: absolute;
    top: -22px;
    display: flex;
    gap: 16px;
}

.gate-lamp-led {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: #CFD8DC;
    border: 2px solid #546E7A;
}

.gate-lamp-led.green-flash {
    background: #00E676;
    box-shadow: 0 0 18px #00E676;
    animation: lamp-blink 0.25s alternate 6;
}

/* ==========================================================================
   LEVEL 4: RA CỔNG BAY
   ========================================================================== */
.boarding-hall-arena {
    width: 100%;
    max-width: 920px;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.gates-array-row {
    display: flex;
    justify-content: space-around;
    gap: 10px;
}

.gate-pillar {
    width: 130px;
    height: 130px;
    background: #263238;
    color: #FFD54F;
    border: 5px solid #455A64;
    border-radius: 26px;
    box-shadow: 0 8px 0 #102027;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-family: monospace;
    font-weight: 900;
    transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.gate-pillar:active {
    transform: scale(1.1);
}

.gate-pillar.matched {
    background: linear-gradient(180deg, #2E7D32 0%, #1B5E20 100%);
    border-color: #00E676;
    color: #FFFFFF;
    box-shadow: 0 8px 0 #004D40, 0 0 22px #00E676;
}

/* ==========================================================================
   LEVEL 5: HIỆP SĨ ĐAI AN TOÀN & UỐNG NƯỚC
   ========================================================================== */
.cabin-seat-arena {
    width: 100%;
    max-width: 860px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    align-items: center;
}

.seat-plush-box {
    background: linear-gradient(180deg, #1976D2 0%, #0D47A1 100%);
    border-radius: 38px;
    border: 8px solid #0D47A1;
    box-shadow: 0 10px 0 #002171, var(--shadow-chunky);
    padding: 18px;
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
}

.safety-sign-led {
    background: #FF5252;
    color: white;
    font-weight: 900;
    font-size: 14px;
    padding: 4px 16px;
    border-radius: var(--radius-round);
    margin-bottom: 8px;
    transition: background 0.3s;
}

.safety-sign-led.green-safe {
    background: #00E676;
    color: #004D40;
    box-shadow: 0 0 18px #00E676;
}

.knight-cape-icon {
    position: absolute;
    top: 50px;
    font-size: 54px;
    opacity: 0;
    transform: scale(0.5);
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.knight-cape-icon.active {
    opacity: 1;
    transform: scale(1);
}

.seatbelt-straps-row {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    height: 70px;
    position: relative;
}

.strap-left, .strap-right {
    height: 46px;
    display: flex;
    align-items: center;
    cursor: grab;
    touch-action: none;
    transition: transform 0.2s;
}

.strap-left {
    background: #37474F;
    width: 90px;
    border-radius: 8px 0 0 8px;
    position: relative;
}

.buckle-insert {
    position: absolute;
    right: -18px;
    width: 22px;
    height: 30px;
    background: #B0BEC5;
    border: 3px solid #78909C;
    border-radius: 4px;
}

.strap-right {
    background: #37474F;
    width: 90px;
    border-radius: 0 8px 8px 0;
    position: relative;
}

.buckle-receiver {
    position: absolute;
    left: -18px;
    width: 28px;
    height: 42px;
    background: #90A4AE;
    border: 3px solid #546E7A;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.seatbelt-buckled .strap-left {
    transform: translateX(18px) !important;
}

.seatbelt-buckled .buckle-receiver {
    background: #00E676;
    border-color: #00BFA5;
}

/* ==========================================================================
   LEVEL 6: NGẮM MÂY BIẾN HÌNH
   ========================================================================== */
.cloud-window-frame {
    width: 100%;
    max-width: 860px;
    height: 310px;
    background: linear-gradient(180deg, #29B6F6 0%, #81D4FA 60%, #E1F5FE 100%);
    border-radius: 44px;
    border: 14px solid #ECEFF1;
    box-shadow: inset 0 0 25px rgba(0,0,0,0.18), 0 12px 0 #CFD8DC, var(--shadow-chunky);
    display: flex;
    align-items: center;
    justify-content: space-around;
    padding: 10px;
}

.morph-cloud-tile {
    background: rgba(255, 255, 255, 0.95);
    border-radius: 40px;
    padding: 16px 26px;
    box-shadow: 0 8px 18px rgba(0,0,0,0.12);
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: pointer;
    border: 3px solid transparent;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.morph-cloud-tile:active {
    transform: scale(1.25);
}

.morph-cloud-tile.morphed {
    background: #FFF9C4;
    border-color: #FFD54F;
    box-shadow: 0 0 25px #FFD54F;
    animation: gentle-bounce 0.6s infinite alternate;
}

/* ==========================================================================
   LEVEL 7: MÓN QUÀ LỊCH SỰ
   ========================================================================== */
.etiquette-arena {
    width: 100%;
    max-width: 860px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
}

.etiquette-card-chunky {
    background: rgba(255, 255, 255, 0.95);
    border-radius: 30px;
    padding: 20px;
    border: 4px solid #B3E5FC;
    box-shadow: 0 8px 0 #81D4FA, var(--shadow-chunky);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 14px;
}

.volume-emotion-options {
    display: flex;
    gap: 14px;
}

.volume-emotion-btn {
    width: 72px;
    height: 72px;
    border-radius: 24px;
    background: #FFF;
    border: 3px solid #CFD8DC;
    box-shadow: 0 7px 0 #B0BEC5;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.volume-emotion-btn span {
    font-size: 28px;
    line-height: 1;
}

.volume-emotion-btn small {
    font-size: 11px;
    font-weight: 900;
    color: #455A64;
    margin-top: 2px;
}

.volume-emotion-btn:active, .volume-emotion-btn.selected {
    transform: scale(1.15);
    border-color: #00E676;
    background: #E8F5E9;
    box-shadow: 0 7px 0 #00BFA5;
}

/* ==========================================================================
   LEVEL 8: LẤY VALI & HUY HIỆU DỰ THƯỞNG (CAROUSEL)
   ========================================================================== */
.carousel-final-arena {
    width: 100%;
    max-width: 900px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 14px;
}

.carousel-track-chunky {
    width: 90%;
    height: 160px;
    border: 16px solid #455A64;
    border-radius: 80px;
    background: #ECEFF1;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-around;
    box-shadow: inset 0 0 18px rgba(0,0,0,0.25);
    overflow: hidden;
}

.carousel-suitcases-track {
    display: flex;
    gap: 30px;
    position: absolute;
    animation: carousel-orbit 14s linear infinite;
}

.carousel-suitcases-track.paused {
    animation-play-state: paused;
}

.carousel-bag-tile {
    width: 78px;
    height: 90px;
    border-radius: 20px;
    border: 4px solid rgba(0,0,0,0.2);
    box-shadow: 0 6px 12px rgba(0,0,0,0.18);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 36px;
    cursor: pointer;
    transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.carousel-bag-tile:active {
    transform: scale(1.3) translateY(-10px);
}

/* Modal Phần Thưởng Cuối */
.golden-medal-modal {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) scale(0.8);
    opacity: 0;
    visibility: hidden;
    width: 90%;
    max-width: 580px;
    background: linear-gradient(135deg, #FFFDE7 0%, #FFF9C4 100%);
    border-radius: 38px;
    border: 8px solid #FFD54F;
    box-shadow: 0 20px 60px rgba(0,0,0,0.35);
    padding: 26px;
    text-align: center;
    z-index: 200;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.golden-medal-modal.show {
    opacity: 1;
    visibility: visible;
    transform: translate(-50%, -50%) scale(1);
}

/* ==========================================================================
   CỔNG BA MẸ (PARENT CONTROL HUB)
   ========================================================================== */
.parent-modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.65);
    backdrop-filter: blur(8px);
    z-index: 999;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
}

.parent-modal-overlay.open {
    opacity: 1;
    visibility: visible;
}

.parent-control-card {
    width: 90%;
    max-width: 560px;
    max-height: 88vh;
    overflow-y: auto;
    background: #FFFFFF;
    border-radius: 36px;
    padding: 24px;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.3);
    border: 5px solid #FF8A65;
}

.parent-tip-box {
    background: #FFF3E0;
    border-left: 5px solid #FF9800;
    padding: 10px 14px;
    border-radius: 12px;
    margin-bottom: 10px;
    font-size: 14px;
    line-height: 1.45;
    color: #4E342E;
}

.level-jump-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 8px;
    margin: 10px 0;
}

.jump-btn {
    padding: 8px;
    background: #ECEFF1;
    border: 2px solid #CFD8DC;
    border-radius: 12px;
    font-weight: 800;
    font-size: 14px;
    cursor: pointer;
}

/* ==========================================================================
   KEYFRAME ANIMATIONS
   ========================================================================== */
@keyframes gentle-sway {
    0%, 100% { transform: rotate(-3deg); }
    50% { transform: rotate(3deg); }
}

@keyframes gentle-bounce {
    0% { transform: translateY(0); }
    100% { transform: translateY(-8px); }
}

@keyframes gentle-pulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.12); }
}

@keyframes lamp-blink {
    0% { opacity: 0.3; }
    100% { opacity: 1; }
}

@keyframes carousel-orbit {
    0% { transform: translateX(0); }
    100% { transform: translateX(-400px); }
}

.pop-in {
    animation: popIn 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

@keyframes popIn {
    0% { transform: scale(0.6); opacity: 0; }
