/* ==========================================================================
   CÙNG BÉ BIN ĐI MÁY BAY - RICH COLORFUL 3D TYCOON DESIGN SYSTEM
   - Font Offline Fallback: Nunito -> Arial Rounded MT Bold -> system-ui -> sans-serif
   - Tươi sáng, độ bão hòa cao, bo tròn đồ chơi, viền đáy 3D đậm, đổ bóng đa tầng
   - Mô hình Parent-Co-Play: Chữ to rõ ràng $\ge 22px$, giao diện tương tác cực đại
   ========================================================================== */

:root {
    --color-sky-blue: #29B6F6;
    --color-sky-deep: #0288D1;
    --color-sun-yellow: #FFD54F;
    --color-sun-orange: #FF9800;
    --color-candy-red: #FF5252;
    --color-candy-red-deep: #D50000;
    --color-mint-green: #69F0AE;
    --color-emerald: #00E676;
    --color-royal-blue: #1976D2;
    --color-purple: #BA68C8;
    --color-warm-wood: #8D6E63;
    --text-dark: #1A237E;
    --text-muted: #455A64;
    --shadow-chunky: 0 8px 0 rgba(0, 0, 0, 0.16), 0 16px 28px rgba(0, 0, 0, 0.12);
    --shadow-glow: 0 0 25px rgba(255, 213, 79, 0.8);
    --radius-toy: 32px;
    --radius-round: 9999px;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    -webkit-tap-highlight-color: transparent;
    user-select: none;
    -webkit-user-select: none;
}

body, html {
    width: 100%;
    height: 100%;
    overflow: hidden;
    font-family: "Nunito", "Arial Rounded MT Bold", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: linear-gradient(135deg, #4FC3F7 0%, #81D4FA 35%, #FFE082 70%, #FF8A65 100%);
    color: var(--text-dark);
    touch-action: manipulation;
}

#app-root {
    width: 100vw;
    height: 100vh;
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
}

#effects-canvas {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1000;
}

/* ==========================================================================
   TOP BAR: 8 STAGE ICONS RỰC RỠ & CỔNG BA MẸ
   ========================================================================== */
.top-nav {
    height: 60px;
    padding: 6px 16px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    z-index: 50;
}

.stage-indicators {
    display: flex;
    gap: 8px;
    background: rgba(255, 255, 255, 0.94);
    backdrop-filter: blur(12px);
    padding: 4px 12px;
    border-radius: var(--radius-round);
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.12);
    border: 3px solid #FFF;
}

.stage-dot {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: #ECEFF1;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    box-shadow: inset 0 -4px 0 #CFD8DC;
    border: none;
}

.stage-dot.active {
    background: linear-gradient(180deg, #FFEB3B 0%, #FFC107 100%);
    transform: scale(1.18);
    box-shadow: 0 6px 16px rgba(255, 193, 7, 0.5), inset 0 -4px 0 #FF8F00;
}

.stage-dot.completed {
    background: linear-gradient(180deg, #69F0AE 0%, #00E676 100%);
    box-shadow: inset 0 -4px 0 #00BFA5;
}

.stage-dot.locked {
    opacity: 0.38;
    cursor: not-allowed;
    filter: grayscale(0.85);
}

/* NÚT BẤM BILLIONAIR 3D CHUNKY */
.tycoon-btn {
    min-width: 60px;
    min-height: 48px;
    padding: 8px 20px;
    border: none;
    border-radius: var(--radius-round);
    background: #FFFFFF;
    color: var(--text-dark);
    font-weight: 900;
    font-size: 17px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    cursor: pointer;
    box-shadow: 0 6px 0 #B0BEC5, 0 10px 18px rgba(0, 0, 0, 0.15);
    transition: all 0.12s ease;
    touch-action: manipulation;
}

.tycoon-btn:active:not(:disabled) {
    transform: translateY(4px);
    box-shadow: 0 2px 0 #B0BEC5, 0 4px 8px rgba(0, 0, 0, 0.1);
}

.tycoon-btn:disabled {
    cursor: not-allowed;
    opacity: 0.6;
    filter: grayscale(0.3);
}

.tycoon-btn-primary {
    background: linear-gradient(180deg, #FFD54F 0%, #FFA000 100%);
    color: #4E342E;
    box-shadow: 0 6px 0 #E65100, 0 10px 20px rgba(230, 81, 0, 0.35);
}

.tycoon-btn-primary:active:not(:disabled) {
    box-shadow: 0 2px 0 #E65100;
}

.tycoon-btn-green {
    background: linear-gradient(180deg, #69F0AE 0%, #00E676 100%);
    color: #004D40;
    box-shadow: 0 6px 0 #00897B, 0 10px 20px rgba(0, 137, 123, 0.35);
}

.tycoon-btn-green:active:not(:disabled) {
    box-shadow: 0 2px 0 #00897B;
}

/* Cổng Ba Mẹ: Vòng giữ 3 giây */
.parent-gate-btn {
    position: relative;
    overflow: hidden;
}

.parent-hold-ring {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    transform: rotate(-90deg);
}

.parent-hold-ring circle {
    fill: none;
    stroke: #FF5722;
    stroke-width: 5;
    stroke-dasharray: 175;
    stroke-dashoffset: 175;
    transition: stroke-dashoffset 0.1s linear;
}

/* ==========================================================================
   BIỂN BÁO LỜI THOẠI BA MẸ ĐỌC (PARENT PROMPT SIGNBOARD)
   - Chữ to $\ge 22px$, dễ đọc trong 2 giây, avatar Mẹ 3D chân thực
   ========================================================================== */
.parent-prompt-container {
    width: 100%;
    max-width: 880px;
    margin: 2px auto 6px auto;
    padding: 0 14px;
    z-index: 40;
}

.parent-prompt-signboard {
    background: linear-gradient(135deg, #FFFFFF 0%, #FFFDE7 100%);
    border-radius: 26px;
    padding: 8px 20px;
    border: 4px solid #FFCA28;
    box-shadow: 0 6px 0 #FFA000, var(--shadow-chunky);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
    text-align: center;
    position: relative;
}

.prompt-avatar-art {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    border: 3px solid #FF8A65;
    box-shadow: 0 4px 8px rgba(0,0,0,0.15);
    object-fit: cover;
    flex-shrink: 0;
    animation: gentle-sway 2.5s infinite;
}

.prompt-speech-text {
    font-size: 21px;
    font-weight: 900;
    color: #1A237E;
    line-height: 1.35;
    text-shadow: 0 1px 0 rgba(255,255,255,0.8);
}

/* ==========================================================================
   SCREENS VIEWPORT & THEMED BACKGROUNDS (8 MÀN CHƠI)
   ========================================================================== */
.screens-viewport {
    flex: 1;
    position: relative;
    width: 100%;
    height: calc(100vh - 135px);
    overflow: hidden;
}

.screen {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    visibility: hidden;
    transform: scale(0.96) translateY(16px);
    transition: opacity 0.35s ease, transform 0.35s cubic-bezier(0.34, 1.25, 0.64, 1), visibility 0.35s;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 4px 16px 14px 16px;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    border-radius: 28px;
}

.screen.active {
    opacity: 1;
    visibility: visible;
    transform: scale(1) translateY(0);
}

