    box-shadow: 0 10px 0 #B0BEC5, 0 12px 20px rgba(0,0,0,0.15);
}

.clothes-tile-art:active {
    cursor: grabbing;
    transform: scale(1.16) rotate(3deg);
    z-index: 100;
}

.clothes-tile-art.shake-wobble {
    animation: springShake 0.45s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
    border-color: #FF5252 !important;
}

.clothes-tile-art.fly-success {
    animation: flyShrinkSuccess 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.item-img-art {
