    justify-content: center;
    align-items: center;
    position: relative;
}

.bin-stage-pedestal {
    width: 250px;
    height: 330px;
    background: rgba(255, 255, 255, 0.9);
    border-radius: 36px;
    border: 6px solid #FFCA28;
