    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 10px;
    position: relative;
    overflow: hidden;
}

.bin-sprite-crop {
    width: 170px;
    height: 240px;
    background-image: var(--char-sprite);
    background-size: 470% auto;
    background-position: 4.5% 82%;
