}

.dress-check-badge.checked {
    background: #00E676;
    color: #004D40;
    box-shadow: 0 0 10px #00E676;
    transform: scale(1.08);
}

/* ==========================================================================
   LEVEL 2: CHIẾC VALI KỲ DIỆU
   ========================================================================== */
.suitcase-arena {
    width: 100%;
    max-width: 880px;
    display: flex;
    gap: 20px;
    align-items: center;
    justify-content: center;
}

.clothes-tile {
    width: 100%;
    height: 85px;
    background: #FFFFFF;
