    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: grab;
    touch-action: none;
    transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
    padding: 6px;
}

.clothes-tile:hover {
    transform: translateY(-3px) scale(1.05);
}

.clothes-tile.shake-wobble {
    animation: springShake 0.45s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
    border-color: #FF5252 !important;
}

.suitcase-box-red {
    width: 280px;
    height: 300px;
    background: linear-gradient(135deg, #FF5252 0%, #D50000 100%);
    border-radius: 38px;
    border: 6px solid #8E0000;
    box-shadow: 0 12px 0 #5f0000, var(--shadow-chunky);
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 12px;
    position: relative;
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.suitcase-box-red.packed-bounce {
    animation: popBounce 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.suitcase-inner-grid {
    width: 100%;
    flex: 1;
    background: #FFCDD2;
    border-radius: 26px;
    border: 3px dashed #B71C1C;
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-template-rows: repeat(2, 1fr);
    gap: 8px;
    padding: 8px;
    align-items: center;
    justify-items: center;
}

/* ==========================================================================
   LEVEL 3: KIỂM TRA AN NINH
   ========================================================================== */
.security-station-grid {
    width: 100%;
    max-width: 900px;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
}

.station-pod {
    background: rgba(255, 255, 255, 0.95);
    border-radius: 30px;
    border: 4px solid #B3E5FC;
    padding: 16px;
    box-shadow: 0 8px 0 #81D4FA, var(--shadow-chunky);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
}

.officer-avatar-crop {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background-image: var(--char-sprite);
    background-size: 430% auto;
    background-position: 87.5% 14%;
    border: 3px solid #00897B;
    box-shadow: 0 4px 10px rgba(0,0,0,0.15);
}

.boarding-pass-chunky {
    width: 160px;
    height: 95px;
    background: #FFF9C4;
    border-radius: 20px;
    border: 3px dashed #FFB300;
    box-shadow: 0 6px 14px rgba(0,0,0,0.12);
    padding: 8px;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    transition: transform 0.2s;
    position: relative;
}

.boarding-pass-chunky:hover { transform: scale(1.05); }

.stamp-badge {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) rotate(-15deg) scale(0);
    border: 4px solid #00E676;
    color: #00E676;
    font-weight: 900;
    font-size: 19px;
    padding: 4px 12px;
    border-radius: 10px;
    opacity: 0;
    background: #E8F5E9;
    transition: all 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.stamp-badge.stamped {
    opacity: 1;
    transform: translate(-50%, -50%) rotate(-15deg) scale(1.15);
    animation: stampSlam 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.xray-screen-neon {
    width: 180px;
    height: 110px;
    background: #00251A;
    border-radius: 18px;
    border: 3px solid #00E676;
    box-shadow: inset 0 0 18px rgba(0, 230, 118, 0.5);
    display: flex;
    align-items: center;
    justify-content: space-around;
    padding: 6px;
}

.xray-tap-box {
    width: 48px;
    height: 48px;
    background: #00E676;
    border-radius: 14px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 26px;
    cursor: pointer;
    box-shadow: 0 0 12px #00E676;
    transition: transform 0.2s;
}

.xray-tap-box:hover { transform: scale(1.12); }
.xray-tap-box.revealed-pulse { animation: popBounce 0.35s cubic-bezier(0.34, 1.56, 0.64, 1); }

.gate-detector-chunky {
    width: 140px;
    height: 180px;
