    pointer-events: none;
}

.item-label-tag {
    font-size: 13px;
    font-weight: 900;
    color: #37474F;
    margin-top: 4px;
    text-align: center;
}

.bin-character-stage {
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
}

.bin-stage-pedestal {
    width: 250px;
    height: 330px;
    background: rgba(255, 255, 255, 0.9);
    border-radius: 36px;
