    box-shadow: 0 0 18px #00E676;
}

.knight-cape-icon {
    position: absolute;
    top: 50px;
    font-size: 54px;
    opacity: 0;
    transform: scale(0.5);
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.knight-cape-icon.active {
    opacity: 1;
    transform: scale(1);
    animation: gentle-sway 1.5s infinite;
}

.seatbelt-straps-row {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    height: 70px;
    position: relative;
}

.strap-left, .strap-right {
