content:
Ứng dụng đã được cập nhật **Hệ Thống Trạng Thái Nhân Vật Động (Dynamic Character State Engine)** giúp hình ảnh Bé Bin **thay đổi trực tiếp và tức thì** theo mọi lựa chọn của học sinh:

---

### 🎨 1. Bảng 4 Trạng Thái Hình Ảnh Kết Hợp Của Bé Bin

Hệ thống quản lý 2 biến trạng thái chính:
- `shirtColor`: `'yellow'` (Áo thun vàng) hoặc `'blue'` (Áo xanh máy bay giấy)
- `seatbelt`: `true` (Đã cài đai) hoặc `false` (Chưa cài đai)

| Trạng thái kết hợp | Màu áo | Dây an toàn | File hình ảnh hiển thị trực tiếp |
| :--- | :---: | :---: | :--- |
| **1. Áo vàng + Chưa cài đai** | 🟡 Vàng | ❌ Chưa cài | [bin_yellow_unbuckled.svg](file:///c:/Demo.plane/assets/characters/bin_yellow_unbuckled.svg) |
| **2. Áo vàng + Đã cài đai** | 🟡 Vàng | ✅ Đã cài | [bin_yellow_buckled.svg](file:///c:/Demo.plane/assets/characters/bin_yellow_buckled.svg) |
| **3. Áo xanh + Chưa cài đai** | 🔵 Xanh | ❌ Chưa cài | [bin_blue_unbuckled.svg](file:///c:/Demo.plane/assets/characters/bin_blue_unbuckled.svg) |
| **4. Áo xanh + Đã cài đai** | 🔵 Xanh | ✅ Đã cài | [bin_blue_buckled.svg](file:///c:/Demo.plane/assets/characters/bin_blue_buckled.svg) |

---

### ⚙️ 2. Hàm Điều Khiển `updateCharacterImage()` Trong `app.js`

```javascript
updateCharacterImage() {
    const { shirtColor, seatbelt } = this.characterState;
    let assetPath = '';

    if (shirtColor === 'yellow') {
        assetPath = seatbelt 
            ? 'assets/characters/bin_yellow_buckled.svg' 
            : 'assets/characters/bin_yellow_unbuckled.svg';
    } else {
        assetPath = seatbelt 
            ? 'assets/characters/bin_blue_buckled.svg' 
            : 'assets/characters/bin_blue_unbuckled.svg';
    }

    // Cập nhật ngay lập tức tất cả hình ảnh Bé Bin trong ứng dụng
    document.querySelectorAll('.bin-dynamic-avatar').forEach(img => {
        img.src = assetPath;
        img.classList.remove('pop-in');
        void img.offsetWidth; // Kích hoạt animation chuyển động nhẹ
        img.classList.add('pop-in');
    });
}
```

---

### 🎮 3. Trải Nghiệm Tương Tác Trực Quan

1. **Tại Màn 1 (Mặc đồ)**:
   - Học sinh bấm chọn **“Áo thun vàng”** $\rightarrow$ Hình Bé Bin **đổi ngay sang áo hoodie vàng**.
   - Học sinh bấm chọn **“Áo thun xanh”** $\rightarrow$ Hình Bé Bin **đổi ngay sang áo xanh in máy bay giấy**.
2. **Tại Màn 5 (Cài đai)**:
   - Học sinh kéo/chạm cài dây an toàn $\rightarrow$ Hình Bé Bin **đổi ngay sang phiên bản có đai an toàn thắt ngang hông với khóa kim loại sáng bóng và huy hiệu an toàn xanh**, giữ nguyên màu áo đã chọn ở Màn 1!
3. **Tại Màn 8 (Tháo đai)**:
   - Sau khi máy bay dừng, bấm "Mở đai" $\rightarrow$ Hình Bé Bin **đổi ngay sang phiên bản đã tháo đai**.

---

Bạn có thể mở trực tiếp file [index.html](file:///c:/Demo.plane/index.html) để bấm thử các lựa chọn và quan sát hình ảnh Bé Bin thay đổi ngay tức thì trên màn hình!

args.CodeContent:
/**
 * character-renderer.js - Character State Renderer for Bé Bin
 * Quản lý trạng thái trang phục, tư thế (pose) và đai an toàn xuyên suốt 8 Level
 * KHÔNG hard-code asset trong gameplay - Gameplay chỉ thay đổi state qua API.
 */

class CharacterRenderer {
    constructor() {
        // State mặc định của Bé Bin
        this.characterState = {
            outfit: {
                shirt: 'yellow',       // 'yellow' | 'blue'
                pants: 'orange',       // 'orange' | 'blue'
                shoes: 'blue_velcro'   // 'blue_velcro' | 'white_laces'
            },
            pose: 'standing',          // 'standing' | 'happy' | 'pointing' | 'seated' | 'drinking_water' | 'looking_window' | 'whispering' | 'sitting_neat' | 'holding_badge'
            expression: 'normal',      // 'normal' | 'happy' | 'whispering'
            seatbelt: 'none',          // 'none' | 'open' | 'fastened'
            holding: null              // null | 'water' | 'ticket' | 'badge'
        };

        // Bảng ánh xạ Asset đường dẫn chuẩn
        this.assetManifest = {
            baseBody: 'assets/characters/bin/dress/bin_base.svg',
            shirts: {
                yellow: 'assets/characters/bin/dress/shirts/shirt_yellow.svg',
                blue: 'assets/characters/bin/dress/shirts/shirt_blue.svg'
            },
            pants: {
                orange: 'assets/characters/bin/dress/pants/pants_orange.svg',
                blue: 'assets/characters/bin/dress/pants/pants_blue.svg'
            },
            shoes: {
                blue_velcro: 'assets/characters/bin/dress/shoes/shoes_blue_velcro.svg',
                white_laces: 'assets/characters/bin/dress/shoes/shoes_white_laces.svg'
            },
            seatbelts: {
                open: 'assets/characters/bin/layers/seatbelt_open.svg',
                fastened: 'assets/characters/bin/layers/seatbelt_fastened.svg'
            },
            poses: {
                standing: null, // Dùng hệ layer dress
                seated: 'assets/characters/bin/poses/seated_base.svg',
                drinking_water: 'assets/characters/bin/poses/seated_drinking.svg',
                looking_window: 'assets/characters/bin/poses/looking_window.svg',
                whispering: 'assets/characters/bin/poses/whispering.svg',
                sitting_neat: 'assets/characters/bin/poses/sitting_neat.svg',
                holding_badge: 'assets/characters/bin/poses/holding_badge.svg'
            },
            // Màu trang phục đồng bộ vào CSS Variables để các Pose SVG tự động kế thừa
            palette: {
                shirt: {
                    yellow: '#FDD835',
                    blue: '#0288D1'
                },
                pants: {
                    orange: '#FFA726',
                    blue: '#1E88E5'
                },
                shoes: {
                    blue_velcro: '#1976D2',
                    white_laces: '#FFFFFF'
                }
            }
        };

        this.init();
    }

    init() {
        this.syncThemeVariables();
    }

    // --- CẬP NHẬT CSS VARIABLES ĐỂ TẤT CẢ POSE KẾ THỪA MÀU TRANG PHỤC ĐÃ CHỌN ---
    syncThemeVariables() {
        const root = document.documentElement;
        const shirtHex = this.assetManifest.palette.shirt[this.characterState.outfit.shirt] || '#FDD835';
        const pantsHex = this.assetManifest.palette.pants[this.characterState.outfit.pants] || '#FFA726';
        const shoesHex = this.assetManifest.palette.shoes[this.characterState.outfit.shoes] || '#1976D2';

        root.style.setProperty('--bin-shirt-color', shirtHex);
        root.style.setProperty('--bin-pants-color', pantsHex);
        root.style.setProperty('--bin-shoes-color', shoesHex);
    }

    // ==========================================================================
    // PUBLIC STATE API (GỌI TỪ GAMEPLAY CONTROLLER)
    // ==========================================================================

    setShirt(value) {
        if (!this.assetManifest.shirts[value]) return;
        this.characterState.outfit.shirt = value;
        this.syncThemeVariables();
        this.updateAll();
    }

    setPants(value) {
        if (!this.assetManifest.pants[value]) return;
        this.characterState.outfit.pants = value;
        this.syncThemeVariables();
        this.updateAll();
    }

    setShoes(value) {
        if (!this.assetManifest.shoes[value]) return;
        this.characterState.outfit.shoes = value;
        this.syncThemeVariables();
        this.updateAll();
    }

    setOutfit(outfitObj) {
        if (!outfitObj) return;
        if (outfitObj.shirt && this.assetManifest.shirts[outfitObj.shirt]) {
            this.characterState.outfit.shirt = outfitObj.shirt;
        }
        if (outfitObj.pants && this.assetManifest.pants[outfitObj.pants]) {
            this.characterState.outfit.pants = outfitObj.pants;
        }
        if (outfitObj.shoes && this.assetManifest.shoes[outfitObj.shoes]) {
            this.characterState.outfit.shoes = outfitObj.shoes;
        }
        this.syncThemeVariables();
        this.updateAll();
    }

    setPose(poseName) {
        this.characterState.pose = poseName;
        this.updateAll();
    }

    setExpression(expressionName) {
        this.characterState.expression = expressionName;
        this.updateAll();
    }

    setSeatbelt(seatbeltState) {
        this.characterState.seatbelt = seatbeltState; // 'none' | 'open' | 'fastened'
        this.updateAll();
    }

    setHolding(item) {
        this.characterState.holding = item;
        if (item === 'water') {
            this.setPose('drinking_water');
        } else if (item === 'badge') {
            this.setPose('holding_badge');
        } else {
            this.updateAll();
        }
    }

    reset() {
        this.characterState = {
            outfit: {
                shirt: 'yellow',
                pants: 'orange',
                shoes: 'blue_velcro'
            },
            pose: 'standing',
            expression: 'normal',
            seatbelt: 'none',
            holding: null
        };
        this.syncThemeVariables();
        this.updateAll();
    }

    // ==========================================================================
    // RENDER ENGINE: TẠO VÀ CẬP NHẬT CÁC LAYER HÌNH ẢNH
    // ==========================================================================

    renderTo(containerEl, customPose = null, customSeatbelt = null) {
        if (!containerEl) return;

        const effectivePose = customPose || this.characterState.pose;
        const effectiveSeatbelt = customSeatbelt !== null ? customSeatbelt : this.characterState.seatbelt;
        const isStandingLayered = effectivePose === 'standing' || effectivePose === 'happy';

        containerEl.innerHTML = '';
        containerEl.classList.add('bin-character-frame');

        if (isStandingLayered) {
            // HỆ LAYER LEVEL 1 & STANDING: Base Body + Shoes + Pants + Shirt + Accessories
            const wrapper = document.createElement('div');
            wrapper.className = 'bin-layered-stack';

            // 1. Layer Base Body
            const baseImg = document.createElement('img');
            baseImg.className = 'bin-layer bin-layer-base';
            baseImg.src = this.assetManifest.baseBody;
            baseImg.alt = 'Bé Bin Base Body';
            wrapper.appendChild(baseImg);

            // 2. Layer Giày (Shoes)
            if (this.characterState.outfit.shoes && this.assetManifest.shoes[this.characterState.outfit.shoes]) {
                const shoesImg = document.createElement('img');
                shoesImg.className = 'bin-layer bin-layer-shoes pop-in-soft';
                shoesImg.src = this.assetManifest.shoes[this.characterState.outfit.shoes];
                shoesImg.alt = 'Giày của Bin';
                wrapper.appendChild(shoesImg);
            }

            // 3. Layer Quần (Pants)
            if (this.characterState.outfit.pants && this.assetManifest.pants[this.characterState.outfit.pants]) {
                const pantsImg = document.createElement('img');
                pantsImg.className = 'bin-layer bin-layer-pants pop-in-soft';
                pantsImg.src = this.assetManifest.pants[this.characterState.outfit.pants];
                pantsImg.alt = 'Quần của Bin';
                wrapper.appendChild(pantsImg);
            }

            // 4. Layer Áo (Shirt)
            if (this.characterState.outfit.shirt && this.assetManifest.shirts[this.characterState.outfit.shirt]) {
                const shirtImg = document.createElement('img');
                shirtImg.className = 'bin-layer bin-layer-shirt pop-in-soft';
                shirtImg.src = this.assetManifest.shirts[this.characterState.outfit.shirt];
                shirtImg.alt = 'Áo của Bin';
                wrapper.appendChild(shirtImg);
            }

            // 5. Layer Dây An Toàn (Nếu có)
            if (effectiveSeatbelt && this.assetManifest.seatbelts[effectiveSeatbelt]) {
                const beltImg = document.createElement('img');
                beltImg.className = 'bin-layer bin-layer-seatbelt pop-in-soft';
                beltImg.src = this.assetManifest.seatbelts[effectiveSeatbelt];
                beltImg.alt = 'Dây an toàn';
                wrapper.appendChild(beltImg);
            }

            containerEl.appendChild(wrapper);
        } else {
            // POSE ĐẶC BIỆT (Seated, Drinking, Looking Window, Whispering, Sitting Neat, Holding Badge)
            const poseSrc = this.assetManifest.poses[effectivePose] || this.assetManifest.poses.seated;
            const wrapper = document.createElement('div');
            wrapper.className = 'bin-layered-stack';

            const poseImg = document.createElement('img');
            poseImg.className = 'bin-layer bin-layer-pose pop-in-soft';
            poseImg.src = poseSrc;
            poseImg.alt = `Bé Bin ${effectivePose}`;
            wrapper.appendChild(poseImg);

            // Thêm layer đai an toàn nếu pose seated và có yêu cầu
            if (effectiveSeatbelt && this.assetManifest.seatbelts[effectiveSeatbelt]) {
                const beltImg = document.createElement('img');
                beltImg.className = 'bin-layer bin-layer-seatbelt pop-in-soft';
                beltImg.src = this.assetManifest.seatbelts[effectiveSeatbelt];
                beltImg.alt = 'Dây an toàn';
                wrapper.appendChild(beltImg);
            }

            containerEl.appendChild(wrapper);
        }
    }

    // Cập nhật tất cả các mount point chứa nhân vật trên các màn chơi
    updateAll() {
        // 1. Mount point Level 1 Sân khấu chính
        const lvl1Mount = document.getElementById('bin-character-mount-lvl1');
        if (lvl1Mount) this.renderTo(lvl1Mount, 'standing', 'none');

        // 2. Mount point Level 3 Cổng An Ninh
        const lvl3Mount = document.getElementById('bin-character-mount-lvl3');
        if (lvl3Mount) this.renderTo(lvl3Mount, 'standing', 'none');

        // 3. Mount point Level 5 Ghế Ngồi Khoang Bay (Đai an toàn & Uống nước)
        const lvl5Mount = document.getElementById('bin-character-mount-lvl5');
        if (lvl5Mount) {
            const beltState = this.characterState.seatbelt || 'open';
            this.renderTo(lvl5Mount, this.characterState.pose === 'drinking_water' ? 'drinking_water' : 'seated', beltState);
        }

        // 4. Mount point Level 6 Nhìn Cửa Sổ
        const lvl6Mount = document.getElementById('bin-character-mount-lvl6');
        if (lvl6Mount) this.renderTo(lvl6Mount, 'looking_window', 'fastened');

        // 5. Mount point Level 7 Lịch Sự
        const lvl7Mount = document.getElementById('bin-character-mount-lvl7');
        if (lvl7Mount) {
            const pose7 = this.characterState.pose === 'whispering' ? 'whispering' : (this.characterState.pose === 'sitting_neat' ? 'sitting_neat' : 'seated');
            this.renderTo(lvl7Mount, pose7, 'fastened');
        }

        // 6. Mount point Level 8 Nhận Thưởng
        const lvl8Mount = document.getElementById('bin-character-mount-lvl8');
        if (lvl8Mount) {
            const pose8 = this.characterState.pose === 'holding_badge' ? 'holding_badge' : 'standing';
            this.renderTo(lvl8Mount, pose8, this.characterState.seatbelt === 'fastened' ? 'fastened' : 'open');
        }
    }
}

