/* ==========================================================================
   KEYFRAME ANIMATIONS
   ========================================================================== */
@keyframes gentle-sway {
    0%, 100% { transform: rotate(-2deg); }
    50% { transform: rotate(2deg); }
}

@keyframes gentle-bounce {
    0% { transform: translateY(0); }
    100% { transform: translateY(-6px); }
}

@keyframes springShake {
    10%, 90% { transform: translate3d(-3px, 0, 0) rotate(-3deg); }
    20%, 80% { transform: translate3d(4px, 0, 0) rotate(3deg); }
    30%, 50%, 70% { transform: translate3d(-5px, 0, 0) rotate(-2deg); }
    40%, 60% { transform: translate3d(5px, 0, 0) rotate(2deg); }
}

@keyframes stampSlam {
    0% { transform: translate(-50%, -50%) scale(2.4) rotate(-35deg); opacity: 0; }
    50% { transform: translate(-50%, -50%) scale(0.95) rotate(-10deg); opacity: 1; }
    100% { transform: translate(-50%, -50%) scale(1.1) rotate(-15deg); opacity: 1; }
}

@keyframes popBounce {
    0% { transform: scale(0.8); }
    60% { transform: scale(1.18); }
    100% { transform: scale(1); }
}

@keyframes lamp-blink {
    0% { opacity: 0.3; }
    100% { opacity: 1; }
}

@keyframes carousel-orbit {
    0% { transform: translateX(0); }
    100% { transform: translateX(-380px); }
}

.pop-in {
    animation: popIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

@keyframes popIn {
    0% { transform: scale(0.7); opacity: 0; }
    100% { transform: scale(1); opacity: 1; }
}

.hidden {
    display: none !important;
}

