        height: 38px;
    }
}

/**
 * app.js - Main Controller for "Cùng Bé Bin Đi Máy Bay" (8 Levels)
 * Chuẩn Storybook 2D Co-Play (BIN_SOFT_STORYBOOK_2D_V1)
 * - Không SpeechSynthesis / Không đọc tự động
 * - Gameplay chỉ đổi state qua window.binRenderer
 * - Phản hồi tương tác thân thiện, không lộ trước đáp án
 */

class KidFlightApp {
    constructor() {
        this.currentScreen = 1;
        this.totalScreens = 8;
        this.maxUnlockedLevel = 1;

        // Tránh duplicate event listeners
        this.levelInitialized = {
            1: false, 2: false, 3: false, 4: false,
            5: false, 6: false, 7: false, 8: false
        };

        // State theo dõi các nhiệm vụ
        this.level1Dressed = { shirt: false, pants: false, shoes: false };
        this.level2Packed = 0;
        this.level3Steps = { checkin: false, xrayCount: 0, gate: false };
        this.level4Completed = false;
        this.level5Belt = { inserted: false, earRelieved: false };
        this.level6Clouds = { c1: false, c2: false, c3: false, c4: false };
        this.level7Tasks = { volume: false, leg: false };
        this.level8State = { planeStopped: false, unbuckled: false, baggage: false };

        this.parentHoldStart = 0;
        this.parentHoldReqId = null;

        this.init();
    }

    init() {
        this.bindGlobalEvents();
        if (window.binRenderer) {
            window.binRenderer.updateAll();
        }
        this.initLevel(1);
        this.showScreen(1);
    }

    // --- BIỂN BÁO LỜI THOẠI BA MẸ ĐỌC (KHÔNG SPEECH SYNTHESIS) ---
    showParentPrompt(speaker, text) {
        if (window.dialogueMgr) {
            window.dialogueMgr.show(speaker, text);
        }
    }

    // --- NAVIGATION & PROGRESS LOCKING CONTROLLER ---
    unlockLevel(levelNum) {
        if (levelNum > this.maxUnlockedLevel && levelNum <= this.totalScreens) {
            this.maxUnlockedLevel = levelNum;
            const dot = document.querySelector(`.stage-dot[data-screen="${levelNum}"]`);
            if (dot) {
                dot.classList.remove('locked');
            }
        }
    }

    showScreen(screenNum) {
        if (screenNum < 1 || screenNum > this.totalScreens) return;

        if (this.currentScreen === 5 && screenNum !== 5) {
            if (window.audioMgr) window.audioMgr.stopEngineSound();
        }

        this.currentScreen = screenNum;
        this.unlockLevel(screenNum);

        document.querySelectorAll('.screen').forEach((scr, idx) => {
            if (idx + 1 === screenNum) {
                scr.classList.add('active');
            } else {
                scr.classList.remove('active');
            }
        });

        document.querySelectorAll('.stage-dot').forEach((dot, idx) => {
            const level = idx + 1;
            dot.classList.remove('active', 'completed', 'locked');

            if (level === screenNum) {
                dot.classList.add('active');
            } else if (level < screenNum || level <= this.maxUnlockedLevel) {
                dot.classList.add('completed');
            } else {
                dot.classList.add('locked');
            }
        });

        this.updateCharacterForScreen(screenNum);
        this.initLevel(screenNum);
        this.setInitialScreenDialogue(screenNum);
    }

    updateCharacterForScreen(screenNum) {
        if (!window.binRenderer) return;

        switch (screenNum) {
            case 1:
                window.binRenderer.renderTo(document.getElementById('bin-character-mount-lvl1'), 'level1_layers');
                break;
            case 2:
            case 3:
            case 4:
                window.binRenderer.setPose('standing');
                window.binRenderer.setSeatbelt('none');
                break;
            case 5:
                window.binRenderer.setPose('seated');
                window.binRenderer.setSeatbelt(this.level5Belt.inserted ? 'fastened' : 'open');
                break;
            case 6:
                window.binRenderer.setPose('looking_window');
                window.binRenderer.setSeatbelt('fastened');
                break;
            case 7:
                if (this.level7Tasks.volume && !this.level7Tasks.leg) {
                    window.binRenderer.setPose('whispering');
                } else if (this.level7Tasks.leg) {
                    window.binRenderer.setPose('sitting_neat');
                } else {
                    window.binRenderer.setPose('seated');
                }
                window.binRenderer.setSeatbelt('fastened');
                break;
            case 8:
                if (this.level8State.baggage) {
                    window.binRenderer.setPose('holding_badge');
                } else {
                    window.binRenderer.setPose('standing');
                }
                window.binRenderer.setSeatbelt(this.level8State.unbuckled ? 'open' : 'fastened');
                break;
        }
    }

    setInitialScreenDialogue(screenNum) {
        switch (screenNum) {
            case 1:
                this.showParentPrompt('Mẹ', '“Bin sắp đi máy bay rồi. Con chọn bộ đồ nào giúp Bin dễ vận động nhé!”');
                break;
            case 2:
                this.showParentPrompt('Bố', '“Bin mang gì đi máy bay nhỉ? Con xếp vali giúp Bin nhé!”');
                break;
            case 3:
                this.showParentPrompt('Mẹ', '“Đến chỗ kiểm tra an ninh rồi. Bin đi cùng Ba Mẹ và làm theo hướng dẫn nhé!”');
                break;
            case 4:
                this.showParentPrompt('Bố', '“Vé của Bin ghi số 03. Con tìm cổng số 03 nhé!”');
                break;
            case 5:
                this.showParentPrompt('Mẹ', '“Con giúp Bin cài dây an toàn nhé!”');
                break;
            case 6:
                this.showParentPrompt('Bin', '“Bin thấy đám mây giống hình gì nhỉ? Con nhìn cùng Bin nhé!”');
                break;
            case 7:
                this.showParentPrompt('Mẹ', '“Trên máy bay mình nói nhỏ vừa đủ nghe nhé. Con giúp Bin nào!”');
                break;
            case 8:
                this.level8State.planeStopped = false;
                this.level8State.unbuckled = false;
                this.showParentPrompt('Bố', '“Máy bay đang chạy vào chỗ đỗ. Bin vẫn ngồi yên và giữ dây an toàn nhé!”');

                const unbuckleBtn = document.getElementById('unbuckle-latch-btn');
                if (unbuckleBtn) {
                    unbuckleBtn.setAttribute('disabled', 'true');
                    unbuckleBtn.style.opacity = '0.6';
                    unbuckleBtn.style.borderColor = '#78909C';
                    unbuckleBtn.innerHTML = '<span>⏳ Máy bay đang chạy vào bãi đỗ...</span>';
                }

                setTimeout(() => {
                    this.level8State.planeStopped = true;
                    if (unbuckleBtn) {
                        unbuckleBtn.removeAttribute('disabled');
                        unbuckleBtn.style.opacity = '1';
                        unbuckleBtn.style.borderColor = '#00E676';
                        unbuckleBtn.innerHTML = '<span>🔓 Máy bay đã dừng hẳn — Mở dây an toàn</span>';
                    }
                    this.showParentPrompt('Mẹ', '“Máy bay dừng hẳn rồi. Bây giờ mình mới mở dây nhé!”');
                }, 2600);
                break;
        }
    }

    // --- GLOBAL EVENTS & CỔNG BA MẸ CONTROLLER ---
    bindGlobalEvents() {
        const parentBtn = document.getElementById('btn-parent-gate');
        const holdCircle = document.getElementById('parent-ring-circle');
        const modal = document.getElementById('parent-modal');
        const closeModalBtn = document.getElementById('btn-close-parent');

        if (parentBtn && holdCircle) {
            const startHold = (e) => {
                e.preventDefault();
                this.parentHoldStart = Date.now();
                const totalHold = 3000;

                const updateRing = () => {
                    const elapsed = Date.now() - this.parentHoldStart;
                    const progress = Math.min(1, elapsed / totalHold);
                    const offset = 175 - (175 * progress);
                    holdCircle.style.strokeDashoffset = offset;

                    if (progress >= 1) {
                        if (window.audioMgr) window.audioMgr.playTing();
                        modal.classList.add('open');
                        resetHold();
                    } else {
                        this.parentHoldReqId = requestAnimationFrame(updateRing);
                    }
                };

                this.parentHoldReqId = requestAnimationFrame(updateRing);
            };

            const resetHold = () => {
                if (this.parentHoldReqId) cancelAnimationFrame(this.parentHoldReqId);
                holdCircle.style.strokeDashoffset = 175;
            };

            parentBtn.addEventListener('pointerdown', startHold);
            parentBtn.addEventListener('pointerup', resetHold);
            parentBtn.addEventListener('pointerleave', resetHold);
            parentBtn.addEventListener('pointercancel', resetHold);
        }

        if (closeModalBtn && modal) {
            closeModalBtn.addEventListener('click', () => {
                if (window.audioMgr) window.audioMgr.playPop();
                modal.classList.remove('open');
            });
        }

        const volSlider = document.getElementById('setting-volume');
        if (volSlider) {
            volSlider.addEventListener('input', (e) => {
                if (window.audioMgr) window.audioMgr.volume = parseFloat(e.target.value);
            });
        }

        const motionToggle = document.getElementById('setting-reduced-motion');
        if (motionToggle) {
            motionToggle.addEventListener('change', (e) => {
                if (window.effectsMgr) window.effectsMgr.reducedMotion = e.target.checked;
            });
        }

        const resetBtn = document.getElementById('btn-reset-app');
        if (resetBtn) {
            resetBtn.addEventListener('click', () => {
                if (window.binRenderer) window.binRenderer.reset();
                window.location.reload();
            });
        }

        document.querySelectorAll('.jump-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const target = parseInt(btn.getAttribute('data-level'), 10);
                if (target) {
                    if (window.audioMgr) window.audioMgr.playPop();
                    modal.classList.remove('open');
                    this.unlockLevel(target);
                    this.showScreen(target);
                }
            });
        });

        document.querySelectorAll('.stage-dot').forEach((dot) => {
            dot.addEventListener('click', () => {
                const targetScreen = parseInt(dot.getAttribute('data-screen'), 10);
                if (!dot.classList.contains('locked') && targetScreen && targetScreen <= this.maxUnlockedLevel) {
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.showScreen(targetScreen);
                }
            });
        });
    }

    initLevel(levelNum) {
        if (this.levelInitialized[levelNum]) return;
        this.levelInitialized[levelNum] = true;

        switch (levelNum) {
            case 1: this.initLevel1(); break;
            case 2: this.initLevel2(); break;
            case 3: this.initLevel3(); break;
            case 4: this.initLevel4(); break;
            case 5: this.initLevel5(); break;
            case 6: this.initLevel6(); break;
            case 7: this.initLevel7(); break;
            case 8: this.initLevel8(); break;
        }
    }

    // ==========================================================================
    // LEVEL 1: CHỌN TRANG PHỤC (KHÔNG LỘ ĐÁP ÁN, FEEDBACK SAU THAO TÁC)
    // ==========================================================================
    initLevel1() {
        const clothesTiles = document.querySelectorAll('#screen-1 [data-clothing-item="true"]');
        const binTarget = document.getElementById('bin-dress-target');
        const btnNext1 = document.getElementById('btn-next-level-1');

        const applyClothingItem = (tile) => {
            const isFit = tile.getAttribute('data-fit') === 'soft';
            const type = tile.getAttribute('data-type');
            const binRect = binTarget.getBoundingClientRect();

            if (isFit && window.binRenderer) {
                // Áp dụng trực tiếp vào layer của Bé Bin
                if (type === 'shirt') {
                    this.level1Dressed.shirt = true;
                    window.binRenderer.setShirt('soft');
                } else if (type === 'pants') {
                    this.level1Dressed.pants = true;
                    window.binRenderer.setPants('soft');
                } else if (type === 'shoes') {
                    this.level1Dressed.shoes = true;
                    window.binRenderer.setShoes('velcro');
                }

                if (window.effectsMgr) {
                    window.effectsMgr.burstStarsAt(binRect.left + binRect.width / 2, binRect.top + binRect.height / 2);
                }
                if (window.audioMgr) window.audioMgr.playTing();

                this.showParentPrompt('Mẹ', '“Đúng rồi! Món này mềm và dễ vận động.”');

                // Kiểm tra hoàn thành đủ 3 món
                if (this.level1Dressed.shirt && this.level1Dressed.pants && this.level1Dressed.shoes) {
                    this.unlockLevel(2);
                    if (btnNext1) {
                        btnNext1.classList.remove('hidden');
                        btnNext1.classList.add('pop-in');
                    }
                }
            } else {
                tile.classList.add('shake-wobble');
                setTimeout(() => { tile.classList.remove('shake-wobble'); }, 500);

                tile.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
                tile.style.transform = 'translate(0px, 0px)';
                if (window.audioMgr) window.audioMgr.playBoing();
                this.showParentPrompt('Bố', '“Món này hơi bất tiện. Con thử món khác nhé!”');
            }
        };

        clothesTiles.forEach(tile => {
            let startX = 0, startY = 0;
            let isDragging = false;

            const onDown = (e) => {
                isDragging = true;
                tile.setPointerCapture(e.pointerId);
                startX = e.clientX;
                startY = e.clientY;
                tile.style.zIndex = '999';
            };

            const onMove = (e) => {
                if (!isDragging) return;
                const dx = e.clientX - startX;
                const dy = e.clientY - startY;
                tile.style.transform = `translate(${dx}px, ${dy}px) scale(1.15)`;
            };

            const onUp = (e) => {
                if (!isDragging) return;
                isDragging = false;
                tile.releasePointerCapture(e.pointerId);

                const tileRect = tile.getBoundingClientRect();
                const binRect = binTarget.getBoundingClientRect();

                const isOver = !(
                    tileRect.right < binRect.left ||
                    tileRect.left > binRect.right ||
                    tileRect.bottom < binRect.top ||
                    tileRect.top > binRect.bottom
                );

                if (isOver) {
                    applyClothingItem(tile);
                    tile.style.transform = 'translate(0px, 0px)';
                } else {
                    tile.style.transition = 'transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)';
                    tile.style.transform = 'translate(0px, 0px)';
                }
            };

            tile.addEventListener('pointerdown', onDown);
            tile.addEventListener('pointermove', onMove);
            tile.addEventListener('pointerup', onUp);
            tile.addEventListener('pointercancel', onUp);

            tile.addEventListener('click', () => {
                applyClothingItem(tile);
            });
        });

        if (btnNext1) {
            btnNext1.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(2);
            };
        }
    }

    // ==========================================================================
    // LEVEL 2: XẾP VALI (PACK / ASK_PARENT / LEAVE_HOME)
    // ==========================================================================
    initLevel2() {
        const luggageItems = document.querySelectorAll('#screen-2 [data-luggage-item="true"]');
        const suitcase = document.getElementById('suitcase-target-lvl2');
        const suitcaseInner = document.getElementById('suitcase-inner-lvl2');
        const btnNext2 = document.getElementById('btn-next-level-2');

        const tryPackLuggage = (item) => {
            if (item.classList.contains('packed')) return;
            const category = item.getAttribute('data-category');
            const suitcaseRect = suitcase.getBoundingClientRect();

            if (category === 'PACK') {
                item.classList.add('packed');
                item.style.display = 'none';

                if (suitcase) {
                    suitcase.classList.add('packed-bounce');
                    setTimeout(() => { suitcase.classList.remove('packed-bounce'); }, 450);
                }

                const icon = item.querySelector('.item-icon');
                if (icon && icon.tagName === 'IMG') {
                    const imgClone = document.createElement('img');
                    imgClone.src = icon.src;
                    imgClone.style.width = '52px';
                    imgClone.style.height = '52px';
                    imgClone.style.objectFit = 'contain';
                    imgClone.className = 'pop-in';
                    suitcaseInner.appendChild(imgClone);
                } else {
                    const iconSpan = document.createElement('span');
                    iconSpan.textContent = icon ? icon.textContent : '📦';
                    iconSpan.style.fontSize = '34px';
                    iconSpan.className = 'pop-in';
                    suitcaseInner.appendChild(iconSpan);
                }

                this.level2Packed++;

                if (window.effectsMgr) {
                    window.effectsMgr.burstStarsAt(suitcaseRect.left + suitcaseRect.width / 2, suitcaseRect.top + suitcaseRect.height / 2);
                }
                if (window.audioMgr) window.audioMgr.playTing();

                this.showParentPrompt('Mẹ', '“Ừ! Món này mình xếp vào vali nhé.”');

                if (this.level2Packed >= 3) {
                    this.showParentPrompt('Mẹ', '“Vali của Bin đã sẵn sàng rồi! Cùng đến sân bay thôi!”');
                    this.unlockLevel(3);
                    if (btnNext2) {
                        btnNext2.classList.remove('hidden');
                        btnNext2.classList.add('pop-in');
                    }
                }
            } else if (category === 'ASK_PARENT') {
                item.classList.add('shake-wobble');
                setTimeout(() => { item.classList.remove('shake-wobble'); }, 500);

                item.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
                item.style.transform = 'translate(0px, 0px)';
                if (window.audioMgr) window.audioMgr.playPop();
                this.showParentPrompt('Bố', '“Món này mình hỏi Ba Mẹ trước nhé!”');
            } else {
                item.classList.add('shake-wobble');
                setTimeout(() => { item.classList.remove('shake-wobble'); }, 500);

                item.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
                item.style.transform = 'translate(0px, 0px)';
                if (window.audioMgr) window.audioMgr.playBoing();
                this.showParentPrompt('Bố', '“Món này để Ba Mẹ giúp mình xử lý nhé.”');
            }
        };

        luggageItems.forEach(item => {
            let startX = 0, startY = 0;
            let isDragging = false;

            const onDown = (e) => {
                if (item.classList.contains('packed')) return;
                isDragging = true;
                item.setPointerCapture(e.pointerId);
                startX = e.clientX;
                startY = e.clientY;
                item.style.zIndex = '999';
            };

            const onMove = (e) => {
                if (!isDragging) return;
                const dx = e.clientX - startX;
                const dy = e.clientY - startY;
                item.style.transform = `translate(${dx}px, ${dy}px) scale(1.15)`;
            };

            const onUp = (e) => {
                if (!isDragging) return;
                isDragging = false;
                item.releasePointerCapture(e.pointerId);

                const itemRect = item.getBoundingClientRect();
                const suitcaseRect = suitcase.getBoundingClientRect();

                const isOver = !(
                    itemRect.right < suitcaseRect.left ||
                    itemRect.left > suitcaseRect.right ||
                    itemRect.bottom < suitcaseRect.top ||
                    itemRect.top > suitcaseRect.bottom
                );

                if (isOver) {
                    tryPackLuggage(item);
                } else {
                    item.style.transition = 'transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)';
                    item.style.transform = 'translate(0px, 0px)';
                }
            };

            item.addEventListener('pointerdown', onDown);
            item.addEventListener('pointermove', onMove);
            item.addEventListener('pointerup', onUp);
            item.addEventListener('pointercancel', onUp);

            item.addEventListener('click', () => {
                if (!item.classList.contains('packed')) {
                    tryPackLuggage(item);
                }
            });
        });

        if (btnNext2) {
            btnNext2.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(3);
            };
        }
    }

    // ==========================================================================
    // LEVEL 3: KIỂM TRA AN NINH (3 TRẠM)
    // ==========================================================================
    initLevel3() {
        const passCard = document.getElementById('pass-card-lvl3');
        const stampBadge = document.getElementById('stamp-badge-lvl3');
        const xrayBoxes = document.querySelectorAll('#screen-3 .xray-tap-box');
        const gate = document.getElementById('gate-detector-lvl3');
        const lamps = document.querySelectorAll('#screen-3 .gate-lamp-led');
        const binMount3 = document.getElementById('bin-character-mount-lvl3');
        const btnNext3 = document.getElementById('btn-next-level-3');

        if (passCard) {
            passCard.onclick = () => {
                if (this.level3Steps.checkin) return;
                this.level3Steps.checkin = true;
                if (stampBadge) stampBadge.classList.add('stamped');
                if (window.audioMgr) window.audioMgr.playStamp();

                if (window.effectsMgr) {
                    const r = passCard.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }

                this.showParentPrompt('Tiếp viên', '“Vé của Bin xong rồi! Giờ soi chiếu vali nhé.”');
                this.checkLevel3Completion();
            };
        }

        xrayBoxes.forEach(box => {
            box.onclick = () => {
                if (box.getAttribute('data-revealed') === 'true') return;
                box.setAttribute('data-revealed', 'true');
                box.textContent = box.getAttribute('data-item');
                box.style.background = '#FFF9C4';
                box.classList.add('revealed-pulse');
                this.level3Steps.xrayCount++;

                if (window.audioMgr) window.audioMgr.playTing();
                if (window.effectsMgr) {
                    const r = box.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }

                if (this.level3Steps.xrayCount >= 3) {
                    this.showParentPrompt('Mẹ', '“Vali của Bin an toàn rồi! Chạm để Bin qua cổng nhé.”');
                    this.checkLevel3Completion();
                }
            };
        });

        if (gate) {
            gate.onclick = () => {
                if (this.level3Steps.gate) return;
                this.level3Steps.gate = true;

                lamps.forEach(l => l.classList.add('green-flash'));
                if (binMount3) binMount3.style.transform = 'translateY(-14px) scale(1.1)';

                if (window.audioMgr) window.audioMgr.playBeepBoop();
                if (window.effectsMgr) {
                    const r = gate.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }

                this.showParentPrompt('Mẹ', '“Giỏi lắm! Bin đã qua khu kiểm tra an ninh rồi.”');
                this.checkLevel3Completion();
            };
        }

        if (btnNext3) {
            btnNext3.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(4);
            };
        }
    }

    checkLevel3Completion() {
        const btnNext3 = document.getElementById('btn-next-level-3');
        if (this.level3Steps.checkin && this.level3Steps.xrayCount >= 3 && this.level3Steps.gate) {
            this.unlockLevel(4);
            if (btnNext3) {
                btnNext3.classList.remove('hidden');
                btnNext3.classList.add('pop-in');
            }
        }
    }

    // ==========================================================================
    // LEVEL 4: RA CỔNG BAY (TÌM CỔNG 03)
    // ==========================================================================
    initLevel4() {
        const gatePillars = document.querySelectorAll('#screen-4 .gate-pillar');
        const btnNext4 = document.getElementById('btn-next-level-4');

        gatePillars.forEach(pillar => {
            pillar.onclick = () => {
                const targetGate = pillar.getAttribute('data-gate');

                if (targetGate === '03') {
                    this.level4Completed = true;
                    pillar.classList.add('matched');

                    if (window.effectsMgr) {
                        const r = pillar.getBoundingClientRect();
                        window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                    }
                    if (window.audioMgr) window.audioMgr.playConnect();

                    this.showParentPrompt('Tiếp viên', '“Đúng rồi! Cổng 03 đây rồi! Chào mừng Bin lên máy bay!”');
                    this.unlockLevel(5);

                    if (btnNext4) {
                        btnNext4.classList.remove('hidden');
                        btnNext4.classList.add('pop-in');
                    }
                } else {
                    pillar.classList.add('shake-wobble');
                    setTimeout(() => { pillar.classList.remove('shake-wobble'); }, 500);

                    if (window.audioMgr) window.audioMgr.playBoing();
                    this.showParentPrompt('Bố', '“Con nhìn lại số trên vé nhé!”');
                }
            };
        });

        if (btnNext4) {
            btnNext4.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(5);
            };
        }
    }

    // ==========================================================================
    // LEVEL 5: ĐAI AN TOÀN & UỐNG NƯỚC (RENDERER SEATBELT & DRINKING)
    // ==========================================================================
    initLevel5() {
        const strapLeft = document.getElementById('seatbelt-strap-lvl5');
        const puzzleBox = document.getElementById('seatbelt-puzzle-lvl5');
        const safetySign = document.getElementById('safety-sign-lvl5');
        const knightCape = document.getElementById('bin-knight-cape');
        const btnWater = document.getElementById('btn-drink-water-lvl5');
        const earWaves = document.querySelectorAll('#screen-5 .ear-soundwave');
        const btnNext5 = document.getElementById('btn-next-level-5');

        const tryBuckleBelt = () => {
            if (this.level5Belt.inserted) return;
            this.level5Belt.inserted = true;
            puzzleBox.classList.add('seatbelt-buckled');

            // Cập nhật trạng thái cài đai thật qua Renderer
            if (window.binRenderer) {
                window.binRenderer.setSeatbelt('fastened');
            }

            if (safetySign) safetySign.classList.add('green-safe');
            if (knightCape) knightCape.classList.add('active');

            if (window.audioMgr) {
                window.audioMgr.playClack();
                window.audioMgr.startEngineSound(0.22);
            }

            if (window.effectsMgr) {
                const r = puzzleBox.getBoundingClientRect();
                window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
            }

            this.showParentPrompt('Mẹ', '“CẠCH! Dây an toàn chắc chắn rồi!”');

            setTimeout(() => {
                earWaves.forEach(w => w.classList.remove('hidden'));
                if (btnWater) btnWater.classList.remove('hidden');
                this.showParentPrompt('Mẹ', '“Tai Bin hơi khó chịu. Bin uống một ngụm nước nhé.”');
            }, 2500);
        };

        if (strapLeft && puzzleBox) {
            let isDragging = false;
            let startX = 0;

            const onDown = (e) => {
                if (this.level5Belt.inserted) return;
                isDragging = true;
                strapLeft.setPointerCapture(e.pointerId);
                startX = e.clientX;
            };

            const onMove = (e) => {
                if (!isDragging || this.level5Belt.inserted) return;
                const dx = Math.max(0, Math.min(45, e.clientX - startX));
                strapLeft.style.transform = `translateX(${dx}px)`;

                if (dx >= 35) {
                    tryBuckleBelt();
                }
            };

            const onUp = (e) => {
                if (!isDragging) return;
                isDragging = false;
                strapLeft.releasePointerCapture(e.pointerId);
                if (!this.level5Belt.inserted) {
                    strapLeft.style.transform = 'translateX(0px)';
                }
            };

            strapLeft.addEventListener('pointerdown', onDown);
            strapLeft.addEventListener('pointermove', onMove);
            strapLeft.addEventListener('pointerup', onUp);

            puzzleBox.addEventListener('click', () => {
                tryBuckleBelt();
            });
        }

        if (btnWater) {
            btnWater.onclick = () => {
                if (this.level5Belt.earRelieved) return;
                this.level5Belt.earRelieved = true;

                // Pose uống nước thật
                if (window.binRenderer) {
                    window.binRenderer.setPose('drinking_water');
                }

                earWaves.forEach(w => w.classList.add('hidden'));

                if (window.effectsMgr) {
                    const binHead = document.getElementById('bin-character-mount-lvl5');
                    if (binHead) {
                        const r = binHead.getBoundingClientRect();
                        window.effectsMgr.spawnMusicNotesAt(r.left + r.width / 2, r.top);
                    }
                }

                if (window.audioMgr) window.audioMgr.playDrinkWater();
                this.showParentPrompt('Bin', '“Tai Bin dễ chịu hơn rồi!”');
                this.unlockLevel(6);

                setTimeout(() => {
                    if (window.binRenderer) {
                        window.binRenderer.setPose('seated');
                    }
                }, 2800);

                if (btnNext5) {
                    btnNext5.classList.remove('hidden');
                    btnNext5.classList.add('pop-in');
                }
            };
        }

        if (btnNext5) {
            btnNext5.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(6);
            };
        }
    }

    // ==========================================================================
    // LEVEL 6: NGẮM MÂY BIẾN HÌNH (BIN LOOKING WINDOW)
    // ==========================================================================
    initLevel6() {
        const cloudTiles = document.querySelectorAll('#screen-6 .morph-cloud-tile');
        const btnNext6 = document.getElementById('btn-next-level-6');

        cloudTiles.forEach(tile => {
            tile.onclick = () => {
                if (tile.classList.contains('morphed')) return;
                tile.classList.add('morphed');

                const morphType = tile.getAttribute('data-morph');
                const icon = tile.querySelector('.cloud-icon');
                const label = tile.querySelector('.cloud-label');

                if (morphType === 'bunny') {
                    icon.textContent = '🐰';
                    label.textContent = 'Chú thỏ';
                    this.level6Clouds.c1 = true;
                    this.showParentPrompt('Bin', '“Bin thấy giống chú thỏ! Còn con thấy giống gì?”');
                } else if (morphType === 'car') {
                    icon.textContent = '🚗';
                    label.textContent = 'Chiếc ô tô';
                    this.level6Clouds.c2 = true;
                    this.showParentPrompt('Bin', '“Bin thấy giống ô tô chạy! Còn con thấy giống gì?”');
                } else if (morphType === 'watermelon') {
                    icon.textContent = '🍉';
                    label.textContent = 'Miếng dưa hấu';
                    this.level6Clouds.c3 = true;
                    this.showParentPrompt('Bin', '“Bin thấy giống miếng dưa hấu! Còn con thấy giống gì?”');
                } else if (morphType === 'bear') {
                    icon.textContent = '🐻';
                    label.textContent = 'Chú gấu';
                    this.level6Clouds.c4 = true;
                    this.showParentPrompt('Bin', '“Bin thấy giống chú gấu vẫy tay! Còn con thấy giống gì?”');
                }

                if (window.effectsMgr) {
                    const r = tile.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }
                if (window.audioMgr) window.audioMgr.playBling();

                if (this.level6Clouds.c1 && this.level6Clouds.c2 && this.level6Clouds.c3 && this.level6Clouds.c4) {
                    this.unlockLevel(7);
                    if (btnNext6) {
                        btnNext6.classList.remove('hidden');
                        btnNext6.classList.add('pop-in');
                    }
                }
            };
        });

        if (btnNext6) {
            btnNext6.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(7);
            };
        }
    }

    // ==========================================================================
    // LEVEL 7: LỊCH SỰ (3 MỨC ÂM LƯỢNG & THU CHÂN)
    // ==========================================================================
    initLevel7() {
        const emotionBtns = document.querySelectorAll('#screen-7 .volume-emotion-btn');
        const legTarget = document.getElementById('bin-leg-target');
        const legLabel = document.getElementById('leg-status-label');
        const btnNext7 = document.getElementById('btn-next-level-7');

        emotionBtns.forEach(btn => {
            btn.onclick = () => {
                emotionBtns.forEach(b => b.classList.remove('selected'));
                btn.classList.add('selected');
                const level = btn.getAttribute('data-level');

                if (level === 'loud') {
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.showParentPrompt('Mẹ', '“Ơ, hơi to rồi. Con thử nhỏ hơn nhé!”');
                } else if (level === 'medium') {
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.showParentPrompt('Mẹ', '“Nhỏ hơn một chút nữa nhé!”');
                } else if (level === 'whisper') {
                    this.level7Tasks.volume = true;
                    if (window.binRenderer) {
                        window.binRenderer.setPose('whispering');
                    }

                    if (window.effectsMgr) {
                        const r = btn.getBoundingClientRect();
                        window.effectsMgr.spawnFloatingHeartsAt(r.left + r.width / 2, r.top);
                    }
                    if (window.audioMgr) window.audioMgr.playTing();
                    this.showParentPrompt('Bin', '“Đúng rồi! Mình nói nhỏ vừa đủ nghe nhé.”');

                    if (!this.level7Tasks.leg) {
                        setTimeout(() => {
                            this.showParentPrompt('Mẹ', '“Bin thu chân gọn lại để không chạm ghế phía trước nhé!”');
                        }, 2200);
                    }

                    this.checkLevel7Completion();
                }
            };
        });

        if (legTarget) {
            legTarget.onclick = () => {
                if (this.level7Tasks.leg) return;
                this.level7Tasks.leg = true;

                if (window.binRenderer) {
                    window.binRenderer.setPose('sitting_neat');
                }

                legTarget.style.transform = 'translateY(14px)';
                if (legLabel) legLabel.textContent = 'Chân Bin đã thu lại ngay ngắn ✓';

                if (window.effectsMgr) {
                    const r = legTarget.getBoundingClientRect();
                    window.effectsMgr.spawnFloatingHeartsAt(r.left + r.width / 2, r.top);
                }

                if (window.audioMgr) window.audioMgr.playTing();
                this.showParentPrompt('Bố', '“Giỏi lắm! Bin ngồi gọn rồi, không đạp ghế trước!”');
                this.checkLevel7Completion();
            };
        }

        if (btnNext7) {
            btnNext7.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(8);
            };
        }
    }

    checkLevel7Completion() {
        const btnNext7 = document.getElementById('btn-next-level-7');
        if (this.level7Tasks.volume && this.level7Tasks.leg) {
            this.unlockLevel(8);
            if (btnNext7) {
                btnNext7.classList.remove('hidden');
                btnNext7.classList.add('pop-in');
            }
        }
    }

    // ==========================================================================
    // LEVEL 8: HẠ CÁNH, MỞ ĐAI & NHẬN VALI THƯỞNG
    // ==========================================================================
    initLevel8() {
        const unbuckleLatch = document.getElementById('unbuckle-latch-btn');
        const baggageCarousel = document.getElementById('baggage-carousel-lvl8');
        const bags = document.querySelectorAll('#screen-8 .carousel-bag-tile');
        const medalModal = document.getElementById('golden-medal-modal');
        const btnReplay = document.getElementById('btn-replay-adventure');

        if (unbuckleLatch) {
            unbuckleLatch.onclick = () => {
                if (!this.level8State.planeStopped) {
                    this.showParentPrompt('Bố', '“Máy bay đang chạy vào chỗ đỗ. Bin vẫn ngồi yên và giữ dây an toàn nhé!”');
                    return;
                }

                if (this.level8State.unbuckled) return;
                this.level8State.unbuckled = true;

                if (window.binRenderer) {
                    window.binRenderer.setSeatbelt('open');
                }

                unbuckleLatch.innerHTML = '<span>🔓 Đai an toàn đã mở ✓</span>';
                unbuckleLatch.style.borderColor = '#00E676';

                if (window.audioMgr) window.audioMgr.playUnbuckle();
                this.showParentPrompt('Bố', '“Con tìm chiếc vali đỏ có hình gấu của Bin nhé!”');

                if (baggageCarousel) baggageCarousel.classList.remove('hidden');
            };
        }

        bags.forEach(bag => {
            bag.onclick = () => {
                if (!this.level8State.unbuckled) {
                    this.showParentPrompt('Mẹ', '“Máy bay dừng hẳn rồi. Bây giờ mình mới mở dây an toàn nhé!”');
                    return;
                }

                const isBinBag = bag.getAttribute('data-is-bin') === 'true';

                if (isBinBag) {
                    this.level8State.baggage = true;
                    bag.style.transform = 'scale(1.3) translateY(-14px)';
                    const track = document.querySelector('.carousel-suitcases-track');
                    if (track) track.classList.add('paused');

                    if (window.binRenderer) {
                        window.binRenderer.setPose('holding_badge');
                    }

                    if (window.effectsMgr) {
                        window.effectsMgr.startCelebrationFireworks(3000);
                    }

                    if (window.audioMgr) window.audioMgr.playFanfare();
                    this.showParentPrompt('Mẹ', '“Hoan hô! Bin tìm đúng vali rồi!”');

                    setTimeout(() => {
                        if (medalModal) medalModal.classList.add('show');
                    }, 1200);
                } else {
                    bag.classList.add('shake-wobble');
                    setTimeout(() => { bag.classList.remove('shake-wobble'); }, 500);

                    if (window.audioMgr) window.audioMgr.playBoing();
                    this.showParentPrompt('Bố', '“Vali này của bạn khác rồi. Con tìm lại nhé!”');
                }
            };
        });

        if (btnReplay) {
            btnReplay.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                if (window.binRenderer) window.binRenderer.reset();
                window.location.reload();
            };
        }
    }
}

