/**
 * character-renderer.js - Character State Renderer for Bé Bin
 * 100% Sử dụng Master Storybook 2D Artwork thật (BIN_SOFT_STORYBOOK_2D_V1)
 * Tuyệt đối không dùng SVG procedural primitives để dựng nhân vật
 */

class CharacterRenderer {
    constructor() {
        // State nhân vật
        this.characterState = {
            outfit: {
                shirt: 'soft',
                pants: 'soft',
                shoes: 'velcro'
            },
            pose: 'standing',
            expression: 'normal',
            seatbelt: 'none',
            holding: null
        };

        // Bảng ánh xạ Artwork Storybook 2D Thật
        this.assetManifest = {
            storybookPoses: {
                standing: 'file:///C:/Users/USER/.gemini/antigravity/brain/6f49409f-fe23-4490-984d-4f0e771339c6/bin_point_right_1787725750609.jpg',
                pointing: 'file:///C:/Users/USER/.gemini/antigravity/brain/6f49409f-fe23-4490-984d-4f0e771339c6/bin_point_right_1787725750609.jpg',
                seated_open: 'file:///C:/Users/USER/.gemini/antigravity/brain/6f49409f-fe23-4490-984d-4f0e771339c6/bin_seated_plane_1787725580022.jpg',
                seated_fastened: 'file:///C:/Users/USER/.gemini/antigravity/brain/6f49409f-fe23-4490-984d-4f0e771339c6/bin_seatbelt_fastened_1787725612313.jpg',
                drinking_water: 'file:///C:/Users/USER/.gemini/antigravity/brain/6f49409f-fe23-4490-984d-4f0e771339c6/bin_drink_water_1787725639196.jpg',
                looking_window: 'file:///C:/Users/USER/.gemini/antigravity/brain/6f49409f-fe23-4490-984d-4f0e771339c6/bin_looking_window_1787725671427.jpg',
                whispering: 'file:///C:/Users/USER/.gemini/antigravity/brain/6f49409f-fe23-4490-984d-4f0e771339c6/bin_whisper_sitting_1787725691994.jpg',
                sitting_neat: 'file:///C:/Users/USER/.gemini/antigravity/brain/6f49409f-fe23-4490-984d-4f0e771339c6/bin_whisper_sitting_1787725691994.jpg',
                holding_badge: 'file:///C:/Users/USER/.gemini/antigravity/brain/6f49409f-fe23-4490-984d-4f0e771339c6/bin_holding_badge_1787725718575.jpg'
            }
        };

        this.init();
    }

    init() {
        this.updateAll();
    }

    // ==========================================================================
    // PUBLIC STATE API (GỌI TỪ GAMEPLAY CONTROLLER)
    // ==========================================================================

    setShirt(value) {
        this.characterState.outfit.shirt = value;
        this.updateAll();
    }

    setPants(value) {
        this.characterState.outfit.pants = value;
        this.updateAll();
    }

    setShoes(value) {
        this.characterState.outfit.shoes = value;
        this.updateAll();
    }

    setPose(poseName) {
        this.characterState.pose = poseName;
        this.updateAll();
    }

    setSeatbelt(seatbeltState) {
        this.characterState.seatbelt = seatbeltState; // 'none' | 'open' | 'fastened'
        this.updateAll();
    }

    setHolding(item) {
        this.characterState.holding = item;
        if (item === 'water') {
            this.setPose('drinking_water');
        } else if (item === 'badge') {
            this.setPose('holding_badge');
        } else {
            this.updateAll();
        }
    }

    reset() {
        this.characterState = {
            outfit: { shirt: 'soft', pants: 'soft', shoes: 'velcro' },
            pose: 'standing',
            expression: 'normal',
            seatbelt: 'none',
            holding: null
        };
        this.updateAll();
    }

    // ==========================================================================
    // RENDER ENGINE
    // ==========================================================================

    renderTo(containerEl, customMode = null, customSeatbelt = null) {
        if (!containerEl) return;

        const effectivePose = customMode || this.characterState.pose;
        const effectiveSeatbelt = customSeatbelt !== null ? customSeatbelt : this.characterState.seatbelt;

        let poseKey = effectivePose;
        if (effectivePose === 'seated') {
            poseKey = effectiveSeatbelt === 'fastened' ? 'seated_fastened' : 'seated_open';
        }

        const poseSrc = this.assetManifest.storybookPoses[poseKey] || this.assetManifest.storybookPoses.standing;

        containerEl.innerHTML = '';
        containerEl.classList.add('bin-character-frame');

        const wrapper = document.createElement('div');
        wrapper.className = 'bin-layered-stack';

        const poseImg = document.createElement('img');
        poseImg.className = 'bin-layer bin-layer-pose pop-in-soft';
        poseImg.src = poseSrc;
        poseImg.style.borderRadius = '24px';
        poseImg.alt = `Bé Bin ${effectivePose}`;
        wrapper.appendChild(poseImg);

        containerEl.appendChild(wrapper);
    }

    updateAll() {
        // 1. Mount point Level 1: Bé Bin đứng trực tiếp trong phòng
        const lvl1Mount = document.getElementById('bin-character-mount-lvl1');
        if (lvl1Mount) this.renderTo(lvl1Mount, 'standing');

        // 2. Mount point Level 3 Cổng An Ninh
        const lvl3Mount = document.getElementById('bin-character-mount-lvl3');
        if (lvl3Mount) this.renderTo(lvl3Mount, 'pointing');

        // 3. Mount point Level 5 Ghế Ngồi Khoang Bay
        const lvl5Mount = document.getElementById('bin-character-mount-lvl5');
        if (lvl5Mount) {
            const pose5 = this.characterState.pose === 'drinking_water' ? 'drinking_water' : 'seated';
            this.renderTo(lvl5Mount, pose5, this.characterState.seatbelt);
        }

        // 4. Mount point Level 6 Nhìn Cửa Sổ
        const lvl6Mount = document.getElementById('bin-character-mount-lvl6');
        if (lvl6Mount) this.renderTo(lvl6Mount, 'looking_window');

        // 5. Mount point Level 7 Lịch Sự
        const lvl7Mount = document.getElementById('bin-character-mount-lvl7');
        if (lvl7Mount) {
            const pose7 = this.characterState.pose === 'whispering' ? 'whispering' : (this.characterState.pose === 'sitting_neat' ? 'sitting_neat' : 'seated');
            this.renderTo(lvl7Mount, pose7, 'fastened');
        }

        // 6. Mount point Level 8 Nhận Thưởng
        const lvl8Mount = document.getElementById('bin-character-mount-lvl8');
        if (lvl8Mount) {
            const pose8 = this.characterState.pose === 'holding_badge' ? 'holding_badge' : 'standing';
            this.renderTo(lvl8Mount, pose8);
        }
    }
}

