            return this.assetManifest.outfitSprites.yellow_shirt_blue_pants_shoes;
        }

        // Các kết hợp chuyển tiếp khác
        if (s && sh && !p) return this.assetManifest.outfitSprites.yellow_shirt_only;
        if (p && !s) return this.assetManifest.outfitSprites.base_neutral;

        return this.assetManifest.outfitSprites.yellow_shirt_blue_pants_shoes;
    }

    // ==========================================================================
    // RENDER ENGINE
    // ==========================================================================

    renderTo(containerEl, customMode = null, customSeatbelt = null) {
        if (!containerEl) return;

        const effectivePose = customMode || this.characterState.pose;
        const effectiveSeatbelt = customSeatbelt !== null ? customSeatbelt : this.characterState.seatbelt;

        let rawSrc = '';

        if (effectivePose === 'level1_outfit') {
            rawSrc = this.getOutfitSprite();
        } else if (effectivePose === 'seated') {
            const poseKey = effectiveSeatbelt === 'fastened' ? 'seated_fastened' : 'seated_open';
            rawSrc = this.assetManifest.storybookPoses[poseKey];
        } else {
            rawSrc = this.assetManifest.storybookPoses[effectivePose] || this.assetManifest.storybookPoses.standing;
        }

        containerEl.innerHTML = '';
        containerEl.classList.add('bin-character-frame');

        const wrapper = document.createElement('div');
        wrapper.className = 'bin-layered-stack';

        const poseImg = document.createElement('img');
        poseImg.className = 'bin-layer bin-layer-pose pop-in-soft';
        poseImg.alt = `Bé Bin ${effectivePose}`;
        poseImg.style.opacity = '1';

        this.getTransparentImage(rawSrc, (cleanSrc) => {
            poseImg.src = cleanSrc;
        });

        wrapper.appendChild(poseImg);
        containerEl.appendChild(wrapper);
    }

    updateAll() {
        // 1. Mount point Level 1: Bé Bin thay đổi trang phục thật qua Outfit State Machine
        const lvl1Mount = document.getElementById('bin-character-mount-lvl1');
        if (lvl1Mount) this.renderTo(lvl1Mount, 'level1_outfit');

        // 2. Mount point Level 3 Cổng An Ninh
        const lvl3Mount = document.getElementById('bin-character-mount-lvl3');
        if (lvl3Mount) this.renderTo(lvl3Mount, 'pointing');

        // 3. Mount point Level 5 Ghế Ngồi Khoang Bay
        const lvl5Mount = document.getElementById('bin-character-mount-lvl5');
        if (lvl5Mount) {
            const pose5 = this.characterState.pose === 'drinking_water' ? 'drinking_water' : 'seated';
            this.renderTo(lvl5Mount, pose5, this.characterState.seatbelt);
        }

        // 4. Mount point Level 6 Nhìn Cửa Sổ
        const lvl6Mount = document.getElementById('bin-character-mount-lvl6');
        if (lvl6Mount) this.renderTo(lvl6Mount, 'looking_window');

        // 5. Mount point Level 7 Lịch Sự
        const lvl7Mount = document.getElementById('bin-character-mount-lvl7');
        if (lvl7Mount) {
            const pose7 = this.characterState.pose === 'whispering' ? 'whispering' : (this.characterState.pose === 'sitting_neat' ? 'sitting_neat' : 'seated');
            this.renderTo(lvl7Mount, pose7, 'fastened');
        }

        // 6. Mount point Level 8 Nhận Thưởng
        const lvl8Mount = document.getElementById('bin-character-mount-lvl8');
        if (lvl8Mount) {
            const pose8 = this.characterState.pose === 'holding_badge' ? 'holding_badge' : 'standing';
            this.renderTo(lvl8Mount, pose8);
        }
    }
}

// Khởi tạo instance toàn cục
window.binRenderer = new CharacterRenderer();

/**
 * app.js - Main Controller for "Cùng Bé Bin Đi Máy Bay" (8 Levels)
 * Chuẩn Storybook 2D Co-Play (BIN_SOFT_STORYBOOK_2D_V1)
 * - Quần áo thay đổi thật 100% qua Outfit State Machine
 * - Không SpeechSynthesis / Không đọc tự động
 */

class KidFlightApp {
    constructor() {
        this.currentScreen = 1;
        this.totalScreens = 8;
        this.maxUnlockedLevel = 1;

        // Tránh duplicate event listeners
        this.levelInitialized = {
            1: false, 2: false, 3: false, 4: false,
            5: false, 6: false, 7: false, 8: false
        };

        // State theo dõi các nhiệm vụ
        this.level1Dressed = { shirt: false, pants: false, shoes: false };
        this.level2Packed = 0;
        this.level3Steps = { checkin: false, xrayCount: 0, gate: false };
        this.level4Completed = false;
        this.level5Belt = { inserted: false, earRelieved: false };
        this.level6Clouds = { c1: false, c2: false, c3: false, c4: false };
        this.level7Tasks = { volume: false, leg: false };
        this.level8State = { planeStopped: false, unbuckled: false, baggage: false };

        this.parentHoldStart = 0;
        this.parentHoldReqId = null;

        this.init();
    }

    init() {
        this.bindGlobalEvents();
        if (window.binRenderer) {
            window.binRenderer.updateAll();
        }
        this.initLevel(1);
        this.showScreen(1);
    }

    // --- BIỂN BÁO LỜI THOẠI BA MẸ ĐỌC (KHÔNG SPEECH SYNTHESIS) ---
    showParentPrompt(speaker, text) {
        if (window.dialogueMgr) {
            window.dialogueMgr.show(speaker, text);
        }
    }

    // --- NAVIGATION & PROGRESS LOCKING CONTROLLER ---
    unlockLevel(levelNum) {
        if (levelNum > this.maxUnlockedLevel && levelNum <= this.totalScreens) {
            this.maxUnlockedLevel = levelNum;
            const dot = document.querySelector(`.stage-dot[data-screen="${levelNum}"]`);
            if (dot) {
                dot.classList.remove('locked');
            }
        }
    }

    showScreen(screenNum) {
        if (screenNum < 1 || screenNum > this.totalScreens) return;

        if (this.currentScreen === 5 && screenNum !== 5) {
            if (window.audioMgr) window.audioMgr.stopEngineSound();
        }

        this.currentScreen = screenNum;
        this.unlockLevel(screenNum);

        document.querySelectorAll('.screen').forEach((scr, idx) => {
            if (idx + 1 === screenNum) {
                scr.classList.add('active');
            } else {
                scr.classList.remove('active');
            }
        });

        document.querySelectorAll('.stage-dot').forEach((dot, idx) => {
            const level = idx + 1;
            dot.classList.remove('active', 'completed', 'locked');

            if (level === screenNum) {
                dot.classList.add('active');
            } else if (level < screenNum || level <= this.maxUnlockedLevel) {
                dot.classList.add('completed');
            } else {
                dot.classList.add('locked');
            }
        });

        this.updateCharacterForScreen(screenNum);
        this.initLevel(screenNum);
        this.setInitialScreenDialogue(screenNum);
    }

    updateCharacterForScreen(screenNum) {
        if (!window.binRenderer) return;

        switch (screenNum) {
            case 1:
                window.binRenderer.renderTo(document.getElementById('bin-character-mount-lvl1'), 'level1_outfit');
                break;
            case 2:
            case 3:
            case 4:
                window.binRenderer.setPose('standing');
                window.binRenderer.setSeatbelt('none');
                break;
            case 5:
                window.binRenderer.setPose('seated');
                window.binRenderer.setSeatbelt(this.level5Belt.inserted ? 'fastened' : 'open');
                break;
            case 6:
                window.binRenderer.setPose('looking_window');
                window.binRenderer.setSeatbelt('fastened');
                break;
            case 7:
                if (this.level7Tasks.volume && !this.level7Tasks.leg) {
                    window.binRenderer.setPose('whispering');
                } else if (this.level7Tasks.leg) {
                    window.binRenderer.setPose('sitting_neat');
                } else {
                    window.binRenderer.setPose('seated');
                }
                window.binRenderer.setSeatbelt('fastened');
                break;
            case 8:
                if (this.level8State.baggage) {
                    window.binRenderer.setPose('holding_badge');
                } else {
                    window.binRenderer.setPose('standing');
                }
                window.binRenderer.setSeatbelt(this.level8State.unbuckled ? 'open' : 'fastened');
                break;
        }
    }

    setInitialScreenDialogue(screenNum) {
        switch (screenNum) {
            case 1:
                this.showParentPrompt('Mẹ', '“Bin sắp đi máy bay rồi. Con chọn bộ đồ nào giúp Bin dễ vận động nhé!”');
                break;
            case 2:
                this.showParentPrompt('Bố', '“Bin mang gì đi máy bay nhỉ? Con xếp vali giúp Bin nhé!”');
                break;
            case 3:
                this.showParentPrompt('Mẹ', '“Đến chỗ kiểm tra an ninh rồi. Bin đi cùng Ba Mẹ và làm theo hướng dẫn nhé!”');
                break;
            case 4:
                this.showParentPrompt('Bố', '“Vé của Bin ghi số 03. Con tìm cổng số 03 nhé!”');
                break;
            case 5:
                this.showParentPrompt('Mẹ', '“Con giúp Bin cài dây an toàn nhé!”');
                break;
            case 6:
                this.showParentPrompt('Bin', '“Bin thấy đám mây giống hình gì nhỉ? Con nhìn cùng Bin nhé!”');
                break;
            case 7:
                this.showParentPrompt('Mẹ', '“Trên máy bay mình nói nhỏ vừa đủ nghe nhé. Con giúp Bin nào!”');
                break;
            case 8:
                this.level8State.planeStopped = false;
                this.level8State.unbuckled = false;
                this.showParentPrompt('Bố', '“Máy bay đang chạy vào chỗ đỗ. Bin vẫn ngồi yên và giữ dây an toàn nhé!”');

                const unbuckleBtn = document.getElementById('unbuckle-latch-btn');
                if (unbuckleBtn) {
                    unbuckleBtn.setAttribute('disabled', 'true');
                    unbuckleBtn.style.opacity = '0.6';
                    unbuckleBtn.style.borderColor = '#78909C';
                    unbuckleBtn.innerHTML = '<span>⏳ Máy bay đang chạy vào bãi đỗ...</span>';
                }

                setTimeout(() => {
                    this.level8State.planeStopped = true;
                    if (unbuckleBtn) {
                        unbuckleBtn.removeAttribute('disabled');
                        unbuckleBtn.style.opacity = '1';
                        unbuckleBtn.style.borderColor = '#00E676';
                        unbuckleBtn.innerHTML = '<span>🔓 Máy bay đã dừng hẳn — Mở dây an toàn</span>';
                    }
                    this.showParentPrompt('Mẹ', '“Máy bay dừng hẳn rồi. Bây giờ mình mới mở dây nhé!”');
                }, 2600);
                break;
        }
    }

    // --- GLOBAL EVENTS & CỔNG BA MẸ CONTROLLER ---
    bindGlobalEvents() {
        const parentBtn = document.getElementById('btn-parent-gate');
        const holdCircle = document.getElementById('parent-ring-circle');
        const modal = document.getElementById('parent-modal');
        const closeModalBtn = document.getElementById('btn-close-parent');

        if (parentBtn && holdCircle) {
            const startHold = (e) => {
                e.preventDefault();
                this.parentHoldStart = Date.now();
                const totalHold = 3000;

                const updateRing = () => {
                    const elapsed = Date.now() - this.parentHoldStart;
                    const progress = Math.min(1, elapsed / totalHold);
                    const offset = 175 - (175 * progress);
                    holdCircle.style.strokeDashoffset = offset;

                    if (progress >= 1) {
                        if (window.audioMgr) window.audioMgr.playTing();
                        modal.classList.add('open');
                        resetHold();
                    } else {
                        this.parentHoldReqId = requestAnimationFrame(updateRing);
                    }
                };

                this.parentHoldReqId = requestAnimationFrame(updateRing);
            };

            const resetHold = () => {
                if (this.parentHoldReqId) cancelAnimationFrame(this.parentHoldReqId);
                holdCircle.style.strokeDashoffset = 175;
            };

            parentBtn.addEventListener('pointerdown', startHold);
            parentBtn.addEventListener('pointerup', resetHold);
            parentBtn.addEventListener('pointerleave', resetHold);
            parentBtn.addEventListener('pointercancel', resetHold);
        }

        if (closeModalBtn && modal) {
            closeModalBtn.addEventListener('click', () => {
                if (window.audioMgr) window.audioMgr.playPop();
                modal.classList.remove('open');
            });
        }

        const volSlider = document.getElementById('setting-volume');
        if (volSlider) {
            volSlider.addEventListener('input', (e) => {
                if (window.audioMgr) window.audioMgr.volume = parseFloat(e.target.value);
            });
        }

        const motionToggle = document.getElementById('setting-reduced-motion');
        if (motionToggle) {
            motionToggle.addEventListener('change', (e) => {
                if (window.effectsMgr) window.effectsMgr.reducedMotion = e.target.checked;
            });
        }

        const resetBtn = document.getElementById('btn-reset-app');
        if (resetBtn) {
            resetBtn.addEventListener('click', () => {
                if (window.binRenderer) window.binRenderer.reset();
                window.location.reload();
            });
        }

        document.querySelectorAll('.jump-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const target = parseInt(btn.getAttribute('data-level'), 10);
                if (target) {
                    if (window.audioMgr) window.audioMgr.playPop();
                    modal.classList.remove('open');
                    this.unlockLevel(target);
                    this.showScreen(target);
                }
            });
        });

        document.querySelectorAll('.stage-dot').forEach((dot) => {
            dot.addEventListener('click', () => {
                const targetScreen = parseInt(dot.getAttribute('data-screen'), 10);
                if (!dot.classList.contains('locked') && targetScreen && targetScreen <= this.maxUnlockedLevel) {
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.showScreen(targetScreen);
                }
            });
        });
    }

    initLevel(levelNum) {
        if (this.levelInitialized[levelNum]) return;
        this.levelInitialized[levelNum] = true;

        switch (levelNum) {
            case 1: this.initLevel1(); break;
            case 2: this.initLevel2(); break;
            case 3: this.initLevel3(); break;
            case 4: this.initLevel4(); break;
            case 5: this.initLevel5(); break;
            case 6: this.initLevel6(); break;
            case 7: this.initLevel7(); break;
            case 8: this.initLevel8(); break;
        }
    }

    // ==========================================================================
    // LEVEL 1: CHỌN TRANG PHỤC (OUTFIT STATE MACHINE THAY ĐỔI THẬT)
    // ==========================================================================
    initLevel1() {
        const clothesTiles = document.querySelectorAll('#screen-1 [data-clothing-item="true"]');
        const binTarget = document.getElementById('bin-dress-target');
        const btnNext1 = document.getElementById('btn-next-level-1');

        const applyClothingItem = (tile) => {
            const isFit = tile.getAttribute('data-fit') === 'soft';
            const type = tile.getAttribute('data-type');
            const binRect = binTarget.getBoundingClientRect();

            if (isFit && window.binRenderer) {
                if (type === 'shirt') {
                    this.level1Dressed.shirt = true;
                    window.binRenderer.setShirt('yellow');
                } else if (type === 'pants') {
                    this.level1Dressed.pants = true;
                    window.binRenderer.setPants('blue');
                } else if (type === 'shoes') {
                    this.level1Dressed.shoes = true;
                    window.binRenderer.setShoes('velcro');
                }

                if (window.effectsMgr) {
                    window.effectsMgr.burstStarsAt(binRect.left + binRect.width / 2, binRect.top + binRect.height / 2);
                }
                if (window.audioMgr) window.audioMgr.playTing();

                this.showParentPrompt('Mẹ', '“Đúng rồi! Món này mềm và dễ vận động.”');

                // Kiểm tra hoàn thành đủ 3 món
                if (this.level1Dressed.shirt && this.level1Dressed.pants && this.level1Dressed.shoes) {
                    this.unlockLevel(2);
                    if (btnNext1) {
                        btnNext1.classList.remove('hidden');
                        btnNext1.classList.add('pop-in');
                    }
                    this.showParentPrompt('Mẹ', '“Bin sẵn sàng rồi! Mình đi xếp vali nhé!”');
                }
            } else {
                tile.classList.add('shake-wobble');
                setTimeout(() => { tile.classList.remove('shake-wobble'); }, 500);

                tile.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
                tile.style.transform = 'translate(0px, 0px)';
                if (window.audioMgr) window.audioMgr.playBoing();
                this.showParentPrompt('Bố', '“Món này hơi bất tiện. Con thử món khác nhé!”');
            }
        };

        clothesTiles.forEach(tile => {
            let startX = 0, startY = 0;
            let isDragging = false;

            const onDown = (e) => {
                isDragging = true;
                tile.setPointerCapture(e.pointerId);
                startX = e.clientX;
                startY = e.clientY;
                tile.style.zIndex = '999';
            };

            const onMove = (e) => {
                if (!isDragging) return;
                const dx = e.clientX - startX;
                const dy = e.clientY - startY;
                tile.style.transform = `translate(${dx}px, ${dy}px) scale(1.15)`;
            };

            const onUp = (e) => {
                if (!isDragging) return;
                isDragging = false;
                tile.releasePointerCapture(e.pointerId);

                const tileRect = tile.getBoundingClientRect();
                const binRect = binTarget.getBoundingClientRect();

                const isOver = !(
                    tileRect.right < binRect.left ||
                    tileRect.left > binRect.right ||
                    tileRect.bottom < binRect.top ||
                    tileRect.top > binRect.bottom
                );

                if (isOver) {
                    applyClothingItem(tile);
                    tile.style.transform = 'translate(0px, 0px)';
                } else {
                    tile.style.transition = 'transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)';
                    tile.style.transform = 'translate(0px, 0px)';
                }
            };

            tile.addEventListener('pointerdown', onDown);
            tile.addEventListener('pointermove', onMove);
            tile.addEventListener('pointerup', onUp);
            tile.addEventListener('pointercancel', onUp);

            tile.addEventListener('click', () => {
                applyClothingItem(tile);
            });
        });

        if (btnNext1) {
            btnNext1.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(2);
            };
        }
    }

    // ==========================================================================
    // LEVEL 2: XẾP VALI (PACK / ASK_PARENT / LEAVE_HOME)
    // ==========================================================================
    initLevel2() {
        const luggageItems = document.querySelectorAll('#screen-2 [data-luggage-item="true"]');
        const suitcase = document.getElementById('suitcase-target-lvl2');
        const suitcaseInner = document.getElementById('suitcase-inner-lvl2');
        const btnNext2 = document.getElementById('btn-next-level-2');

        const tryPackLuggage = (item) => {
            if (item.classList.contains('packed')) return;
            const category = item.getAttribute('data-category');
            const suitcaseRect = suitcase.getBoundingClientRect();

            if (category === 'PACK') {
                item.classList.add('packed');
                item.style.display = 'none';

                if (suitcase) {
                    suitcase.classList.add('packed-bounce');
                    setTimeout(() => { suitcase.classList.remove('packed-bounce'); }, 450);
                }

                const icon = item.querySelector('.item-icon');
                if (icon && icon.tagName === 'IMG') {
                    const imgClone = document.createElement('img');
                    imgClone.src = icon.src;
                    imgClone.style.width = '52px';
                    imgClone.style.height = '52px';
                    imgClone.style.objectFit = 'contain';
                    imgClone.className = 'pop-in';
                    suitcaseInner.appendChild(imgClone);
                } else {
                    const iconSpan = document.createElement('span');
                    iconSpan.textContent = icon ? icon.textContent : '📦';
                    iconSpan.style.fontSize = '34px';
                    iconSpan.className = 'pop-in';
                    suitcaseInner.appendChild(iconSpan);
                }

                this.level2Packed++;

                if (window.effectsMgr) {
                    window.effectsMgr.burstStarsAt(suitcaseRect.left + suitcaseRect.width / 2, suitcaseRect.top + suitcaseRect.height / 2);
                }
                if (window.audioMgr) window.audioMgr.playTing();

                this.showParentPrompt('Mẹ', '“Ừ! Món này mình xếp vào vali nhé.”');

                if (this.level2Packed >= 3) {
                    this.showParentPrompt('Mẹ', '“Vali của Bin đã sẵn sàng rồi! Cùng đến sân bay thôi!”');
                    this.unlockLevel(3);
                    if (btnNext2) {
                        btnNext2.classList.remove('hidden');
                        btnNext2.classList.add('pop-in');
                    }
                }
            } else if (category === 'ASK_PARENT') {
                item.classList.add('shake-wobble');
                setTimeout(() => { item.classList.remove('shake-wobble'); }, 500);

                item.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
                item.style.transform = 'translate(0px, 0px)';
                if (window.audioMgr) window.audioMgr.playPop();
                this.showParentPrompt('Bố', '“Món này mình hỏi Ba Mẹ trước nhé!”');
            } else {
                item.classList.add('shake-wobble');
                setTimeout(() => { item.classList.remove('shake-wobble'); }, 500);

                item.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
                item.style.transform = 'translate(0px, 0px)';
                if (window.audioMgr) window.audioMgr.playBoing();
                this.showParentPrompt('Bố', '“Món này để Ba Mẹ giúp mình xử lý nhé.”');
            }
        };

        luggageItems.forEach(item => {
            let startX = 0, startY = 0;
            let isDragging = false;

            const onDown = (e) => {
                if (item.classList.contains('packed')) return;
                isDragging = true;
                item.setPointerCapture(e.pointerId);
                startX = e.clientX;
                startY = e.clientY;
                item.style.zIndex = '999';
            };

            const onMove = (e) => {
                if (!isDragging) return;
                const dx = e.clientX - startX;
                const dy = e.clientY - startY;
                item.style.transform = `translate(${dx}px, ${dy}px) scale(1.15)`;
            };

            const onUp = (e) => {
                if (!isDragging) return;
                isDragging = false;
                item.releasePointerCapture(e.pointerId);

                const itemRect = item.getBoundingClientRect();
                const suitcaseRect = suitcase.getBoundingClientRect();

                const isOver = !(
                    itemRect.right < suitcaseRect.left ||
                    itemRect.left > suitcaseRect.right ||
                    itemRect.bottom < suitcaseRect.top ||
                    itemRect.top > suitcaseRect.bottom
                );

                if (isOver) {
                    tryPackLuggage(item);
                } else {
                    item.style.transition = 'transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)';
                    item.style.transform = 'translate(0px, 0px)';
                }
            };

            item.addEventListener('pointerdown', onDown);
            item.addEventListener('pointermove', onMove);
            item.addEventListener('pointerup', onUp);
            item.addEventListener('pointercancel', onUp);

            item.addEventListener('click', () => {
                if (!item.classList.contains('packed')) {
                    tryPackLuggage(item);
                }
            });
        });

        if (btnNext2) {
            btnNext2.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(3);
            };
        }
    }

    // ==========================================================================
    // LEVEL 3: KIỂM TRA AN NINH (3 TRẠM)
    // ==========================================================================
    initLevel3() {
        const passCard = document.getElementById('pass-card-lvl3');
        const stampBadge = document.getElementById('stamp-badge-lvl3');
        const xrayBoxes = document.querySelectorAll('#screen-3 .xray-tap-box');
        const gate = document.getElementById('gate-detector-lvl3');
        const lamps = document.querySelectorAll('#screen-3 .gate-lamp-led');
        const binMount3 = document.getElementById('bin-character-mount-lvl3');
        const btnNext3 = document.getElementById('btn-next-level-3');

        if (passCard) {
            passCard.onclick = () => {
                if (this.level3Steps.checkin) return;
                this.level3Steps.checkin = true;
                if (stampBadge) stampBadge.classList.add('stamped');
                if (window.audioMgr) window.audioMgr.playStamp();

                if (window.effectsMgr) {
                    const r = passCard.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }

                this.showParentPrompt('Tiếp viên', '“Vé của Bin xong rồi! Giờ soi chiếu vali nhé.”');
                this.checkLevel3Completion();
            };
        }

        xrayBoxes.forEach(box => {
            box.onclick = () => {
                if (box.getAttribute('data-revealed') === 'true') return;
                box.setAttribute('data-revealed', 'true');
                box.textContent = box.getAttribute('data-item');
                box.style.background = '#FFF9C4';
                box.classList.add('revealed-pulse');
                this.level3Steps.xrayCount++;

                if (window.audioMgr) window.audioMgr.playTing();
                if (window.effectsMgr) {
                    const r = box.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }

                if (this.level3Steps.xrayCount >= 3) {
                    this.showParentPrompt('Mẹ', '“Vali của Bin an toàn rồi! Chạm để Bin qua cổng nhé.”');
                    this.checkLevel3Completion();
                }
            };
        });

        if (gate) {
            gate.onclick = () => {
                if (this.level3Steps.gate) return;
                this.level3Steps.gate = true;

                lamps.forEach(l => l.classList.add('green-flash'));
                if (binMount3) binMount3.style.transform = 'translateY(-14px) scale(1.1)';

                if (window.audioMgr) window.audioMgr.playBeepBoing ? window.audioMgr.playBeepBoing() : window.audioMgr.playBeepBoop();
                if (window.effectsMgr) {
                    const r = gate.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }

                this.showParentPrompt('Mẹ', '“Giỏi lắm! Bin đã qua khu kiểm tra an ninh rồi.”');
                this.checkLevel3Completion();
            };
        }

        if (btnNext3) {
            btnNext3.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(4);
            };
        }
    }

    checkLevel3Completion() {
        const btnNext3 = document.getElementById('btn-next-level-3');
        if (this.level3Steps.checkin && this.level3Steps.xrayCount >= 3 && this.level3Steps.gate) {
            this.unlockLevel(4);
            if (btnNext3) {
                btnNext3.classList.remove('hidden');
                btnNext3.classList.add('pop-in');
            }
        }
    }

    // ==========================================================================
    // LEVEL 4: RA CỔNG BAY (TÌM CỔNG 03)
    // ==========================================================================
    initLevel4() {
        const gatePillars = document.querySelectorAll('#screen-4 .gate-pillar');
        const btnNext4 = document.getElementById('btn-next-level-4');

        gatePillars.forEach(pillar => {
            pillar.onclick = () => {
                const targetGate = pillar.getAttribute('data-gate');

                if (targetGate === '03') {
                    this.level4Completed = true;
                    pillar.classList.add('matched');

                    if (window.effectsMgr) {
                        const r = pillar.getBoundingClientRect();
                        window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                    }
                    if (window.audioMgr) window.audioMgr.playConnect();

                    this.showParentPrompt('Tiếp viên', '“Đúng rồi! Cổng 03 đây rồi! Chào mừng Bin lên máy bay!”');
                    this.unlockLevel(5);

                    if (btnNext4) {
                        btnNext4.classList.remove('hidden');
                        btnNext4.classList.add('pop-in');
                    }
                } else {
                    pillar.classList.add('shake-wobble');
                    setTimeout(() => { pillar.classList.remove('shake-wobble'); }, 500);

                    if (window.audioMgr) window.audioMgr.playBoing();
                    this.showParentPrompt('Bố', '“Con nhìn lại số trên vé nhé!”');
                }
            };
        });

        if (btnNext4) {
            btnNext4.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(5);
            };
        }
    }

    // ==========================================================================
    // LEVEL 5: ĐAI AN TOÀN & UỐNG NƯỚC (RENDERER SEATBELT & DRINKING)
    // ==========================================================================
    initLevel5() {
        const strapLeft = document.getElementById('seatbelt-strap-lvl5');
        const puzzleBox = document.getElementById('seatbelt-puzzle-lvl5');
        const safetySign = document.getElementById('safety-sign-lvl5');
        const knightCape = document.getElementById('bin-knight-cape');
        const btnWater = document.getElementById('btn-drink-water-lvl5');
        const earWaves = document.querySelectorAll('#screen-5 .ear-soundwave');
        const btnNext5 = document.getElementById('btn-next-level-5');

        const tryBuckleBelt = () => {
            if (this.level5Belt.inserted) return;
            this.level5Belt.inserted = true;
            puzzleBox.classList.add('seatbelt-buckled');

            if (window.binRenderer) {
                window.binRenderer.setSeatbelt('fastened');
            }

            if (safetySign) safetySign.classList.add('green-safe');
            if (knightCape) knightCape.classList.add('active');

            if (window.audioMgr) {
                window.audioMgr.playClack();
                window.audioMgr.startEngineSound(0.22);
            }

            if (window.effectsMgr) {
                const r = puzzleBox.getBoundingClientRect();
                window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
            }

            this.showParentPrompt('Mẹ', '“CẠCH! Dây an toàn chắc chắn rồi!”');

            setTimeout(() => {
                earWaves.forEach(w => w.classList.remove('hidden'));
                if (btnWater) btnWater.classList.remove('hidden');
                this.showParentPrompt('Mẹ', '“Tai Bin hơi khó chịu. Bin uống một ngụm nước nhé.”');
            }, 2500);
        };

        if (strapLeft && puzzleBox) {
            let isDragging = false;
            let startX = 0;

            const onDown = (e) => {
                if (this.level5Belt.inserted) return;
                isDragging = true;
                strapLeft.setPointerCapture(e.pointerId);
                startX = e.clientX;
            };

            const onMove = (e) => {
                if (!isDragging || this.level5Belt.inserted) return;
                const dx = Math.max(0, Math.min(45, e.clientX - startX));
                strapLeft.style.transform = `translateX(${dx}px)`;

                if (dx >= 35) {
                    tryBuckleBelt();
                }
            };

            const onUp = (e) => {
                if (!isDragging) return;
                isDragging = false;
                strapLeft.releasePointerCapture(e.pointerId);
                if (!this.level5Belt.inserted) {
                    strapLeft.style.transform = 'translateX(0px)';
                }
            };

            strapLeft.addEventListener('pointerdown', onDown);
            strapLeft.addEventListener('pointermove', onMove);
            strapLeft.addEventListener('pointerup', onUp);

            puzzleBox.addEventListener('click', () => {
                tryBuckleBelt();
            });
        }

        if (btnWater) {
            btnWater.onclick = () => {
                if (this.level5Belt.earRelieved) return;
                this.level5Belt.earRelieved = true;

                if (window.binRenderer) {
                    window.binRenderer.setPose('drinking_water');
                }

                earWaves.forEach(w => w.classList.add('hidden'));

                if (window.effectsMgr) {
                    const binHead = document.getElementById('bin-character-mount-lvl5');
                    if (binHead) {
                        const r = binHead.getBoundingClientRect();
                        window.effectsMgr.spawnMusicNotesAt(r.left + r.width / 2, r.top);
                    }
                }

                if (window.audioMgr) window.audioMgr.playDrinkWater();
                this.showParentPrompt('Bin', '“Tai Bin dễ chịu hơn rồi!”');
                this.unlockLevel(6);

                setTimeout(() => {
                    if (window.binRenderer) {
                        window.binRenderer.setPose('seated');
                    }
                }, 2800);

                if (btnNext5) {
                    btnNext5.classList.remove('hidden');
                    btnNext5.classList.add('pop-in');
                }
            };
        }

        if (btnNext5) {
            btnNext5.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(6);
            };
        }
    }

    // ==========================================================================
    // LEVEL 6: NGẮM MÂY BIẾN HÌNH (BIN LOOKING WINDOW)
    // ==========================================================================
    initLevel6() {
        const cloudTiles = document.querySelectorAll('#screen-6 .morph-cloud-tile');
        const btnNext6 = document.getElementById('btn-next-level-6');

        cloudTiles.forEach(tile => {
            tile.onclick = () => {
                if (tile.classList.contains('morphed')) return;
                tile.classList.add('morphed');

                const morphType = tile.getAttribute('data-morph');
                const icon = tile.querySelector('.cloud-icon');
                const label = tile.querySelector('.cloud-label');

                if (morphType === 'bunny') {
                    icon.textContent = '🐰';
                    label.textContent = 'Chú thỏ';
                    this.level6Clouds.c1 = true;
                    this.showParentPrompt('Bin', '“Bin thấy giống chú thỏ! Còn con thấy giống gì?”');
                } else if (morphType === 'car') {
                    icon.textContent = '🚗';
                    label.textContent = 'Chiếc ô tô';
                    this.level6Clouds.c2 = true;
                    this.showParentPrompt('Bin', '“Bin thấy giống ô tô chạy! Còn con thấy giống gì?”');
                } else if (morphType === 'watermelon') {
                    icon.textContent = '🍉';
                    label.textContent = 'Miếng dưa hấu';
                    this.level6Clouds.c3 = true;
                    this.showParentPrompt('Bin', '“Bin thấy giống miếng dưa hấu! Còn con thấy giống gì?”');
                } else if (morphType === 'bear') {
                    icon.textContent = '🐻';
                    label.textContent = 'Chú gấu';
                    this.level6Clouds.c4 = true;
                    this.showParentPrompt('Bin', '“Bin thấy giống chú gấu vẫy tay! Còn con thấy giống gì?”');
                }

                if (window.effectsMgr) {
                    const r = tile.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }
                if (window.audioMgr) window.audioMgr.playBling();

                if (this.level6Clouds.c1 && this.level6Clouds.c2 && this.level6Clouds.c3 && this.level6Clouds.c4) {
                    this.unlockLevel(7);
                    if (btnNext6) {
                        btnNext6.classList.remove('hidden');
                        btnNext6.classList.add('pop-in');
                    }
                }
            };
        });

        if (btnNext6) {
            btnNext6.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(7);
            };
        }
    }

    // ==========================================================================
    // LEVEL 7: LỊCH SỰ (3 MỨC ÂM LƯỢNG & THU CHÂN)
    // ==========================================================================
    initLevel7() {
        const emotionBtns = document.querySelectorAll('#screen-7 .volume-emotion-btn');
        const legTarget = document.getElementById('bin-leg-target');
        const legLabel = document.getElementById('leg-status-label');
        const btnNext7 = document.getElementById('btn-next-level-7');

        emotionBtns.forEach(btn => {
            btn.onclick = () => {
                emotionBtns.forEach(b => b.classList.remove('selected'));
                btn.classList.add('selected');
                const level = btn.getAttribute('data-level');

                if (level === 'loud') {
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.showParentPrompt('Mẹ', '“Ơ, hơi to rồi. Con thử nhỏ hơn nhé!”');
                } else if (level === 'medium') {
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.showParentPrompt('Mẹ', '“Nhỏ hơn một chút nữa nhé!”');
                } else if (level === 'whisper') {
                    this.level7Tasks.volume = true;
                    if (window.binRenderer) {
                        window.binRenderer.setPose('whispering');
                    }

                    if (window.effectsMgr) {
                        const r = btn.getBoundingClientRect();
                        window.effectsMgr.spawnFloatingHeartsAt(r.left + r.width / 2, r.top);
                    }
                    if (window.audioMgr) window.audioMgr.playTing();
                    this.showParentPrompt('Bin', '“Đúng rồi! Mình nói nhỏ vừa đủ nghe nhé.”');

                    if (!this.level7Tasks.leg) {
                        setTimeout(() => {
                            this.showParentPrompt('Mẹ', '“Bin thu chân gọn lại để không chạm ghế phía trước nhé!”');
                        }, 2200);
                    }

                    this.checkLevel7Completion();
                }
            };
        });

        if (legTarget) {
            legTarget.onclick = () => {
                if (this.level7Tasks.leg) return;
                this.level7Tasks.leg = true;

                if (window.binRenderer) {
                    window.binRenderer.setPose('sitting_neat');
                }

                legTarget.style.transform = 'translateY(14px)';
                if (legLabel) legLabel.textContent = 'Chân Bin đã thu lại ngay ngắn ✓';

                if (window.effectsMgr) {
                    const r = legTarget.getBoundingClientRect();
                    window.effectsMgr.spawnFloatingHeartsAt(r.left + r.width / 2, r.top);
                }

                if (window.audioMgr) window.audioMgr.playTing();
                this.showParentPrompt('Bố', '“Giỏi lắm! Bin ngồi gọn rồi, không đạp ghế trước!”');
                this.checkLevel7Completion();
            };
        }

        if (btnNext7) {
            btnNext7.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                this.showScreen(8);
            };
        }
    }

    checkLevel7Completion() {
        const btnNext7 = document.getElementById('btn-next-level-7');
        if (this.level7Tasks.volume && this.level7Tasks.leg) {
            this.unlockLevel(8);
            if (btnNext7) {
                btnNext7.classList.remove('hidden');
                btnNext7.classList.add('pop-in');
            }
        }
    }

    // ==========================================================================
    // LEVEL 8: HẠ CÁNH, MỞ ĐAI & NHẬN VALI THƯỞNG
    // ==========================================================================
    initLevel8() {
        const unbuckleLatch = document.getElementById('unbuckle-latch-btn');
        const baggageCarousel = document.getElementById('baggage-carousel-lvl8');
        const bags = document.querySelectorAll('#screen-8 .carousel-bag-tile');
        const medalModal = document.getElementById('golden-medal-modal');
        const btnReplay = document.getElementById('btn-replay-adventure');

        if (unbuckleLatch) {
            unbuckleLatch.onclick = () => {
                if (!this.level8State.planeStopped) {
                    this.showParentPrompt('Bố', '“Máy bay đang chạy vào chỗ đỗ. Bin vẫn ngồi yên và giữ dây an toàn nhé!”');
                    return;
                }

                if (this.level8State.unbuckled) return;
                this.level8State.unbuckled = true;

                if (window.binRenderer) {
                    window.binRenderer.setSeatbelt('open');
                }

                unbuckleLatch.innerHTML = '<span>🔓 Đai an toàn đã mở ✓</span>';
                unbuckleLatch.style.borderColor = '#00E676';

                if (window.audioMgr) window.audioMgr.playUnbuckle();
                this.showParentPrompt('Bố', '“Con tìm chiếc vali đỏ có hình gấu của Bin nhé!”');

                if (baggageCarousel) baggageCarousel.classList.remove('hidden');
            };
        }

        bags.forEach(bag => {
            bag.onclick = () => {
                if (!this.level8State.unbuckled) {
                    this.showParentPrompt('Mẹ', '“Máy bay dừng hẳn rồi. Bây giờ mình mới mở dây an toàn nhé!”');
                    return;
                }

                const isBinBag = bag.getAttribute('data-is-bin') === 'true';

                if (isBinBag) {
                    this.level8State.baggage = true;
                    bag.style.transform = 'scale(1.3) translateY(-14px)';
                    const track = document.querySelector('.carousel-suitcases-track');
                    if (track) track.classList.add('paused');

                    if (window.binRenderer) {
                        window.binRenderer.setPose('holding_badge');
                    }

                    if (window.effectsMgr) {
                        window.effectsMgr.startCelebrationFireworks(3000);
                    }

                    if (window.audioMgr) window.audioMgr.playFanfare();
                    this.showParentPrompt('Mẹ', '“Hoan hô! Bin tìm đúng vali rồi!”');

                    setTimeout(() => {
                        if (medalModal) medalModal.classList.add('show');
                    }, 1200);
                } else {
                    bag.classList.add('shake-wobble');
                    setTimeout(() => { bag.classList.remove('shake-wobble'); }, 500);

                    if (window.audioMgr) window.audioMgr.playBoing();
                    this.showParentPrompt('Bố', '“Vali này của bạn khác rồi. Con tìm lại nhé!”');
                }
            };
        });

        if (btnReplay) {
            btnReplay.onclick = () => {
                if (window.audioMgr) window.audioMgr.playPop();
                if (window.binRenderer) window.binRenderer.reset();
                window.location.reload();
            };
        }
    }
}

document.addEventListener('DOMContentLoaded', () => {
    window.kidFlightApp = new KidFlightApp();
});

/* ==========================================================================
   CÙNG BÉ BIN ĐI MÁY BAY - 2D STORYBOOK INTERACTIVE BOOK (13 HOẠT ĐỘNG ĐỘC LẬP)
   - 8 Chặng lớn (Top Nav) & Tiến trình phụ (Sub-progress) cho từng chặng
   - Cấu trúc chuẩn: Màn Giới Thiệu (Intro) -> Màn Thực Hiện (Gameplay) -> Phản Hồi
   - 1 Kỹ năng = 1 Hoạt động riêng biệt
   - Tối ưu chạm lớn (>=70px), không SpeechSynthesis, giữ Web Audio SFX
   - Responsive hoàn hảo 1366x768 & 1920x1080 không scroll dọc gameplay
   ========================================================================== */

:root {
    --color-sky-blue: #73C7E8;
    --color-warm-orange: #F5A45D;
    --color-cream-yellow: #F8D978;
    --color-soft-green: #82C99A;
    --color-coral-pink: #EFA49A;
    --color-suitcase-red: #E75B52;
    --outline-brown: #514B48;
    --text-dark: #37474F;
    --shadow-soft: 0 6px 14px rgba(81, 75, 72, 0.14);
    --shadow-chunky: 0 6px 0 rgba(81, 75, 72, 0.18), 0 10px 20px rgba(0, 0, 0, 0.1);
    --radius-round: 9999px;
    --radius-story: 28px;

    /* Master Family Reference Sprite Sheet */
    --char-sprite: url('file:///C:/Users/USER/.gemini/antigravity/brain/6f49409f-fe23-4490-984d-4f0e771339c6/.user_uploaded/media_1787727192577.png');
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    -webkit-tap-highlight-color: transparent;
    user-select: none;
    -webkit-user-select: none;
}

body, html {
    width: 100%;
    height: 100%;
    overflow: hidden;
    font-family: "Nunito", "Arial Rounded MT Bold", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: #E1F5FE;
    color: var(--text-dark);
    touch-action: manipulation;
}

#app-root {
    width: 100vw;
    height: 100vh;
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
}

#effects-canvas {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1000;
}

/* ==========================================================================
   TẦNG 1: THANH TIẾN TRÌNH (8 CHẶNG LỚN & CỔNG BA MẸ)
   ========================================================================== */
.top-nav {
    height: 52px;
    padding: 4px 16px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    z-index: 50;
}

.stage-indicators {
    display: flex;
    gap: 8px;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(10px);
    padding: 4px 12px;
    border-radius: var(--radius-round);
    box-shadow: var(--shadow-soft);
    border: 2px solid #FFF;
}

.stage-dot {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #ECEFF1;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
    cursor: pointer;
    transition: all 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
    box-shadow: inset 0 -3px 0 #CFD8DC;
    border: none;
}

.stage-dot.active {
    background: linear-gradient(180deg, #F8D978 0%, #F5A45D 100%);
    transform: scale(1.18);
    box-shadow: 0 4px 12px rgba(245, 164, 93, 0.45), inset 0 -3px 0 #E67E22;
}

.stage-dot.completed {
    background: linear-gradient(180deg, #A5D6A7 0%, #82C99A 100%);
    box-shadow: inset 0 -3px 0 #66BB6A;
}

.stage-dot.locked {
    opacity: 0.35;
    cursor: not-allowed;
    filter: grayscale(0.8);
}

/* NÚT BẤM STORYBOOK BO TRÒN */
.tycoon-btn {
    min-width: 60px;
    min-height: 44px;
    padding: 6px 18px;
    border: none;
    border-radius: var(--radius-round);
    background: #FFFFFF;
    color: var(--text-dark);
    font-weight: 900;
    font-size: 15px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    cursor: pointer;
    box-shadow: 0 5px 0 #CFD8DC, 0 8px 14px rgba(0, 0, 0, 0.1);
    transition: all 0.12s ease;
    touch-action: manipulation;
}

.tycoon-btn:active:not(:disabled) {
    transform: translateY(3px);
    box-shadow: 0 2px 0 #CFD8DC;
}

.tycoon-btn:disabled {
    cursor: not-allowed;
    opacity: 0.6;
}

.tycoon-btn-green {
    background: linear-gradient(180deg, #82C99A 0%, #66BB6A 100%);
    color: #1B5E20;
    box-shadow: 0 5px 0 #43A047, 0 8px 18px rgba(67, 160, 71, 0.3);
}

.tycoon-btn-primary {
    background: linear-gradient(180deg, #F8D978 0%, #F5A45D 100%);
    color: #5D4037;
    box-shadow: 0 5px 0 #E67E22, 0 8px 18px rgba(230, 126, 34, 0.3);
}

/* Cổng Ba Mẹ: Vòng giữ 3 giây */
.parent-gate-btn {
    position: relative;
    overflow: hidden;
}

.parent-hold-ring {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    transform: rotate(-90deg);
}

.parent-hold-ring circle {
    fill: none;
    stroke: #FF7043;
    stroke-width: 5;
    stroke-dasharray: 175;
    stroke-dashoffset: 175;
    transition: stroke-dashoffset 0.1s linear;
}

/* ==========================================================================
   TẦNG 2: TIẾN TRÌNH PHỤ (SUB-PROGRESS) & BIỂN BÁO LỜI THOẠI BA MẸ
   ========================================================================== */
.parent-prompt-container {
    width: 100%;
    max-width: 900px;
    margin: 0 auto 4px auto;
    padding: 0 16px;
    z-index: 40;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.sub-progress-bar {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    background: rgba(255, 255, 255, 0.85);
    padding: 2px 14px;
    border-radius: var(--radius-round);
    font-size: 13px;
    font-weight: 800;
    color: #455A64;
    border: 1px solid rgba(255, 255, 255, 0.9);
}

.sub-step-item {
    display: flex;
    align-items: center;
    gap: 4px;
    opacity: 0.5;
}

.sub-step-item.active {
    opacity: 1;
    color: #E65100;
    font-weight: 900;
}

.sub-step-item.completed {
    opacity: 0.9;
    color: #2E7D32;
}

.parent-prompt-signboard {
    background: rgba(255, 255, 255, 0.96);
    border-radius: 24px;
    padding: 6px 18px;
    border: 3px solid #FFE082;
    box-shadow: 0 4px 0 #FFCA28, var(--shadow-soft);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    text-align: center;
}

.prompt-avatar-sprite {
    width: 46px;
    height: 46px;
    border-radius: 50%;
    border: 3px solid #F5A45D;
    box-shadow: 0 3px 8px rgba(0,0,0,0.12);
    background-image: var(--char-sprite);
    background-repeat: no-repeat;
    flex-shrink: 0;
}

.prompt-avatar-sprite.speaker-mom {
    background-size: 500% auto;
    background-position: 29.5% 18%;
    border-color: #EFA49A;
}

.prompt-avatar-sprite.speaker-dad {
    background-size: 500% auto;
    background-position: 51.5% 18%;
    border-color: #82C99A;
}

.prompt-avatar-sprite.speaker-bin {
    background-size: 500% auto;
    background-position: 8.5% 18%;
    border-color: #F5A45D;
}

.prompt-avatar-sprite.speaker-attendant {
    background-size: 500% auto;
    background-position: 88.5% 18%;
    border-color: #00897B;
}

.prompt-speech-text {
    font-size: 18px;
    font-weight: 900;
    color: var(--text-dark);
    line-height: 1.3;
}

/* ==========================================================================
   TẦNG 3: VIEWPORT 13 HOẠT ĐỘNG (MÀN GIỚI THIỆU & MÀN THỰC HIỆN)
   ========================================================================== */
.screens-viewport {
    flex: 1;
    position: relative;
    width: 100%;
    height: calc(100vh - 120px);
    overflow: hidden;
}

.activity-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    visibility: hidden;
    transform: scale(0.98);
    transition: opacity 0.3s ease, transform 0.3s cubic-bezier(0.34, 1.25, 0.64, 1), visibility 0.3s;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 4px 16px 12px 16px;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
}

.activity-container.active {
    opacity: 1;
    visibility: visible;
    transform: scale(1);
}

/* MÀN GIỚI THIỆU HOẠT ĐỘNG (INTRO VIEW) */
.activity-intro-view {
    width: 100%;
    max-width: 820px;
    height: 88%;
    background: rgba(255, 255, 255, 0.96);
    backdrop-filter: blur(10px);
    border-radius: var(--radius-story);
    border: 4px solid #FFE082;
    box-shadow: 0 10px 0 #FFCA28, var(--shadow-chunky);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    padding: 14px 20px;
    text-align: center;
    margin: auto 0;
    z-index: 10;
}

.intro-header-badge {
    background: #E1F5FE;
    color: #0288D1;
    font-size: 13px;
    font-weight: 900;
    padding: 4px 14px;
    border-radius: var(--radius-round);
    border: 2px solid #B3E5FC;
}

.intro-activity-title {
    font-size: 22px;
    font-weight: 900;
    color: #E65100;
    margin: 2px 0;
}

.intro-art-frame {
    width: 100%;
    max-width: 620px;
    height: 250px;
    border-radius: 20px;
    overflow: hidden;
    box-shadow: 0 6px 16px rgba(0,0,0,0.12);
    border: 3px solid #FFF;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #FFF;
}

.intro-art-frame img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.intro-prompt-quote {
    font-size: 17px;
    font-weight: 800;
    color: #37474F;
    line-height: 1.3;
    padding: 0 10px;
}

/* MÀN THỰC HIỆN HOẠT ĐỘNG (GAMEPLAY VIEW) */
.activity-gameplay-view {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    position: relative;
}

/* OVERLAY PHẢN HỒI HOÀN THÀNH */
.activity-feedback-overlay {
    position: absolute;
    bottom: 16px;
    background: rgba(255, 255, 255, 0.98);
    border-radius: 30px;
    padding: 10px 24px;
    border: 4px solid #82C99A;
    box-shadow: 0 8px 0 #43A047, var(--shadow-chunky);
    display: flex;
    align-items: center;
    gap: 16px;
    z-index: 60;
    animation: popBounce 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.activity-feedback-overlay.hidden {
    display: none !important;
}

.feedback-text {
    font-size: 18px;
    font-weight: 900;
    color: #1B5E20;
}

/* ==========================================================================
   CHARACTER RENDERER
   ========================================================================== */
.bin-character-frame {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
}

.bin-layered-stack {
    position: relative;
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
}

.bin-character-frame img,
.bin-layer {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    object-fit: contain;
    pointer-events: none;
    background: transparent;
    opacity: 1;
    transition: opacity 0.2s ease, transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.pop-in-soft {
    animation: popInSoft 0.25s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

@keyframes popInSoft {
    0% { transform: scale(0.94); opacity: 0.7; }
    100% { transform: scale(1); opacity: 1; }
}

/* ==========================================================================
   ACTIVITY 1: WARDROBE
   ========================================================================== */
.wardrobe-arena {
    width: 100%;
    max-width: 980px;
    display: grid;
    grid-template-columns: 1.2fr 1fr;
    gap: 24px;
    align-items: center;
    margin: auto 0;
}

.wardrobe-cabinet-art {
    background: rgba(255, 255, 255, 0.9);
    backdrop-filter: blur(8px);
    border: 4px solid #FFE082;
    border-radius: var(--radius-story);
    padding: 12px;
    box-shadow: var(--shadow-chunky);
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
}

.clothes-tile-art {
    min-height: 90px;
    background: #FFFFFF;
    border-radius: 20px;
    border: 3px solid #CFD8DC;
    box-shadow: 0 4px 0 #B0BEC5, 0 6px 12px rgba(0,0,0,0.06);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 6px;
    cursor: grab;
    touch-action: none;
    transition: transform 0.18s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.clothes-tile-art:hover { transform: translateY(-3px) scale(1.04); }
.clothes-tile-art:active { cursor: grabbing; transform: scale(1.15); z-index: 100; }
.clothes-tile-art.shake-wobble {
    animation: springShake 0.45s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
    border-color: #E75B52 !important;
}

.item-img-art {
    width: 62px;
    height: 62px;
    object-fit: contain;
    pointer-events: none;
}

.item-label-tag {
    font-size: 13px;
    font-weight: 800;
    color: var(--text-dark);
    margin-top: 3px;
    text-align: center;
}

.bin-character-stage {
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
}

.bin-stage-pedestal {
    width: 260px;
    height: 380px;
    background: none;
    border: none;
    box-shadow: none;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
}

.bin-mount-lvl1 {
    width: 250px;
    height: 370px;
}

/* ==========================================================================
   ACTIVITY 4: SOI HÀNH LÝ QUA MÁY QUÉT (ĐỘC LẬP)
   ========================================================================== */
.xray-focused-arena {
    width: 100%;
    max-width: 820px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
    margin: auto 0;
}

.xray-scanner-chunky {
    width: 100%;
    max-width: 580px;
    background: rgba(255, 255, 255, 0.95);
    border-radius: 36px;
    border: 4px solid #00E676;
    box-shadow: 0 8px 0 #00BFA5, var(--shadow-chunky);
    padding: 18px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
}

.xray-screen-large {
    width: 100%;
    height: 140px;
    background: #00251A;
    border-radius: 24px;
    border: 4px solid #00E676;
    box-shadow: inset 0 0 20px rgba(0, 230, 118, 0.5);
    display: flex;
    align-items: center;
    justify-content: space-around;
    padding: 10px;
}

.xray-box-touch {
    width: 80px;
    height: 80px;
    background: #00E676;
    border-radius: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 38px;
    cursor: pointer;
    box-shadow: 0 0 14px #00E676;
    transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.xray-box-touch:hover { transform: scale(1.12); }
.xray-box-touch.revealed { animation: popBounce 0.35s cubic-bezier(0.34, 1.56, 0.64, 1); }

/* ==========================================================================
   ACTIVITY 7: CÀI DÂY AN TOÀN (ĐỘC LẬP)
   ========================================================================== */
.seatbelt-focused-arena {
    width: 100%;
    max-width: 860px;
    display: grid;
    grid-template-columns: 1.1fr 1fr;
    gap: 24px;
    align-items: center;
    margin: auto 0;
}

.seat-plush-box {
    border-radius: 36px;
    padding: 12px;
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
}

.bin-mount-lvl5 {
    width: 220px;
    height: 270px;
}

.safety-sign-led {
    background: #E75B52;
    color: white;
    font-weight: 900;
    font-size: 13px;
    padding: 3px 14px;
    border-radius: var(--radius-round);
    margin-bottom: 6px;
    transition: background 0.3s;
}

.safety-sign-led.green-safe {
    background: #43A047;
    color: #FFFFFF;
    box-shadow: 0 0 16px #00E676;
}

.seatbelt-puzzle-box {
    background: rgba(255, 255, 255, 0.95);
    border-radius: 28px;
    padding: 20px;
    box-shadow: var(--shadow-soft);
    border: 3px solid #FFE082;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
}

.seatbelt-straps-row {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    height: 64px;
    position: relative;
}

.strap-left, .strap-right {
    height: 44px;
    display: flex;
    align-items: center;
    cursor: grab;
    touch-action: none;
    transition: transform 0.2s;
}

.strap-left {
    background: #37474F;
    width: 85px;
    border-radius: 8px 0 0 8px;
    position: relative;
}

.buckle-insert {
    position: absolute;
    right: -16px;
    width: 20px;
    height: 28px;
    background: #B0BEC5;
    border: 3px solid #78909C;
    border-radius: 4px;
}

.strap-right {
    background: #37474F;
    width: 85px;
    border-radius: 0 8px 8px 0;
    position: relative;
}

.buckle-receiver {
    position: absolute;
    left: -16px;
    width: 26px;
    height: 38px;
    background: #90A4AE;
    border: 3px solid #546E7A;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.seatbelt-buckled .strap-left { transform: translateX(16px) !important; }
.seatbelt-buckled .buckle-receiver { background: #00E676; border-color: #00BFA5; box-shadow: 0 0 16px #00E676; }

/* ==========================================================================
   ACTIVITY 12: CHỜ DỪNG RỒI MỞ DÂY (ĐỘC LẬP)
   ========================================================================== */
.unbuckle-focused-arena {
    width: 100%;
    max-width: 860px;
    display: grid;
    grid-template-columns: 1.1fr 1fr;
    gap: 24px;
    align-items: center;
    margin: auto 0;
}

.unbuckle-status-card {
    background: rgba(255, 255, 255, 0.95);
    border-radius: 28px;
    padding: 20px;
    border: 3px solid #B3E5FC;
    box-shadow: var(--shadow-soft);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
}

/* ==========================================================================
   CÁC HOẠT ĐỘNG KHÁC (2, 3, 5, 6, 8, 9, 10, 11, 13)
   ========================================================================== */
.suitcase-arena {
    width: 100%;
    max-width: 880px;
    display: flex;
    gap: 20px;
    align-items: center;
    justify-content: center;
    margin: auto 0;
}

.clothes-tile {
    width: 110px;
    height: 90px;
    background: #FFFFFF;
    border-radius: 20px;
    border: 3px solid #CFD8DC;
    box-shadow: 0 4px 0 #B0BEC5, 0 6px 12px rgba(0,0,0,0.06);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: grab;
    touch-action: none;
    transition: transform 0.18s cubic-bezier(0.34, 1.56, 0.64, 1);
    padding: 6px;
}

.clothes-tile:hover { transform: translateY(-3px) scale(1.04); }
.clothes-tile.shake-wobble { animation: springShake 0.45s cubic-bezier(0.36, 0.07, 0.19, 0.97) both; }

.suitcase-box-red {
    width: 280px;
    height: 290px;
    border-radius: 36px;
    border: 5px solid #8E0000;
    box-shadow: 0 10px 0 #5f0000, var(--shadow-chunky);
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 12px;
    position: relative;
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.suitcase-inner-grid {
    width: 100%;
    flex: 1;
    border-radius: 24px;
    border: 3px dashed #E75B52;
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-template-rows: repeat(2, 1fr);
    gap: 8px;
    padding: 8px;
    align-items: center;
    justify-items: center;
}

.boarding-pass-chunky {
    width: 220px;
    height: 110px;
    background: #FFF9C4;
    border-radius: 20px;
    border: 3px dashed #FFB300;
    box-shadow: 0 6px 14px rgba(0,0,0,0.1);
    padding: 12px;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    transition: transform 0.2s;
    position: relative;
}

.stamp-badge {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) rotate(-15deg) scale(0);
    border: 3px solid #43A047;
    color: #2E7D32;
    font-weight: 900;
    font-size: 19px;
    padding: 6px 14px;
    border-radius: 10px;
    opacity: 0;
    background: #E8F5E9;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.stamp-badge.stamped {
    opacity: 1;
    transform: translate(-50%, -50%) rotate(-15deg) scale(1.1);
    animation: stampSlam 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.gate-detector-chunky {
    width: 160px;
    height: 220px;
    border: 14px solid #78909C;
    border-bottom: none;
    border-radius: 24px 24px 0 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-end;
    cursor: pointer;
    background: rgba(236, 239, 241, 0.6);
    position: relative;
}

.gate-lamps-row {
    position: absolute;
    top: -22px;
    display: flex;
    gap: 16px;
}

.gate-lamp-led {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: #CFD8DC;
    border: 2px solid #546E7A;
}

.gate-lamp-led.green-flash {
    background: #00E676;
    box-shadow: 0 0 16px #00E676;
    animation: lamp-blink 0.25s alternate 6;
}

.gates-array-row {
    display: flex;
    justify-content: space-around;
    gap: 14px;
}

.gate-pillar {
    width: 130px;
    height: 130px;
    background: #263238;
    color: #F8D978;
    border: 4px solid #455A64;
    border-radius: 24px;
    box-shadow: 0 6px 0 #102027;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-family: monospace;
    font-weight: 900;
    transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.gate-pillar.matched {
    background: linear-gradient(180deg, #2E7D32 0%, #1B5E20 100%);
    border-color: #00E676;
    color: #FFFFFF;
    box-shadow: 0 6px 0 #004D40, 0 0 20px #00E676;
    animation: popBounce 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.cloud-window-frame {
    height: 290px;
    background: linear-gradient(180deg, #73C7E8 0%, #B3E5FC 60%, #E1F5FE 100%);
    border-radius: 40px;
    border: 12px solid #ECEFF1;
    box-shadow: inset 0 0 20px rgba(0,0,0,0.15), 0 10px 0 #CFD8DC, var(--shadow-soft);
    display: flex;
    align-items: center;
    justify-content: space-around;
    padding: 8px;
}

.morph-cloud-tile {
    background: rgba(255, 255, 255, 0.96);
    border-radius: 36px;
    padding: 14px 22px;
    box-shadow: 0 6px 14px rgba(0,0,0,0.1);
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: pointer;
    border: 3px solid transparent;
    transition: all 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.morph-cloud-tile.morphed {
    background: #FFF9C4;
    border-color: #F8D978;
    box-shadow: 0 0 20px #F8D978;
    animation: gentle-bounce 0.6s infinite alternate;
}

.volume-emotion-options {
    display: flex;
    gap: 12px;
}

.volume-emotion-btn {
    width: 86px;
    height: 80px;
    border-radius: 20px;
    background: #FFF;
    border: 3px solid #CFD8DC;
    box-shadow: 0 5px 0 #B0BEC5;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.volume-emotion-btn span { font-size: 28px; line-height: 1; }
.volume-emotion-btn small { font-size: 12px; font-weight: 900; color: var(--text-dark); margin-top: 3px; }
.volume-emotion-btn.selected {
    transform: scale(1.12);
    border-color: #43A047;
    background: #E8F5E9;
    box-shadow: 0 5px 0 #2E7D32, 0 0 14px #00E676;
}

.carousel-track-chunky {
    width: 90%;
    height: 150px;
    border: 14px solid #455A64;
    border-radius: 75px;
    background: #ECEFF1;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-around;
    box-shadow: inset 0 0 16px rgba(0,0,0,0.2);
    overflow: hidden;
}

.carousel-suitcases-track {
    display: flex;
    gap: 28px;
    position: absolute;
    animation: carousel-orbit 14s linear infinite;
}

.carousel-suitcases-track.paused { animation-play-state: paused; }

.carousel-bag-tile {
    width: 76px;
    height: 86px;
    border-radius: 18px;
    border: 3px solid rgba(0,0,0,0.2);
    box-shadow: 0 4px 10px rgba(0,0,0,0.15);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 34px;
    cursor: pointer;
    transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.golden-medal-modal {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) scale(0.8);
    opacity: 0;
    visibility: hidden;
    width: 90%;
    max-width: 560px;
    background: linear-gradient(135deg, #FFFDE7 0%, #FFF9C4 100%);
    border-radius: 36px;
    border: 6px solid #F8D978;
    box-shadow: 0 16px 50px rgba(0,0,0,0.3);
    padding: 22px;
    text-align: center;
    z-index: 200;
    transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.golden-medal-modal.show {
    opacity: 1;
    visibility: visible;
    transform: translate(-50%, -50%) scale(1);
    animation: popBounce 0.45s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ==========================================================================
   CỔNG BA MẸ (PARENT CONTROL HUB)
   ========================================================================== */
.parent-modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(6px);
    z-index: 999;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
}

.parent-modal-overlay.open { opacity: 1; visibility: visible; }

.parent-control-card {
    width: 90%;
    max-width: 540px;
    max-height: 88vh;
    overflow-y: auto;
    background: #FFFFFF;
    border-radius: 32px;
    padding: 22px;
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.25);
    border: 4px solid #F5A45D;
}

.parent-tip-box {
    background: #FFF3E0;
    border-left: 4px solid #F5A45D;
    padding: 8px 12px;
    border-radius: 10px;
    margin-bottom: 8px;
    font-size: 13px;
    line-height: 1.4;
    color: #4E342E;
}

.level-jump-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 8px;
    margin: 8px 0;
}

.jump-btn {
    padding: 8px;
    background: #ECEFF1;
    border: 2px solid #CFD8DC;
    border-radius: 10px;
    font-weight: 800;
    font-size: 13px;
    cursor: pointer;
    transition: transform 0.15s;
}

/* ==========================================================================
   KEYFRAME ANIMATIONS
   ========================================================================== */
@keyframes gentle-bounce { 0% { transform: translateY(0); } 100% { transform: translateY(-6px); } }
@keyframes springShake {
    10%, 90% { transform: translate3d(-3px, 0, 0) rotate(-3deg); }
    20%, 80% { transform: translate3d(4px, 0, 0) rotate(3deg); }
    30%, 50%, 70% { transform: translate3d(-5px, 0, 0) rotate(-2deg); }
    40%, 60% { transform: translate3d(5px, 0, 0) rotate(2deg); }
}
@keyframes stampSlam {
    0% { transform: translate(-50%, -50%) scale(2.4) rotate(-35deg); opacity: 0; }
    50% { transform: translate(-50%, -50%) scale(0.95) rotate(-10deg); opacity: 1; }
    100% { transform: translate(-50%, -50%) scale(1.1) rotate(-15deg); opacity: 1; }
}
@keyframes popBounce { 0% { transform: scale(0.8); } 60% { transform: scale(1.18); } 100% { transform: scale(1); } }
@keyframes lamp-blink { 0% { opacity: 0.3; } 100% { opacity: 1; } }
@keyframes carousel-orbit { 0% { transform: translateX(0); } 100% { transform: translateX(-380px); } }

.pop-in { animation: popIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }
@keyframes popIn { 0% { transform: scale(0.7); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
.hidden { display: none !important; }

/* ==========================================================================
   RESPONSIVE (1366x768 & 1920x1080)
   ========================================================================== */
@media (max-width: 900px) {
    .wardrobe-arena, .seatbelt-focused-arena, .unbuckle-focused-arena, .suitcase-arena {
        grid-template-columns: 1fr;
        flex-direction: column;
        gap: 10px;
    }
    .intro-art-frame { height: 180px; }
    .activity-intro-view { padding: 10px; }
    .intro-activity-title { font-size: 18px; }
}

/**
 * app.js - Main Controller for "Cùng Bé Bin Đi Máy Bay" (13 Hoạt Động Độc Lập)
 * Kiến trúc mới: 8 Chặng Lớn -> 13 Hoạt Động Kỹ Năng Riêng Biệt
 * Mỗi Hoạt Động = Màn Giới Thiệu (Intro) -> Màn Thực Hiện (Gameplay) -> Phản Hồi (Feedback)
 */

class KidFlightApp {
    constructor() {
        this.currentActivity = 1;
        this.totalActivities = 13;
        this.maxUnlockedActivity = 1;

        // Cấu hình 13 Hoạt Động
        this.activityConfig = {
            1: { stage: 1, title: 'Chọn Trang Phục Thoải Mái', speaker: 'Mẹ', introText: '“Bin sắp đi máy bay rồi. Con chọn bộ đồ nào giúp Bin dễ vận động nhé!”', subLabel: 'Hoạt động 1: Chọn trang phục' },
            2: { stage: 2, title: 'Xếp Đồ Vào Vali', speaker: 'Bố', introText: '“Bin mang gì đi máy bay nhỉ? Con xếp vali giúp Bin nhé!”', subLabel: 'Hoạt động 2: Xếp đồ vào vali' },
            3: { stage: 3, title: 'Kiểm Tra Vé & Thẻ Bay', speaker: 'Mẹ', introText: '“Đến quầy kiểm tra rồi. Con giúp Bin đưa vé nhé!”', subLabel: 'Bước 1/3: Kiểm tra vé' },
            4: { stage: 3, title: 'Soi Hành Lý Qua Máy Quét', speaker: 'Bố', introText: '“Bây giờ vali của Bin sẽ đi qua máy soi. Con xem bên trong có gì nhé!”', subLabel: 'Bước 2/3: Soi hành lý' },
            5: { stage: 3, title: 'Đi Qua Cổng An Ninh', speaker: 'Mẹ', introText: '“Đến cổng an ninh rồi. Con giúp Bin đi qua nhé!”', subLabel: 'Bước 3/3: Đi qua cổng an ninh' },
            6: { stage: 4, title: 'Tìm Đúng Cổng 03', speaker: 'Bố', introText: '“Vé của Bin ghi số 03. Con tìm cổng số 03 nhé!”', subLabel: 'Hoạt động 6: Tìm cổng lên máy bay' },
            7: { stage: 5, title: 'Cài Dây An Toàn', speaker: 'Mẹ', introText: '“Bin ngồi vào ghế rồi. Con giúp Bin cài dây an toàn nhé!”', subLabel: 'Bước 1/2: Cài dây an toàn' },
            8: { stage: 5, title: 'Giúp Tai Dễ Chịu Khi Cất Cánh', speaker: 'Mẹ', introText: '“Tai Bin hơi khó chịu. Bin uống một ngụm nước nhé.”', subLabel: 'Bước 2/2: Giúp tai dễ chịu' },
            9: { stage: 6, title: 'Ngắm Mây Và Tưởng Tượng', speaker: 'Bin', introText: '“Bin thấy đám mây giống hình gì nhỉ? Con nhìn cùng Bin nhé!”', subLabel: 'Hoạt động 9: Ngắm mây' },
            10: { stage: 7, title: 'Nói Nhỏ Vừa Đủ Nghe', speaker: 'Mẹ', introText: '“Trên máy bay mình nói nhỏ vừa đủ nghe nhé.”', subLabel: 'Bước 1/2: Nói nhỏ vừa đủ nghe' },
            11: { stage: 7, title: 'Ngồi Gọn — Không Đạp Ghế Trước', speaker: 'Bố', introText: '“Bin thu chân gọn lại để không chạm ghế phía trước nhé!”', subLabel: 'Bước 2/2: Ngồi gọn chân' },
            12: { stage: 8, title: 'Chờ Máy Bay Dừng Hẳn Rồi Mới Mở Dây', speaker: 'Bố', introText: '“Máy bay đang chạy vào chỗ đỗ. Bin vẫn ngồi yên và giữ dây an toàn nhé!”', subLabel: 'Bước 1/2: Chờ máy bay dừng' },
            13: { stage: 8, title: 'Tìm Đúng Vali Của Bin', speaker: 'Bố', introText: '“Con tìm chiếc vali đỏ có hình gấu của Bin nhé!”', subLabel: 'Bước 2/2: Nhận hành lý' }
        };

        // Tránh duplicate event listeners
        this.actInitialized = {};

        // State gameplay riêng cho các hoạt động
        this.dressed = { shirt: false, pants: false, shoes: false };
        this.packedCount = 0;
        this.xrayCount = 0;
        this.cloudsCount = 0;
        this.act12PlaneStopped = false;

        this.parentHoldStart = 0;
        this.parentHoldReqId = null;

        this.init();
    }

    init() {
        this.bindGlobalEvents();
        if (window.binRenderer) {
            window.binRenderer.updateAll();
        }
        this.showActivity(1, true);
    }

    showParentPrompt(speaker, text) {
        const avatar = document.getElementById('parent-prompt-avatar');
        const textEl = document.getElementById('parent-prompt-text');

        if (avatar) {
            avatar.className = 'prompt-avatar-sprite';
            if (speaker === 'Mẹ') avatar.classList.add('speaker-mom');
            else if (speaker === 'Bố') avatar.classList.add('speaker-dad');
            else if (speaker === 'Bin') avatar.classList.add('speaker-bin');
            else if (speaker === 'Tiếp viên') avatar.classList.add('speaker-attendant');
            else avatar.classList.add('speaker-mom');
        }

        if (textEl) {
            textEl.textContent = text;
        }
    }

    unlockActivity(actNum) {
        if (actNum > this.maxUnlockedActivity && actNum <= this.totalActivities) {
            this.maxUnlockedActivity = actNum;
        }
    }

    showActivity(actNum, showIntro = true) {
        if (actNum < 1 || actNum > this.totalActivities) return;

        this.currentActivity = actNum;
        this.unlockActivity(actNum);
        const config = this.activityConfig[actNum];

        // 1. Cập nhật Top Nav 8 Chặng Lớn
        document.querySelectorAll('.stage-dot').forEach((dot) => {
            const stageNum = parseInt(dot.getAttribute('data-stage'), 10);
            dot.classList.remove('active', 'completed', 'locked');

            if (stageNum === config.stage) {
                dot.classList.add('active');
            } else if (stageNum < config.stage) {
                dot.classList.add('completed');
            } else {
                // Kiểm tra xem stage này đã được unlock chưa
                const isUnlocked = Object.keys(this.activityConfig).some(k => {
                    return this.activityConfig[k].stage === stageNum && parseInt(k, 10) <= this.maxUnlockedActivity;
                });
                if (isUnlocked) dot.classList.add('completed');
                else dot.classList.add('locked');
            }
        });

        // 2. Cập nhật Sub-progress bar
        const subText = document.getElementById('sub-progress-text');
        if (subText) {
            subText.textContent = `Chặng ${config.stage} — ${config.subLabel}`;
        }

        // 3. Kích hoạt Container tương ứng
        document.querySelectorAll('.activity-container').forEach((cont) => {
            const num = parseInt(cont.getAttribute('data-act'), 10);
            if (num === actNum) {
                cont.classList.add('active');
            } else {
                cont.classList.remove('active');
            }
        });

        const introView = document.getElementById(`intro-act-${actNum}`);
        const gameplayView = document.getElementById(`gameplay-act-${actNum}`);
        const feedbackOverlay = document.getElementById(`feedback-act-${actNum}`);

        if (feedbackOverlay) feedbackOverlay.classList.add('hidden');

        if (showIntro && introView && gameplayView) {
            introView.classList.remove('hidden');
            gameplayView.classList.add('hidden');
            this.showParentPrompt(config.speaker, config.introText);
        } else if (gameplayView) {
            if (introView) introView.classList.add('hidden');
            gameplayView.classList.remove('hidden');
            this.startGameplay(actNum);
        }

        this.updateCharacterForActivity(actNum);
    }

    startGameplay(actNum) {
        const config = this.activityConfig[actNum];
        this.showParentPrompt(config.speaker, config.introText);

        if (!this.actInitialized[actNum]) {
            this.actInitialized[actNum] = true;
            this.initActivityGameplay(actNum);
        }

        if (actNum === 12) {
            this.runActivity12Flow();
        }
    }

    updateCharacterForActivity(actNum) {
        if (!window.binRenderer) return;

        switch (actNum) {
            case 1:
                window.binRenderer.renderTo(document.getElementById('bin-character-mount-lvl1'), 'level1_outfit');
                break;
            case 2:
            case 3:
            case 4:
            case 6:
                window.binRenderer.setPose('standing');
                window.binRenderer.setSeatbelt('none');
                break;
            case 5:
                window.binRenderer.renderTo(document.getElementById('bin-character-mount-lvl3'), 'pointing');
                break;
            case 7:
                window.binRenderer.setPose('seated');
                window.binRenderer.setSeatbelt('open');
                window.binRenderer.renderTo(document.getElementById('bin-character-mount-lvl5'), 'seated', 'open');
                break;
            case 8:
                window.binRenderer.setPose('seated');
                window.binRenderer.setSeatbelt('fastened');
                window.binRenderer.renderTo(document.getElementById('bin-character-mount-act8'), 'seated', 'fastened');
                break;
            case 9:
                window.binRenderer.setPose('looking_window');
                window.binRenderer.renderTo(document.getElementById('bin-character-mount-lvl6'), 'looking_window');
                break;
            case 10:
                window.binRenderer.setPose('whispering');
                window.binRenderer.renderTo(document.getElementById('bin-character-mount-lvl7'), 'whispering');
                break;
            case 11:
                window.binRenderer.setPose('sitting_neat');
                window.binRenderer.renderTo(document.getElementById('bin-character-mount-act11'), 'sitting_neat');
                break;
            case 12:
                window.binRenderer.setPose('seated');
                window.binRenderer.setSeatbelt('fastened');
                window.binRenderer.renderTo(document.getElementById('bin-character-mount-act12'), 'seated', 'fastened');
                break;
            case 13:
                window.binRenderer.setPose('holding_badge');
                window.binRenderer.renderTo(document.getElementById('bin-character-mount-lvl8'), 'holding_badge');
                break;
        }
    }

    bindGlobalEvents() {
        // Nút BẮT ĐẦU HOẠT ĐỘNG từ màn Intro
        document.querySelectorAll('.btn-start-activity').forEach(btn => {
            btn.addEventListener('click', () => {
                const actNum = parseInt(btn.getAttribute('data-act'), 10);
                if (window.audioMgr) window.audioMgr.playPop();
                const introView = document.getElementById(`intro-act-${actNum}`);
                const gameplayView = document.getElementById(`gameplay-act-${actNum}`);
                if (introView) introView.classList.add('hidden');
                if (gameplayView) gameplayView.classList.remove('hidden');
                this.startGameplay(actNum);
            });
        });

        // Nút TIẾP TỤC từ Feedback Overlay
        document.querySelectorAll('.btn-next-activity').forEach(btn => {
            btn.addEventListener('click', () => {
                const nextAct = parseInt(btn.getAttribute('data-next'), 10);
                if (window.audioMgr) window.audioMgr.playPop();
                if (nextAct <= this.totalActivities) {
                    this.showActivity(nextAct, true);
                }
            });
        });

        // Cổng Ba Mẹ
        const parentBtn = document.getElementById('btn-parent-gate');
        const holdCircle = document.getElementById('parent-ring-circle');
        const modal = document.getElementById('parent-modal');
        const closeModalBtn = document.getElementById('btn-close-parent');

        if (parentBtn && holdCircle) {
            const startHold = (e) => {
                e.preventDefault();
                this.parentHoldStart = Date.now();
                const totalHold = 3000;

                const updateRing = () => {
                    const elapsed = Date.now() - this.parentHoldStart;
                    const progress = Math.min(1, elapsed / totalHold);
                    const offset = 175 - (175 * progress);
                    holdCircle.style.strokeDashoffset = offset;

                    if (progress >= 1) {
                        if (window.audioMgr) window.audioMgr.playTing();
                        modal.classList.add('open');
                        resetHold();
                    } else {
                        this.parentHoldReqId = requestAnimationFrame(updateRing);
                    }
                };

                this.parentHoldReqId = requestAnimationFrame(updateRing);
            };

            const resetHold = () => {
                if (this.parentHoldReqId) cancelAnimationFrame(this.parentHoldReqId);
                holdCircle.style.strokeDashoffset = 175;
            };

            parentBtn.addEventListener('pointerdown', startHold);
            parentBtn.addEventListener('pointerup', resetHold);
            parentBtn.addEventListener('pointerleave', resetHold);
            parentBtn.addEventListener('pointercancel', resetHold);
        }

        if (closeModalBtn && modal) {
            closeModalBtn.addEventListener('click', () => {
                if (window.audioMgr) window.audioMgr.playPop();
                modal.classList.remove('open');
            });
        }

        const volSlider = document.getElementById('setting-volume');
        if (volSlider) {
            volSlider.addEventListener('input', (e) => {
                if (window.audioMgr) window.audioMgr.volume = parseFloat(e.target.value);
            });
        }

        const motionToggle = document.getElementById('setting-reduced-motion');
        if (motionToggle) {
            motionToggle.addEventListener('change', (e) => {
                if (window.effectsMgr) window.effectsMgr.reducedMotion = e.target.checked;
            });
        }

        const resetBtn = document.getElementById('btn-reset-app');
        if (resetBtn) {
            resetBtn.addEventListener('click', () => {
                if (window.binRenderer) window.binRenderer.reset();
                window.location.reload();
            });
        }

        document.querySelectorAll('.jump-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const target = parseInt(btn.getAttribute('data-act'), 10);
                if (target) {
                    if (window.audioMgr) window.audioMgr.playPop();
                    modal.classList.remove('open');
                    this.unlockActivity(target);
                    this.showActivity(target, true);
                }
            });
        });
    }

    // ==========================================================================
    // INITIALIZE GAMEPLAY CHO TỪNG HOẠT ĐỘNG
    // ==========================================================================
    initActivityGameplay(actNum) {
        switch (actNum) {
            case 1: this.initAct1Wardrobe(); break;
            case 2: this.initAct2Suitcase(); break;
            case 3: this.initAct3Ticket(); break;
            case 4: this.initAct4Xray(); break;
            case 5: this.initAct5Gate(); break;
            case 6: this.initAct6Gate03(); break;
            case 7: this.initAct7Seatbelt(); break;
            case 8: this.initAct8Water(); break;
            case 9: this.initAct9Clouds(); break;
            case 10: this.initAct10Volume(); break;
            case 11: this.initAct11Feet(); break;
            case 12: this.initAct12Unbuckle(); break;
            case 13: this.initAct13Baggage(); break;
        }
    }

    // --- HOẠT ĐỘNG 1: CHỌN TRANG PHỤC (GOLDEN SAMPLE 1) ---
    initAct1Wardrobe() {
        const clothesTiles = document.querySelectorAll('#act-1 [data-clothing-item="true"]');
        const binTarget = document.getElementById('bin-dress-target');
        const feedback = document.getElementById('feedback-act-1');

        const applyClothingItem = (tile) => {
            const isFit = tile.getAttribute('data-fit') === 'soft';
            const type = tile.getAttribute('data-type');
            const binRect = binTarget.getBoundingClientRect();

            if (isFit && window.binRenderer) {
                if (type === 'shirt') {
                    this.dressed.shirt = true;
                    window.binRenderer.setShirt('yellow');
                } else if (type === 'pants') {
                    this.dressed.pants = true;
                    window.binRenderer.setPants('blue');
                } else if (type === 'shoes') {
                    this.dressed.shoes = true;
                    window.binRenderer.setShoes('velcro');
                }

                if (window.effectsMgr) {
                    window.effectsMgr.burstStarsAt(binRect.left + binRect.width / 2, binRect.top + binRect.height / 2);
                }
                if (window.audioMgr) window.audioMgr.playTing();
                this.showParentPrompt('Mẹ', '“Đúng rồi! Món này mềm và dễ vận động.”');

                if (this.dressed.shirt && this.dressed.pants && this.dressed.shoes) {
                    this.unlockActivity(2);
                    if (feedback) feedback.classList.remove('hidden');
                    this.showParentPrompt('Mẹ', '“Bin sẵn sàng rồi! Mình đi xếp vali nhé!”');
                }
            } else {
                tile.classList.add('shake-wobble');
                setTimeout(() => { tile.classList.remove('shake-wobble'); }, 500);
                if (window.audioMgr) window.audioMgr.playBoing();
                this.showParentPrompt('Bố', '“Món này hơi bất tiện. Con thử món khác nhé!”');
            }
        };

        clothesTiles.forEach(tile => {
            tile.addEventListener('click', () => applyClothingItem(tile));
        });
    }

    // --- HOẠT ĐỘNG 2: XẾP VALI ---
    initAct2Suitcase() {
        const items = document.querySelectorAll('#act-2 [data-luggage-item="true"]');
        const suitcaseInner = document.getElementById('suitcase-inner-lvl2');
        const feedback = document.getElementById('feedback-act-2');

        items.forEach(item => {
            item.addEventListener('click', () => {
                if (item.classList.contains('packed')) return;
                const cat = item.getAttribute('data-category');

                if (cat === 'PACK') {
                    item.classList.add('packed');
                    item.style.display = 'none';
                    this.packedCount++;

                    const img = item.querySelector('img');
                    if (img) {
                        const clone = document.createElement('img');
                        clone.src = img.src;
                        clone.style.width = '52px';
                        clone.style.height = '52px';
                        clone.style.objectFit = 'contain';
                        clone.className = 'pop-in';
                        suitcaseInner.appendChild(clone);
                    }

                    if (window.audioMgr) window.audioMgr.playTing();
                    this.showParentPrompt('Mẹ', '“Ừ! Món này mình xếp vào vali nhé.”');

                    if (this.packedCount >= 3) {
                        this.unlockActivity(3);
                        if (feedback) feedback.classList.remove('hidden');
                        this.showParentPrompt('Mẹ', '“Vali của Bin sẵn sàng rồi! Đến sân bay thôi!”');
                    }
                } else if (cat === 'ASK_PARENT') {
                    item.classList.add('shake-wobble');
                    setTimeout(() => item.classList.remove('shake-wobble'), 500);
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.showParentPrompt('Bố', '“Món này mình hỏi Ba Mẹ trước nhé!”');
                } else {
                    item.classList.add('shake-wobble');
                    setTimeout(() => item.classList.remove('shake-wobble'), 500);
                    if (window.audioMgr) window.audioMgr.playBoing();
                    this.showParentPrompt('Bố', '“Món này để Ba Mẹ giúp mình xử lý nhé.”');
                }
            });
        });
    }

    // --- HOẠT ĐỘNG 3: KIỂM TRA VÉ ---
    initAct3Ticket() {
        const passCard = document.getElementById('pass-card-lvl3');
        const stampBadge = document.getElementById('stamp-badge-lvl3');
        const feedback = document.getElementById('feedback-act-3');

        if (passCard) {
            passCard.onclick = () => {
                if (stampBadge.classList.contains('stamped')) return;
                stampBadge.classList.add('stamped');
                if (window.audioMgr) window.audioMgr.playStamp();
                if (window.effectsMgr) {
                    const r = passCard.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }
                this.showParentPrompt('Tiếp viên', '“Vé của Bin xong rồi! Giờ soi chiếu vali nhé.”');
                this.unlockActivity(4);
                if (feedback) feedback.classList.remove('hidden');
            };
        }
    }

    // --- HOẠT ĐỘNG 4: SOI HÀNH LÝ (GOLDEN SAMPLE 2) ---
    initAct4Xray() {
        const boxes = document.querySelectorAll('#act-4 .xray-box-touch');
        const feedback = document.getElementById('feedback-act-4');

        boxes.forEach(box => {
            box.onclick = () => {
                if (box.getAttribute('data-revealed') === 'true') return;
                box.setAttribute('data-revealed', 'true');
                box.textContent = box.getAttribute('data-item');
                box.style.background = '#FFF9C4';
                box.classList.add('revealed');
                this.xrayCount++;

                if (window.audioMgr) window.audioMgr.playTing();
                if (window.effectsMgr) {
                    const r = box.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }

                if (this.xrayCount >= 3) {
                    this.unlockActivity(5);
                    if (feedback) feedback.classList.remove('hidden');
                    this.showParentPrompt('Mẹ', '“Vali của Bin an toàn rồi! Qua cổng kiểm tra nhé!”');
                }
            };
        });
    }

    // --- HOẠT ĐỘNG 5: ĐI QUA CỔNG AN NINH ---
    initAct5Gate() {
        const gate = document.getElementById('gate-detector-lvl3');
        const lamps = document.querySelectorAll('#act-5 .gate-lamp-led');
        const binMount = document.getElementById('bin-character-mount-lvl3');
        const feedback = document.getElementById('feedback-act-5');

        if (gate) {
            gate.onclick = () => {
                lamps.forEach(l => l.classList.add('green-flash'));
                if (binMount) binMount.style.transform = 'translateY(-14px) scale(1.1)';
                if (window.audioMgr) window.audioMgr.playBeepBoop();
                if (window.effectsMgr) {
                    const r = gate.getBoundingClientRect();
                    window.effectsMgr.burstStarsAt(r.left + r.width / 2, r.top + r.height / 2);
                }
                this.showParentPrompt('Mẹ', '“Bíp boong! Bin qua cửa an toàn rồi!”');
                this.unlockActivity(6);
