    // --- HOẠT ĐỘNG 6: TÌM ĐÚNG CỔNG 03 ---
    initAct6Gate03() {
        const gates = document.querySelectorAll('#act-6 .gate-pillar');
        const feedback = document.getElementById('feedback-act-6');

        gates.forEach(g => {
            g.onclick = () => {
                const target = g.getAttribute('data-gate');
