    }

    // --- HOẠT ĐỘNG 9: NGẮM MÂY ---
    initAct9Clouds() {
        const cloudTiles = document.querySelectorAll('#act-9 .morph-cloud-tile');
        const feedback = document.getElementById('feedback-act-9');

        cloudTiles.forEach(tile => {
            tile.onclick = () => {
                if (tile.classList.contains('morphed')) return;
                tile.classList.add('morphed');
                this.cloudsCount++;

                const morphType = tile.getAttribute('data-morph');
                const icon = tile.querySelector('.cloud-icon');
                const label = tile.querySelector('.cloud-label');

                if (morphType === 'bunny') { icon.textContent = '🐰'; label.textContent = 'Chú thỏ'; }
                else if (morphType === 'car') { icon.textContent = '🚗'; label.textContent = 'Chiếc ô tô'; }
                else if (morphType === 'watermelon') { icon.textContent = '🍉'; label.textContent = 'Miếng dưa hấu'; }
                else if (morphType === 'bear') { icon.textContent = '🐻'; label.textContent = 'Chú gấu'; }

                if (window.audioMgr) window.audioMgr.playBling();
                this.showParentPrompt('Bin', '“Bin thấy những đám mây biến hình thật kỳ diệu!”');

                if (this.cloudsCount >= 4) {
                    this.unlockActivity(10);
                    if (feedback) feedback.classList.remove('hidden');
                }
            };
        });
    }

    // --- HOẠT ĐỘNG 10: NÓI NHỎ ---
    initAct10Volume() {
        const btns = document.querySelectorAll('#act-10 .volume-emotion-btn');
        const feedback = document.getElementById('feedback-act-10');

        btns.forEach(b => {
            b.onclick = () => {
                btns.forEach(btn => btn.classList.remove('selected'));
                b.classList.add('selected');
                const level = b.getAttribute('data-level');

                if (level === 'whisper') {
                    if (window.binRenderer) {
                        window.binRenderer.setPose('whispering');
                        window.binRenderer.renderTo(document.getElementById('bin-character-mount-lvl7'), 'whispering');
                    }
                    if (window.audioMgr) window.audioMgr.playTing();
                    this.showParentPrompt('Bin', '“Đúng rồi! Mình nói nhỏ vừa đủ nghe nhé.”');
                    this.unlockActivity(11);
                    if (feedback) feedback.classList.remove('hidden');
                } else if (level === 'loud') {
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.showParentPrompt('Mẹ', '“Ơ, hơi to rồi. Con thử nhỏ hơn nhé!”');
                } else {
                    if (window.audioMgr) window.audioMgr.playPop();
                    this.showParentPrompt('Mẹ', '“Nhỏ hơn một chút nữa nhé!”');
                }
            };
        });
    }

