                if (window.audioMgr) window.audioMgr.playTing();
                this.showParentPrompt('Bố', '“Giỏi lắm! Bin ngồi gọn rồi, không đạp ghế trước!”');
                this.unlockActivity(12);
                if (feedback) feedback.classList.remove('hidden');
            };
