    --color-suitcase-red: #E75B52;
    --outline-brown: #514B48;
    --text-dark: #37474F;
    --shadow-soft: 0 6px 14px rgba(81, 75, 72, 0.14);
    --shadow-chunky: 0 6px 0 rgba(81, 75, 72, 0.18), 0 10px 20px rgba(0, 0, 0, 0.1);
    --radius-round: 9999px;
    --radius-story: 28px;

    /* Master Family Reference Sprite Sheet */
    --char-sprite: url('file:///C:/Users/USER/.gemini/antigravity/brain/6f49409f-fe23-4490-984d-4f0e771339c6/.user_uploaded/media_1787727192577.png');
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    -webkit-tap-highlight-color: transparent;
    user-select: none;
    -webkit-user-select: none;
}

body, html {
    width: 100%;
    height: 100%;
    overflow: hidden;
    font-family: "Nunito", "Arial Rounded MT Bold", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: #E1F5FE;
    color: var(--text-dark);
    touch-action: manipulation;
}

#app-root {
    width: 100vw;
    height: 100vh;
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
}

#effects-canvas {
