    z-index: 1000;
}

/* ==========================================================================
   TẦNG 1: THANH TIẾN TRÌNH (8 CHẶNG LỚN & CỔNG BA MẸ)
   ========================================================================== */
.top-nav {
    height: 48px;
    padding: 4px 16px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    z-index: 50;
}

.stage-indicators {
    display: flex;
    gap: 8px;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(10px);
    padding: 4px 12px;
    border-radius: var(--radius-round);
    box-shadow: var(--shadow-soft);
    border: 2px solid #FFF;
}

.stage-dot {
    width: 34px;
    height: 34px;
    border-radius: 50%;
    background: #ECEFF1;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 15px;
    cursor: pointer;
    transition: all 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
    box-shadow: inset 0 -3px 0 #CFD8DC;
    border: none;
}

.stage-dot.active {
    background: linear-gradient(180deg, #F8D978 0%, #F5A45D 100%);
    transform: scale(1.18);
    box-shadow: 0 4px 12px rgba(245, 164, 93, 0.45), inset 0 -3px 0 #E67E22;
}

.stage-dot.completed {
    background: linear-gradient(180deg, #A5D6A7 0%, #82C99A 100%);
    box-shadow: inset 0 -3px 0 #66BB6A;
}

.stage-dot.locked {
    opacity: 0.35;
    cursor: not-allowed;
    filter: grayscale(0.8);
}

