   ACTIVITY 13: 5 VALI THẬT TRÊN BĂNG CHUYỀN HÀNH LÝ
   ========================================================================== */
.real-carousel-track {
    width: 100%;
    max-width: 860px;
    height: 200px;
    border: 14px solid #455A64;
    border-radius: 100px;
    background: #ECEFF1;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-around;
    box-shadow: inset 0 0 16px rgba(0,0,0,0.2);
