    margin: auto 0;
}

.real-suitcases-orbit {
    display: flex;
    gap: 32px;
    position: absolute;
    animation: carousel-orbit 14s linear infinite;
    align-items: center;
}

.real-suitcases-orbit.paused { animation-play-state: paused; }

.real-suitcase-card {
    width: 100px;
    height: 140px;
    background: transparent;
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.real-suitcase-card:hover { transform: scale(1.15) translateY(-6px); }
.real-suitcase-card img {
    width: 100%;
    height: 100%;
