/**
 * character-renderer.js - Character State Renderer for Bé Bin
 * Chuẩn Style BIN_SOFT_STORYBOOK_2D_V1
 * - Sử dụng đường dẫn tương đối (Relative URLs), 0 hard-code file:///
 * - Outfit State Machine cho Level 1 thay đổi trang phục thật 100%
 * - Hiển thị trực tiếp, không lỗi Canvas Tainting, 0 console error
 */

class CharacterRenderer {
    constructor() {
        this.characterState = {
            outfit: {
                shirt: null, // 'yellow' | 'blue' | null
                pants: null, // 'blue' | 'orange' | 'soft' | null
                shoes: null  // 'velcro' | null
            },
            pose: 'standing',
            expression: 'normal',
            seatbelt: 'none',
            holding: null
        };

        // Bảng ánh xạ relative asset paths
        this.assets = {
            // Level 1 Outfit States
            outfits: {
                base_neutral: 'assets/characters/bin/bin_base_neutral.jpg',
                yellow_shirt_only: 'assets/characters/bin/bin_yellow_shirt_only.jpg',
                yellow_shirt_blue_pants: 'assets/characters/bin/bin_yellow_shirt_blue_pants.jpg',
                yellow_shirt_blue_pants_shoes: 'assets/characters/bin/bin_yellow_shirt_blue_pants_shoes.jpg'
            },
            // Poses xuyên suốt chuyến bay
            poses: {
                standing: 'assets/characters/bin/bin_point_right.jpg',
                pointing: 'assets/characters/bin/bin_point_right.jpg',
                seated_open: 'assets/characters/bin/bin_seated_plane.jpg',
                seated_fastened: 'assets/characters/bin/bin_seatbelt_fastened.jpg',
                drinking_water: 'assets/characters/bin/bin_drink_water.jpg',
                looking_window: 'assets/characters/bin/bin_looking_window.jpg',
                whispering: 'assets/characters/bin/bin_whisper_sitting.jpg',
                sitting_neat: 'assets/characters/bin/bin_whisper_sitting.jpg',
                holding_badge: 'assets/characters/bin/bin_holding_badge.jpg'
            }
        };

        this.init();
    }

    init() {
        this.updateAll();
    }

    // --- Cập nhật từng thành phần trang phục ---
    setShirt(val) {
        this.characterState.outfit.shirt = val;
        console.log('[CharacterRenderer] Outfit updated:', this.characterState.outfit);
        this.updateAll();
    }

    setPants(val) {
        this.characterState.outfit.pants = val;
        console.log('[CharacterRenderer] Outfit updated:', this.characterState.outfit);
        this.updateAll();
    }

    setShoes(val) {
        this.characterState.outfit.shoes = val;
        console.log('[CharacterRenderer] Outfit updated:', this.characterState.outfit);
        this.updateAll();
    }

    setPose(poseName) {
        this.characterState.pose = poseName;
        this.updateAll();
    }

    setSeatbelt(status) {
        this.characterState.seatbelt = status;
        this.updateAll();
    }

    reset() {
        this.characterState = {
            outfit: { shirt: null, pants: null, shoes: null },
            pose: 'standing',
            expression: 'normal',
            seatbelt: 'none',
            holding: null
        };
        this.updateAll();
    }

    // --- State Machine ánh xạ sang Artwork thật của Level 1 ---
    getOutfitSpriteSrc() {
        const s = this.characterState.outfit.shirt;
        const p = this.characterState.outfit.pants;
        const sh = this.characterState.outfit.shoes;

        // Trạng thái 0: Mộc ban đầu (áo ba lỗ trắng + tất mộc)
        if (!s && !p && !sh) {
            return this.assets.outfits.base_neutral;
        }
        // Trạng thái 1: Đã chọn áo vàng
        if (s && !p && !sh) {
            return this.assets.outfits.yellow_shirt_only;
        }
        // Trạng thái 2: Đã chọn áo vàng + quần xanh
        if (s && p && !sh) {
            return this.assets.outfits.yellow_shirt_blue_pants;
        }
        // Trạng thái 3: Đầy đủ áo vàng + quần xanh + giày dán xé
        if (s && p && sh) {
            return this.assets.outfits.yellow_shirt_blue_pants_shoes;
        }

        // Chuyển tiếp linh hoạt nếu chọn quần/giày trước
        if (s && sh && !p) return this.assets.outfits.yellow_shirt_only;
        if (p && !s) return this.assets.outfits.base_neutral;

        return this.assets.outfits.yellow_shirt_blue_pants_shoes;
    }

    // --- Render trực tiếp vào DOM container ---
    renderTo(containerEl, customMode = null, customSeatbelt = null) {
        if (!containerEl) return;

        const effectivePose = customMode || this.characterState.pose;
        const effectiveSeatbelt = customSeatbelt !== null ? customSeatbelt : this.characterState.seatbelt;

        let src = '';

        if (effectivePose === 'level1_outfit') {
            src = this.getOutfitSpriteSrc();
        } else if (effectivePose === 'seated') {
            src = effectiveSeatbelt === 'fastened' ? this.assets.poses.seated_fastened : this.assets.poses.seated_open;
        } else {
            src = this.assets.poses[effectivePose] || this.assets.poses.standing;
        }

        containerEl.innerHTML = '';
        containerEl.classList.add('bin-character-frame');

        const img = document.createElement('img');
        img.className = 'bin-sprite-img pop-in-soft';
        img.src = src;
        img.alt = `Bé Bin ${effectivePose}`;
        img.style.width = '100%';
        img.style.height = '100%';
        img.style.objectFit = 'contain';
        img.style.display = 'block';

        containerEl.appendChild(img);
    }

    updateAll() {
        const lvl1Mount = document.getElementById('bin-character-mount-lvl1');
        if (lvl1Mount) this.renderTo(lvl1Mount, 'level1_outfit');

        const lvl3Mount = document.getElementById('bin-character-mount-lvl3');
        if (lvl3Mount) this.renderTo(lvl3Mount, 'pointing');

        const lvl8Mount = document.getElementById('bin-character-mount-lvl8');
        if (lvl8Mount) this.renderTo(lvl8Mount, 'holding_badge');
    }
}

window.binRenderer = new CharacterRenderer();

/* ==========================================================================
   CÙNG BÉ BIN ĐI MÁY BAY - 2D STORYBOOK INTERACTIVE BOOK (13 HOẠT ĐỘNG ĐỘC LẬP)
   - 100% Relative Asset URLs (KHÔNG file:///C:/ và KHÔNG .gemini/antigravity/brain)
   - P0.1: Cổng Ba Mẹ display: none mặc định, chỉ mở khi giữ 3 giây (fixed overlay)
   - P0.3: Level 1 Bé Bin đứng trực tiếp trong phòng ngủ, 0 khung pedestal, 0 card trắng
   - P0.4: Không scroll dọc, vừa vặn 100vh cho 1366x768 & 1920x1080
   ========================================================================== */

:root {
    --color-sky-blue: #73C7E8;
    --color-warm-orange: #F5A45D;
    --color-cream-yellow: #F8D978;
    --color-soft-green: #82C99A;
    --color-coral-pink: #EFA49A;
    --color-suitcase-red: #E75B52;
    --outline-brown: #514B48;
    --text-dark: #37474F;
    --shadow-soft: 0 4px 12px rgba(81, 75, 72, 0.12);
    --shadow-chunky: 0 5px 0 rgba(81, 75, 72, 0.16), 0 8px 18px rgba(0, 0, 0, 0.1);
    --radius-round: 9999px;
    --radius-story: 24px;

    /* Master Family Reference Sprite */
    --char-sprite: url('../assets/characters/family/family_reference.png');
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    -webkit-tap-highlight-color: transparent;
    user-select: none;
    -webkit-user-select: none;
}

body, html {
    width: 100%;
    height: 100%;
    overflow: hidden;
    font-family: "Nunito", "Arial Rounded MT Bold", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: #E1F5FE;
    color: var(--text-dark);
    touch-action: manipulation;
}

#app-root {
    width: 100vw;
    height: 100vh;
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
}

#effects-canvas {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1000;
}

/* ==========================================================================
   TẦNG 1: TOP BAR - 8 CHẶNG LỚN & CỔNG BA MẸ
   ========================================================================== */
.top-nav {
    height: 46px;
    padding: 4px 16px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    z-index: 50;
    flex-shrink: 0;
}

.stage-indicators {
    display: flex;
    gap: 8px;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(8px);
    padding: 3px 10px;
    border-radius: var(--radius-round);
    box-shadow: var(--shadow-soft);
    border: 2px solid #FFF;
}

.stage-dot {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: #ECEFF1;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    cursor: pointer;
    transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
    box-shadow: inset 0 -2px 0 #CFD8DC;
    border: none;
}

.stage-dot.active {
    background: linear-gradient(180deg, #F8D978 0%, #F5A45D 100%);
    transform: scale(1.15);
    box-shadow: 0 4px 10px rgba(245, 164, 93, 0.4), inset 0 -2px 0 #E67E22;
}

.stage-dot.completed {
    background: linear-gradient(180deg, #A5D6A7 0%, #82C99A 100%);
    box-shadow: inset 0 -2px 0 #66BB6A;
}

.stage-dot.locked {
    opacity: 0.35;
    cursor: not-allowed;
    filter: grayscale(0.8);
}

.tycoon-btn {
    min-width: 50px;
    min-height: 38px;
    padding: 4px 16px;
    border: none;
    border-radius: var(--radius-round);
    background: #FFFFFF;
    color: var(--text-dark);
    font-weight: 900;
    font-size: 14px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    cursor: pointer;
    box-shadow: 0 4px 0 #CFD8DC, 0 6px 12px rgba(0, 0, 0, 0.08);
    transition: all 0.12s ease;
    touch-action: manipulation;
}

.tycoon-btn:active:not(:disabled) {
    transform: translateY(2px);
    box-shadow: 0 2px 0 #CFD8DC;
}

.tycoon-btn:disabled {
    cursor: not-allowed;
    opacity: 0.6;
}

.tycoon-btn-green {
    background: linear-gradient(180deg, #82C99A 0%, #66BB6A 100%);
    color: #1B5E20;
    box-shadow: 0 4px 0 #43A047, 0 6px 14px rgba(67, 160, 71, 0.3);
}

.tycoon-btn-primary {
    background: linear-gradient(180deg, #F8D978 0%, #F5A45D 100%);
    color: #5D4037;
    box-shadow: 0 4px 0 #E67E22, 0 6px 14px rgba(230, 126, 34, 0.3);
}

.parent-gate-btn {
    position: relative;
    overflow: hidden;
}

.parent-hold-ring {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    transform: rotate(-90deg);
}

.parent-hold-ring circle {
    fill: none;
    stroke: #FF7043;
    stroke-width: 4;
    stroke-dasharray: 175;
    stroke-dashoffset: 175;
    transition: stroke-dashoffset 0.1s linear;
}

/* ==========================================================================
   TẦNG 2: TIẾN TRÌNH PHỤ & LỜI THOẠI BA MẸ
   ========================================================================== */
.parent-prompt-container {
    width: 100%;
    max-width: 900px;
    margin: 0 auto 2px auto;
