/* ==========================================================================
   TẦNG 3: VIEWPORT 13 HOẠT ĐỘNG
   ========================================================================== */
.screens-viewport {
    flex: 1;
    position: relative;
    width: 100%;
    height: calc(100vh - 100px);
    overflow: hidden;
}

.activity-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    visibility: hidden;
    transform: scale(0.98);
    transition: opacity 0.25s ease, transform 0.25s cubic-bezier(0.34, 1.25, 0.64, 1), visibility 0.25s;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 4px 16px 8px 16px;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    overflow: hidden;
}

.activity-container.active {
    opacity: 1;
    visibility: visible;
    transform: scale(1);
}

/* MÀN GIỚI THIỆU HOẠT ĐỘNG (INTRO VIEW) */
.activity-intro-view {
    width: 100%;
    max-width: 800px;
