/* ==========================================================================
   LEVEL 1: PHÒNG NGỦ BÉ BIN (P0.3 - BIN ĐỨNG TRỰC TIẾP TRONG SCENE)
   ========================================================================== */
.level1-room-scene {
    width: 100%;
    max-width: 980px;
    height: 92%;
    position: relative;
    border-radius: 24px;
    overflow: hidden;
    box-shadow: 0 8px 24px rgba(0,0,0,0.18), 0 0 0 4px #FFFFFF;
    background-image: url('../assets/backgrounds/bg_home.jpg');
    background-size: cover;
    background-position: center;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 28px;
    margin: auto 0;
}

/* Kệ tủ đồ bên trái/giữa phòng */
.room-wardrobe-grid {
    background: rgba(255, 255, 255, 0.88);
    backdrop-filter: blur(6px);
    border: 3px solid #FFE082;
    border-radius: 20px;
    padding: 8px;
    box-shadow: 0 6px 16px rgba(0,0,0,0.12);
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
    z-index: 10;
}

.clothes-tile-item {
    min-height: 78px;
    min-width: 105px;
    background: #FFFFFF;
    border-radius: 16px;
    border: 2px solid #CFD8DC;
    box-shadow: 0 3px 0 #B0BEC5, 0 4px 8px rgba(0,0,0,0.06);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 3px;
    cursor: pointer;
    transition: transform 0.16s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.clothes-tile-item:hover { transform: translateY(-2px) scale(1.04); }
.clothes-tile-item:active { transform: scale(1.12); }
.clothes-tile-item.shake-wobble {
    animation: springShake 0.45s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
    border-color: #E75B52 !important;
}

.clothes-tile-item img {
    width: 52px;
    height: 52px;
    object-fit: contain;
    pointer-events: none;
}

.clothes-tile-item span {
    font-size: 11px;
    font-weight: 800;
    color: var(--text-dark);
    margin-top: 2px;
    text-align: center;
}

/* Bé Bin đứng trực tiếp trên sàn phòng ngủ (P0.3: Không pedestal, Không border) */
.room-bin-character-mount {
    width: 250px;
    height: 360px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    background: transparent;
    border: none;
    box-shadow: none;
    z-index: 10;
}

.bin-sprite-img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    pointer-events: none;
    filter: drop-shadow(0 6px 12px rgba(0,0,0,0.16));
}

/* ==========================================================================
   UNIFIED SCENE ART STAGE (HOÀN TOÀN KHÔNG CÓ KHUNG TRẮNG / STICKER)
   ========================================================================== */
.unified-scene-stage {
    width: 100%;
    max-width: 840px;
    height: 88%;
    position: relative;
    border-radius: 24px;
    overflow: hidden;
    box-shadow: 0 8px 24px rgba(0,0,0,0.18), 0 0 0 4px #FFFFFF;
    background: #000;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: auto 0;
}

.unified-scene-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: opacity 0.3s ease;
}

.scene-interactive-hud {
    position: absolute;
    bottom: 10px;
    left: 50%;
    transform: translateX(-50%);
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(8px);
    border-radius: var(--radius-round);
    padding: 6px 18px;
    border: 2px solid #FFE082;
    box-shadow: 0 4px 0 #FFCA28, var(--shadow-soft);
    display: flex;
    align-items: center;
    gap: 12px;
    z-index: 20;
}

/* OVERLAY PHẢN HỒI HOÀN THÀNH */
.activity-feedback-overlay {
    position: absolute;
    bottom: 12px;
    left: 50%;
    transform: translateX(-50%);
    background: rgba(255, 255, 255, 0.98);
    border-radius: 28px;
    padding: 6px 20px;
    border: 3px solid #82C99A;
    box-shadow: 0 6px 0 #43A047, var(--shadow-chunky);
    display: flex;
    align-items: center;
    gap: 14px;
    z-index: 60;
    animation: popBounce 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
    white-space: nowrap;
}

.activity-feedback-overlay.hidden {
    display: none !important;
}

.feedback-text {
    font-size: 16px;
    font-weight: 900;
    color: #1B5E20;
}

/* ==========================================================================
   ACTIVITY 3 & 6: BOARDING PASS
   ========================================================================== */
.real-boarding-pass {
    width: 100%;
    max-width: 520px;
    background: #FFFFFF;
    border-radius: 24px;
    border: 3px solid #F5A45D;
    box-shadow: 0 8px 0 #E67E22, var(--shadow-chunky);
    overflow: hidden;
    position: relative;
    cursor: pointer;
    transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.real-boarding-pass:hover { transform: scale(1.02); }

.pass-header-strip {
    background: linear-gradient(90deg, #0288D1 0%, #29B6F6 100%);
    color: #FFFFFF;
    padding: 6px 16px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-weight: 900;
    font-size: 13px;
}

.pass-body-grid {
    padding: 12px 18px;
    display: grid;
    grid-template-columns: 1.4fr 1fr;
    gap: 12px;
    background: #FFFDE7;
}

.pass-field-label {
    font-size: 10px;
    font-weight: 900;
    color: #78909C;
    text-transform: uppercase;
}

.pass-field-value {
    font-size: 16px;
    font-weight: 900;
    color: #37474F;
}

.pass-gate-highlight {
    background: #FFF3E0;
    border: 2px solid #FF9800;
    border-radius: 14px;
    padding: 6px 10px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.pass-gate-num {
    font-size: 30px;
    font-weight: 900;
    color: #E65100;
    line-height: 1;
}

.pass-stamp-overlay {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) rotate(-15deg) scale(0);
    border: 4px solid #2E7D32;
    color: #1B5E20;
    background: rgba(232, 245, 233, 0.95);
    font-weight: 900;
    font-size: 22px;
    padding: 6px 20px;
    border-radius: 14px;
    opacity: 0;
    pointer-events: none;
    box-shadow: 0 4px 14px rgba(46, 125, 50, 0.35);
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.pass-stamp-overlay.stamped {
    opacity: 1;
    transform: translate(-50%, -50%) rotate(-15deg) scale(1.08);
    animation: stampSlam 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

/* ==========================================================================
   ACTIVITY 4: SOI HÀNH LÝ
   ========================================================================== */
.xray-focused-arena {
    width: 100%;
    max-width: 780px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
    margin: auto 0;
}

.xray-scanner-chunky {
    width: 100%;
    max-width: 560px;
    background: rgba(255, 255, 255, 0.95);
    border-radius: 30px;
    border: 3px solid #00E676;
    box-shadow: 0 6px 0 #00BFA5, var(--shadow-chunky);
    padding: 14px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
}

.xray-screen-art-grid {
    width: 100%;
    height: 120px;
    background: #00251A;
    border-radius: 20px;
    border: 3px solid #00E676;
    box-shadow: inset 0 0 16px rgba(0, 230, 118, 0.5);
    display: flex;
    align-items: center;
    justify-content: space-around;
    padding: 6px;
}

.xray-item-tile {
    width: 72px;
    height: 72px;
    background: #004D40;
    border: 2px solid #00E676;
    border-radius: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    box-shadow: 0 0 12px rgba(0, 230, 118, 0.35);
    transition: transform 0.18s cubic-bezier(0.34, 1.56, 0.64, 1);
    padding: 4px;
}

.xray-item-tile:hover { transform: scale(1.1); }
.xray-item-tile img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    filter: brightness(0.2) invert(1) drop-shadow(0 0 4px #00E676);
}

.xray-item-tile.revealed {
    background: #FFFDE7;
    border-color: #F8D978;
    box-shadow: 0 0 16px #FFD54F;
    animation: popBounce 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.xray-item-tile.revealed img {
    filter: none;
}

/* ==========================================================================
   ACTIVITY 13: 5 VALI THẬT TRÊN BĂNG CHUYỀN
   ========================================================================== */
.real-carousel-track {
    width: 100%;
    max-width: 820px;
    height: 180px;
    border: 12px solid #455A64;
    border-radius: 90px;
    background: #ECEFF1;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-around;
    box-shadow: inset 0 0 14px rgba(0,0,0,0.2);
    overflow: hidden;
    margin: auto 0;
}

.real-suitcases-orbit {
    display: flex;
    gap: 28px;
    position: absolute;
    animation: carousel-orbit 14s linear infinite;
    align-items: center;
}

.real-suitcases-orbit.paused { animation-play-state: paused; }

.real-suitcase-card {
    width: 90px;
    height: 125px;
    background: transparent;
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.22s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.real-suitcase-card:hover { transform: scale(1.12) translateY(-4px); }
.real-suitcase-card img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    filter: drop-shadow(0 4px 10px rgba(0,0,0,0.22));
}

.real-suitcase-card.bin-picked {
    transform: scale(1.3) translateY(-12px);
    filter: drop-shadow(0 0 14px #FFD54F);
}

/* ==========================================================================
   CỔNG BA MẸ (P0.1: FIXED OVERLAY, DISPLAY: NONE MẶC ĐỊNH)
   ========================================================================== */
.parent-modal-overlay {
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    background: rgba(0, 0, 0, 0.72) !important;
    backdrop-filter: blur(8px);
    z-index: 99999 !important;
    display: none !important; /* P0.1 BLOCKER: DISPLAY NONE MẶC ĐỊNH */
    align-items: center;
    justify-content: center;
}

.parent-modal-overlay.open {
    display: flex !important;
}

.parent-control-card {
    width: 90%;
    max-width: 500px;
    max-height: 85vh;
    overflow-y: auto;
    background: #FFFFFF;
    border-radius: 28px;
    padding: 18px;
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.3);
    border: 3px solid #F5A45D;
}

.parent-tip-box {
    background: #FFF3E0;
    border-left: 4px solid #F5A45D;
    padding: 6px 10px;
    border-radius: 8px;
    margin-bottom: 6px;
    font-size: 12px;
    line-height: 1.35;
    color: #4E342E;
}

.level-jump-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 6px;
    margin: 6px 0;
}

.jump-btn {
    padding: 6px;
    background: #ECEFF1;
    border: 2px solid #CFD8DC;
    border-radius: 8px;
    font-weight: 800;
    font-size: 12px;
    cursor: pointer;
    transition: transform 0.15s;
}

.golden-medal-modal {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) scale(0.8);
    opacity: 0;
    visibility: hidden;
    width: 90%;
    max-width: 520px;
    background: linear-gradient(135deg, #FFFDE7 0%, #FFF9C4 100%);
    border-radius: 32px;
    border: 5px solid #F8D978;
    box-shadow: 0 14px 45px rgba(0,0,0,0.3);
    padding: 18px;
    text-align: center;
    z-index: 200;
    transition: all 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.golden-medal-modal.show {
    opacity: 1;
    visibility: visible;
    transform: translate(-50%, -50%) scale(1);
    animation: popBounce 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ==========================================================================
   KEYFRAME ANIMATIONS
   ========================================================================== */
@keyframes springShake {
    10%, 90% { transform: translate3d(-3px, 0, 0) rotate(-3deg); }
    20%, 80% { transform: translate3d(4px, 0, 0) rotate(3deg); }
    30%, 50%, 70% { transform: translate3d(-5px, 0, 0) rotate(-2deg); }
    40%, 60% { transform: translate3d(5px, 0, 0) rotate(2deg); }
}
@keyframes stampSlam {
    0% { transform: translate(-50%, -50%) scale(2.2) rotate(-35deg); opacity: 0; }
    50% { transform: translate(-50%, -50%) scale(0.95) rotate(-10deg); opacity: 1; }
    100% { transform: translate(-50%, -50%) scale(1.08) rotate(-15deg); opacity: 1; }
}
@keyframes popBounce { 0% { transform: scale(0.8); } 60% { transform: scale(1.15); } 100% { transform: scale(1); } }
@keyframes carousel-orbit { 0% { transform: translateX(0); } 100% { transform: translateX(-460px); } }

.pop-in-soft { animation: popInSoft 0.25s cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }
@keyframes popInSoft { 0% { transform: scale(0.92); opacity: 0.7; } 100% { transform: scale(1); opacity: 1; } }
.hidden { display: none !important; }

