        };

        // 100% Relative URLs
        this.scenes = {
            act7_unbuckled: 'assets/scenes/intro_act7_seatbelt.jpg',
            act7_buckled: 'assets/scenes/scene_act7_buckled.jpg',
            act8_ready: 'assets/scenes/scene_act7_buckled.jpg',
            act8_drinking: 'assets/scenes/scene_act8_drinking.jpg',
            act9_window: 'assets/scenes/scene_act9_window.jpg',
            act10_ready: 'assets/scenes/scene_act7_buckled.jpg',
            act10_whisper: 'assets/scenes/scene_act10_whisper.jpg',
            act11_ready: 'assets/scenes/scene_act7_buckled.jpg',
            act11_feet: 'assets/scenes/scene_act11_feet.jpg',
