/* ==========================================================================
   TẦNG 3: VIEWPORT 13 HOẠT ĐỘNG
   ========================================================================== */
.screens-viewport {
    flex: 1;
    position: relative;
    width: 100%;
    height: calc(100vh - 100px);
    overflow: hidden;
}

.activity-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    visibility: hidden;
    transform: scale(0.98);
