    transform: translate(-50%, -50%) scale(1);
    animation: popBounce 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ==========================================================================
   KEYFRAME ANIMATIONS
   ========================================================================== */
@keyframes springShake {
    10%, 90% { transform: translate3d(-3px, 0, 0) rotate(-3deg); }
    20%, 80% { transform: translate3d(4px, 0, 0) rotate(3deg); }
    30%, 50%, 70% { transform: translate3d(-5px, 0, 0) rotate(-2deg); }
    40%, 60% { transform: translate3d(5px, 0, 0) rotate(2deg); }
}
@keyframes stampSlam {
    0% { transform: translate(-50%, -50%) scale(2.2) rotate(-35deg); opacity: 0; }
    50% { transform: translate(-50%, -50%) scale(0.95) rotate(-10deg); opacity: 1; }
    100% { transform: translate(-50%, -50%) scale(1.08) rotate(-15deg); opacity: 1; }
}
@keyframes popBounce { 0% { transform: scale(0.8); } 60% { transform: scale(1.15); } 100% { transform: scale(1); } }
@keyframes carousel-orbit { 0% { transform: translateX(0); } 100% { transform: translateX(-460px); } }

.pop-in-soft { animation: popInSoft 0.25s cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }
@keyframes popInSoft { 0% { transform: scale(0.92); opacity: 0.7; } 100% { transform: scale(1); opacity: 1; } }
.hidden { display: none !important; }

/**
 * character-renderer.js - Character State Renderer for Bé Bin
 * Chuẩn Style BIN_SOFT_STORYBOOK_2D_V1
 * - Sử dụng đường dẫn tương đối (Relative URLs), 0 hard-code file:///
 * - Outfit State Machine cho Level 1 thay đổi trang phục thật 100%
 * - Tệp SVG tồn tại vật lý trên đĩa (Network 404 = 0), 0 console error
 */

class CharacterRenderer {
    constructor() {
        this.characterState = {
            outfit: {
                shirt: null, // 'yellow' | null
                pants: null, // 'blue' | null
                shoes: null  // 'velcro' | null
            },
            pose: 'standing',
            expression: 'normal',
            seatbelt: 'none',
            holding: null
        };

        // Bảng ánh xạ relative asset paths tới các tệp SVG tồn tại vật lý
        this.assets = {
            outfits: {
                base_neutral: 'assets/characters/bin/bin_base_neutral.svg',
                yellow_shirt_only: 'assets/characters/bin/bin_yellow_shirt_only.svg',
                yellow_shirt_blue_pants: 'assets/characters/bin/bin_yellow_shirt_blue_pants.svg',
                yellow_shirt_blue_pants_shoes: 'assets/characters/bin/bin_yellow_shirt_blue_pants_shoes.svg'
            },
            poses: {
                standing: 'assets/characters/bin/bin_point_right.svg',
                pointing: 'assets/characters/bin/bin_point_right.svg',
                holding_badge: 'assets/characters/bin/bin_holding_badge.svg'
            }
        };

        this.init();
    }

    init() {
        this.updateAll();
    }

    // --- Cập nhật từng thành phần trang phục ---
    setShirt(val) {
        this.characterState.outfit.shirt = val;
        console.log('[CharacterRenderer] Outfit updated:', this.characterState.outfit);
        this.updateAll();
    }

    setPants(val) {
        this.characterState.outfit.pants = val;
        console.log('[CharacterRenderer] Outfit updated:', this.characterState.outfit);
        this.updateAll();
    }

    setShoes(val) {
        this.characterState.outfit.shoes = val;
        console.log('[CharacterRenderer] Outfit updated:', this.characterState.outfit);
        this.updateAll();
    }

    setPose(poseName) {
        this.characterState.pose = poseName;
        this.updateAll();
    }

    setSeatbelt(status) {
        this.characterState.seatbelt = status;
        this.updateAll();
    }

    reset() {
        this.characterState = {
            outfit: { shirt: null, pants: null, shoes: null },
            pose: 'standing',
            expression: 'normal',
            seatbelt: 'none',
            holding: null
        };
        this.updateAll();
    }

    // --- State Machine ánh xạ sang Artwork thật của Level 1 ---
    getOutfitSpriteSrc() {
        const s = this.characterState.outfit.shirt;
        const p = this.characterState.outfit.pants;
        const sh = this.characterState.outfit.shoes;

        // Trạng thái 0: Mộc ban đầu (áo ba lỗ trắng + tất mộc)
        if (!s && !p && !sh) {
            return this.assets.outfits.base_neutral;
        }
        // Trạng thái 1: Đã chọn áo vàng
        if (s && !p && !sh) {
            return this.assets.outfits.yellow_shirt_only;
        }
        // Trạng thái 2: Đã chọn áo vàng + quần xanh
        if (s && p && !sh) {
            return this.assets.outfits.yellow_shirt_blue_pants;
        }
        // Trạng thái 3: Đầy đủ áo vàng + quần xanh + giày dán xé
        if (s && p && sh) {
            return this.assets.outfits.yellow_shirt_blue_pants_shoes;
        }

        // Chuyển tiếp linh hoạt
        if (s && sh && !p) return this.assets.outfits.yellow_shirt_only;
        if (p && !s) return this.assets.outfits.base_neutral;

        return this.assets.outfits.yellow_shirt_blue_pants_shoes;
    }

    // --- Render trực tiếp vào DOM container ---
    renderTo(containerEl, customMode = null) {
        if (!containerEl) return;

        const effectivePose = customMode || this.characterState.pose;
        let src = '';

        if (effectivePose === 'level1_outfit') {
            src = this.getOutfitSpriteSrc();
        } else {
            src = this.assets.poses[effectivePose] || this.assets.poses.standing;
        }

        containerEl.innerHTML = '';
        containerEl.classList.add('bin-character-frame');

        const img = document.createElement('img');
        img.className = 'bin-sprite-img pop-in-soft';
        img.src = src;
        img.alt = `Bé Bin ${effectivePose}`;
        img.style.width = '100%';
        img.style.height = '100%';
        img.style.objectFit = 'contain';
        img.style.display = 'block';

        img.onerror = () => {
            console.error('[IMAGE FAILED TO LOAD]', src);
        };

        containerEl.appendChild(img);
    }

    updateAll() {
        const lvl1Mount = document.getElementById('bin-character-mount-lvl1');
        if (lvl1Mount) this.renderTo(lvl1Mount, 'level1_outfit');

        const lvl3Mount = document.getElementById('bin-character-mount-lvl3');
        if (lvl3Mount) this.renderTo(lvl3Mount, 'pointing');

        const lvl8Mount = document.getElementById('bin-character-mount-lvl8');
        if (lvl8Mount) this.renderTo(lvl8Mount, 'holding_badge');
    }
}

