            9: { stage: 6, title: 'Ngắm Mây Và Tưởng Tượng', speaker: 'Bin', introText: '“Bin thấy đám mây giống hình gì nhỉ? Con nhìn cùng Bin nhé!”', subLabel: 'Hoạt động 9: Ngắm mây' },
