            11: { stage: 7, title: 'Ngồi Gọn — Không Đạp Ghế Trước', speaker: 'Bố', introText: '“Bin thu chân gọn lại để không chạm ghế phía trước nhé!”', subLabel: 'Bước 2/2: Ngồi gọn chân' },
