// ---- Level 1 character renderer ----
function renderBinCharacterOutfit() {
  const mount = el('bin-character-mount-lvl1');
  if (!mount) return;

  let src = 'assets/characters/bin/bin_base_neutral.svg';
  if (state.outfit.shirt && state.outfit.pants && state.outfit.shoes) {
    src = 'assets/characters/bin/bin_yellow_shirt_blue_pants_shoes.svg';
  } else if (state.outfit.shirt && state.outfit.pants) {
    src = 'assets/characters/bin/bin_yellow_shirt_blue_pants.svg';
  } else if (state.outfit.shirt) {
    src = 'assets/characters/bin/bin_yellow_shirt_only.svg';
  } else if (state.outfit.pants) {
    src = 'assets/characters/bin/bin_yellow_shirt_blue_pants.svg';
  } else if (state.outfit.shoes) {
    src = 'assets/characters/bin/bin_yellow_shirt_blue_pants_shoes.svg';
  }

  mount.innerHTML = `<img id="runtime-bin-full" src="${src}" alt="Bé Bin" style="width: 100%; height: 100%; object-fit: contain; filter: drop-shadow(0 8px 16px rgba(0,0,0,0.15));">`;
}

function ensureBinRenderer() {
  renderBinCharacterOutfit();
}

// ---- Activity 1 ----
function bindActivity1() {
  document.querySelectorAll('#act-1 [data-clothing-item="true"]').forEach(btn => {
    btn.addEventListener('click', () => {
      const fit = btn.dataset.fit;
      const typeRaw = btn.dataset.type;
      if (fit !== 'soft') {
        sfx.bad();
        showPrompt('Mẹ', 'Món này hơi bất tiện. Con thử món khác nhé!');
        return;
      }
      const type = typeRaw === 'shirt' ? 'shirt' : typeRaw === 'pants' ? 'pants' : typeRaw === 'shoes' ? 'shoes' : null;
      if (!type) return;
      state.outfit[type] = true;
      renderBinCharacterOutfit();
      btn.classList.add('runtime-selected');
      sfx.good();
      showPrompt('Mẹ', 'Đúng rồi! Món này mềm và dễ vận động.');
      if (state.outfit.shirt && state.outfit.pants && state.outfit.shoes) {
        completeActivity(1);
        showFeedback(1);
      }
    });
  });
}

