// ---- Level 1 character renderer ----
const baseCandidates = [
  'assets/characters/bin/bin_base_neutral.svg',
  'assets/characters/bin/bin_base.svg',
  'assets/characters/bin/bin_base.svg'
];
function loadFirstWorking(img, candidates, idx=0) {
  if (idx >= candidates.length) {
    const box = document.createElement('div');
    box.className = 'asset-load-error';
    box.textContent = 'Thiếu artwork Bé Bin trong assets/characters/bin/. App vẫn mở được nhưng cần bổ sung asset nhân vật.';
    img.replaceWith(box);
    return;
  }
  img.onerror = () => loadFirstWorking(img, candidates, idx+1);
  img.src = candidates[idx];
}
function ensureBinRenderer() {
  const mount = el('bin-character-mount-lvl1');
  if (!mount || mount.dataset.runtimeReady === '1') return;
  mount.dataset.runtimeReady = '1';
  mount.innerHTML = '';

  const base = document.createElement('img');
  base.className = 'bin-runtime-base';
  base.alt = 'Bé Bin';
  mount.appendChild(base);
  loadFirstWorking(base, baseCandidates);

  ['shirt','pants','shoes'].forEach(type => {
    const layer = document.createElement('img');
    layer.id = `runtime-bin-${type}`;
    layer.className = `bin-runtime-layer ${type}`;
    layer.alt = '';
    layer.style.display = 'none';
    mount.appendChild(layer);
  });
}
function setOutfitLayer(type, src) {
  const layer = el(`runtime-bin-${type}`);
  if (!layer) return;
  layer.src = src;
  layer.style.display = 'block';
  state.outfit[type] = src;
}

// ---- Activity 1 ----
function bindActivity1() {
  document.querySelectorAll('#act-1 [data-clothing-item="true"]').forEach(btn => {
    btn.addEventListener('click', () => {
      const fit = btn.dataset.fit;
      const typeRaw = btn.dataset.type;
      if (fit !== 'soft') {
        sfx.bad();
        showPrompt('Mẹ', 'Món này hơi bất tiện. Con thử món khác nhé!');
        return;
      }
      const type = typeRaw === 'shirt' ? 'shirt' : typeRaw === 'pants' ? 'pants' : typeRaw === 'shoes' ? 'shoes' : null;
      if (!type) return;
      const img = btn.querySelector('img');
      if (!img) return;
      setOutfitLayer(type, img.getAttribute('src'));
      btn.classList.add('runtime-selected');
      sfx.good();
      showPrompt('Mẹ', 'Đúng rồi! Món này mềm và dễ vận động.');
      if (state.outfit.shirt && state.outfit.pants && state.outfit.shoes) {
        completeActivity(1);
        showFeedback(1);
      }
    });
  });
}

