/**
 * character-renderer.js
 * Multi-layer Dynamic Character Renderer for Bé Bin (viewBox="0 0 400 600")
 * 
 * Cấu trúc layer chuẩn:
 * Layer 0: dress/bin_base.svg (Base body mộc duy nhất)
 * Layer 1: dress/pants/pants_blue.svg (Quần)
 * Layer 2: dress/shirts/shirt_yellow.svg (Áo)
 * Layer 3: dress/shoes/shoes_blue_velcro.svg (Giày)
 * Layer 4: layers/seatbelt_fastened.svg (Dây an toàn)
 */

class BinCharacterRenderer {
    constructor() {
        this.currentOutfit = {
            shirt: null,
            pants: null,
            shoes: null,
            seatbelt: null
        };

        this.assetMap = {
            base: 'assets/characters/bin/dress/bin_base.svg',
            shirts: {
                yellow: 'assets/characters/bin/dress/shirts/shirt_yellow.svg',
                soft: 'assets/characters/bin/dress/shirts/shirt_yellow.svg',
                blue: 'assets/characters/bin/dress/shirts/shirt_blue.svg'
            },
            pants: {
                blue: 'assets/characters/bin/dress/pants/pants_blue.svg',
                soft: 'assets/characters/bin/dress/pants/pants_blue.svg',
                orange: 'assets/characters/bin/dress/pants/pants_orange.svg'
            },
            shoes: {
                velcro: 'assets/characters/bin/dress/shoes/shoes_blue_velcro.svg',
                blue_velcro: 'assets/characters/bin/dress/shoes/shoes_blue_velcro.svg',
                white_laces: 'assets/characters/bin/dress/shoes/shoes_white_laces.svg'
            },
            seatbelt: {
                fastened: 'assets/characters/bin/layers/seatbelt_fastened.svg',
                none: null
            }
        };

        this.containers = new Set();
    }

    renderTo(containerOrId) {
        const container = typeof containerOrId === 'string' ? document.getElementById(containerOrId) : containerOrId;
        if (!container) return;

        this.containers.add(container);
        this.setupDOM(container);
        this.updateLayers(container);
    }

    setupDOM(container) {
        // Xóa hoàn toàn các thẻ sprite cũ
        container.innerHTML = '';
        container.classList.add('bin-layered-character');

        container.innerHTML = `
            <div class="bin-layers-wrapper" style="position: relative; width: 100%; height: 100%; min-height: 320px; display: flex; align-items: center; justify-content: center;">
                <img class="bin-layer bin-base-layer" src="${this.assetMap.base}" alt="Bé Bin" style="position: relative; width: 100%; height: 100%; object-fit: contain; z-index: 1;">
                <img class="bin-layer bin-pants-layer" style="position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; z-index: 2; display: none;" alt="Quần Bé Bin">
                <img class="bin-layer bin-shirt-layer" style="position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; z-index: 3; display: none;" alt="Áo Bé Bin">
                <img class="bin-layer bin-shoes-layer" style="position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; z-index: 4; display: none;" alt="Giày Bé Bin">
                <img class="bin-layer bin-seatbelt-layer" style="position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; z-index: 5; display: none;" alt="Dây an toàn">
            </div>
        `;
    }

    updateLayers(container) {
        if (!container) return;
        const pantsImg = container.querySelector('.bin-pants-layer');
        const shirtImg = container.querySelector('.bin-shirt-layer');
        const shoesImg = container.querySelector('.bin-shoes-layer');
        const seatbeltImg = container.querySelector('.bin-seatbelt-layer');

        if (pantsImg) {
            if (this.currentOutfit.pants && this.assetMap.pants[this.currentOutfit.pants]) {
                pantsImg.src = this.assetMap.pants[this.currentOutfit.pants];
                pantsImg.style.display = 'block';
            } else {
                pantsImg.style.display = 'none';
            }
        }

        if (shirtImg) {
            if (this.currentOutfit.shirt && this.assetMap.shirts[this.currentOutfit.shirt]) {
                shirtImg.src = this.assetMap.shirts[this.currentOutfit.shirt];
                shirtImg.style.display = 'block';
            } else {
                shirtImg.style.display = 'none';
            }
        }

        if (shoesImg) {
            if (this.currentOutfit.shoes && this.assetMap.shoes[this.currentOutfit.shoes]) {
                shoesImg.src = this.assetMap.shoes[this.currentOutfit.shoes];
                shoesImg.style.display = 'block';
            } else {
                shoesImg.style.display = 'none';
            }
        }

        if (seatbeltImg) {
            if (this.currentOutfit.seatbelt && this.assetMap.seatbelt[this.currentOutfit.seatbelt]) {
                seatbeltImg.src = this.assetMap.seatbelt[this.currentOutfit.seatbelt];
                seatbeltImg.style.display = 'block';
            } else {
                seatbeltImg.style.display = 'none';
            }
        }
    }

    setShirt(shirtKey) {
        this.currentOutfit.shirt = shirtKey;
        this.containers.forEach(c => this.updateLayers(c));
    }

    setPants(pantsKey) {
        this.currentOutfit.pants = pantsKey;
        this.containers.forEach(c => this.updateLayers(c));
    }

    setShoes(shoesKey) {
        this.currentOutfit.shoes = shoesKey;
        this.containers.forEach(c => this.updateLayers(c));
    }

    setSeatbelt(seatbeltKey) {
        this.currentOutfit.seatbelt = seatbeltKey;
        this.containers.forEach(c => this.updateLayers(c));
    }

    reset() {
        this.currentOutfit = { shirt: null, pants: null, shoes: null, seatbelt: null };
        this.containers.forEach(c => this.updateLayers(c));
    }
}

window.binRenderer = new BinCharacterRenderer();

