// ---- Level 1 character renderer (4-LAYER STACK: dress/bin_base.svg + shirts + pants + shoes) ----
function ensureBinRenderer() {
  if (window.binRenderer) {
    window.binRenderer.renderTo('bin-character-mount-lvl1');
  }
}

// ---- Activity 1 ----
function bindActivity1() {
  document.querySelectorAll('#act-1 [data-clothing-item="true"]').forEach(btn => {
    btn.addEventListener('click', () => {
      const fit = btn.dataset.fit;
      const typeRaw = btn.dataset.type;
      if (fit !== 'soft') {
        sfx.bad();
        showPrompt('Mẹ', 'Món này hơi bất tiện. Con thử món khác nhé!');
        return;
      }
      const type = typeRaw === 'shirt' ? 'shirt' : typeRaw === 'pants' ? 'pants' : typeRaw === 'shoes' ? 'shoes' : null;
      if (!type) return;

      if (window.binRenderer) {
        if (type === 'shirt') window.binRenderer.setShirt('yellow');
        if (type === 'pants') window.binRenderer.setPants('blue');
        if (type === 'shoes') window.binRenderer.setShoes('velcro');
      }

      state.outfit[type] = true;
      btn.classList.add('runtime-selected');
      sfx.good();
      showPrompt('Mẹ', 'Đúng rồi! Món này mềm và dễ vận động.');
      if (state.outfit.shirt && state.outfit.pants && state.outfit.shoes) {
        completeActivity(1);
        showFeedback(1);
      }
    });
  });
}

