    src = 'assets/characters/bin/bin_yellow_shirt_only.svg';
  } else if (state.outfit.pants) {
    src = 'assets/characters/bin/bin_yellow_shirt_blue_pants.svg';
  } else if (state.outfit.shoes) {
    src = 'assets/characters/bin/bin_yellow_shirt_blue_pants_shoes.svg';
  }

  mount.innerHTML = `<img id="runtime-bin-full" src="${src}" alt="Bé Bin" style="width: 100%; height: 100%; object-fit: contain; filter: drop-shadow(0 8px 16px rgba(0,0,0,0.15));">`;
}

