function bindActivity1() {
  document.querySelectorAll('#act-1 [data-clothing-item="true"]').forEach(btn => {
    btn.addEventListener('click', () => {
      const fit = btn.dataset.fit;
      const typeRaw = btn.dataset.type;
      if (fit !== 'soft') {
        sfx.bad();
        showPrompt('Mẹ', 'Món này hơi bất tiện. Con thử món khác nhé!');
        return;
      }
      const type = typeRaw === 'shirt' ? 'shirt' : typeRaw === 'pants' ? 'pants' : typeRaw === 'shoes' ? 'shoes' : null;
      if (!type) return;

      if (window.binRenderer) {
        if (type === 'shirt') window.binRenderer.setShirt('yellow');
        if (type === 'pants') window.binRenderer.setPants('blue');
        if (type === 'shoes') window.binRenderer.setShoes('velcro');
      }

      state.outfit[type] = true;
      btn.classList.add('runtime-selected');
      sfx.good();
      showPrompt('Mẹ', 'Đúng rồi! Món này mềm và dễ vận động.');
      if (state.outfit.shirt && state.outfit.pants && state.outfit.shoes) {
        completeActivity(1);
        showFeedback(1);
      }
    });
  });
}

function bindActivity2() {
  document.querySelectorAll('#act-2 [data-luggage-item="true"]').forEach(btn => {
    btn.addEventListener('click', () => {
      if (btn.dataset.category === 'PACK') {
        btn.classList.add('runtime-packed');
        state.packed.add(btn);
        sfx.good();
        showPrompt('Bố', 'Ừ! Món này mình xếp vào vali nhé.');
        if (state.packed.size >= 3) { completeActivity(2); showFeedback(2); }
      } else {
        sfx.pop();
        showPrompt('Bố', 'Món này mình hỏi Ba Mẹ trước nhé!');
      }
    });
  });
}

function bindSimpleActivities() {
  // Act 3
  el('btn-show-ticket-3')?.addEventListener('click', () => {
    sfx.stamp();
    showPrompt('Mẹ', 'Vé của Bin đã được kiểm tra rồi!');
    completeActivity(3);
    showFeedback(3);
  });

  // Act 4
  document.querySelectorAll('#act-4 .xray-item-tile').forEach((tile, i) => {
    tile.addEventListener('click', () => {
      state.xrayChecked.add(i);
      sfx.good();
      if (state.xrayChecked.size >= 3) { completeActivity(4); showFeedback(4); }
    });
  });

  // Act 5
  el('btn-walk-gate-5')?.addEventListener('click', () => {
    sfx.good();
    completeActivity(5);
    showFeedback(5);
  });

  // Act 6
  document.querySelectorAll('#act-6 .gate-hud-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      if (btn.dataset.gate === '03') {
        sfx.good();
        showPrompt('Bố', 'Đúng rồi! Cổng 03 đây rồi!');
        completeActivity(6);
        showFeedback(6);
      } else {
        sfx.bad();
        showPrompt('Bố', 'Con nhìn lại số trên vé nhé!');
      }
    });
  });

  // Act 7: Cài dây an toàn (Canonical Bé Bin + Seatbelt Layer)
  el('btn-buckle-action-7')?.addEventListener('click', () => {
    if (window.binRenderer) window.binRenderer.setSeatbelt('fastened');
    sfx.clack();
    completeActivity(7);
    showFeedback(7);
  });

  // Act 8: Uống nước
  el('btn-drink-action-8')?.addEventListener('click', () => {
    sfx.good();
    showPrompt('Bin', 'Tai Bin dễ chịu hơn rồi!');
    completeActivity(8);
    showFeedback(8);
  });

  // Act 9: Ngắm mây
  document.querySelectorAll('#act-9 .morph-cloud-btn').forEach((btn, i) => {
    btn.addEventListener('click', () => {
      state.clouds.add(i);
      btn.classList.add('runtime-selected');
      sfx.good();
      showPrompt('Bin', `Bin thấy giống ${btn.dataset.name || 'một hình thật vui'}! Còn con thấy giống gì?`);
      if (state.clouds.size >= 3) { completeActivity(9); showFeedback(9); }
    });
  });

  // Act 10: Nói nhỏ
  document.querySelectorAll('#act-10 .volume-act-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      if (btn.dataset.level === 'whisper') {
        sfx.good();
        showPrompt('Bin', 'Đúng rồi! Mình nói nhỏ vừa đủ nghe nhé.');
        completeActivity(10);
        showFeedback(10);
      } else if (btn.dataset.level === 'medium') {
        sfx.pop();
        showPrompt('Mẹ', 'Nhỏ hơn một chút nữa nhé!');
      } else {
        sfx.bad();
        showPrompt('Mẹ', 'Ơ, hơi to rồi. Con thử nhỏ hơn nhé!');
      }
    });
  });

  // Act 11: Ngồi gọn
  el('btn-tuck-feet')?.addEventListener('click', () => {
    sfx.good();
    showPrompt('Bố', 'Giỏi lắm! Bin ngồi gọn rồi, không đạp ghế trước!');
    completeActivity(11);
    showFeedback(11);
  });

  // Act 13: Tìm vali
  document.querySelectorAll('#act-13 .real-suitcase-card').forEach(btn => {
    btn.addEventListener('click', () => {
      if (btn.dataset.isBin === 'true') {
        sfx.good();
        completeActivity(13);
        el('golden-medal-modal')?.classList.add('show');
      } else {
        btn.classList.remove('runtime-wrong');
        void btn.offsetWidth;
        btn.classList.add('runtime-wrong');
        sfx.bad();
        showPrompt('Bố', 'Vali này của bạn khác rồi. Con tìm lại nhé!');
      }
    });
  });
}

function armLandingWait() {
  const btn = el('unbuckle-latch-btn');
  if (!btn) return;
  btn.disabled = true;
  btn.style.opacity = '.6';
  btn.innerHTML = '<span>⏳ Máy bay đang chạy vào bãi đỗ...</span>';
  showPrompt('Bố', 'Máy bay đang chạy vào chỗ đỗ. Bin vẫn ngồi yên và giữ dây an toàn nhé!');
  if (state.activity12Timer) clearTimeout(state.activity12Timer);
  state.activity12Timer = setTimeout(() => {
    btn.disabled = false;
    btn.style.opacity = '1';
    btn.innerHTML = '<span>🔓 Máy bay đã dừng hẳn — mở dây an toàn</span>';
    showPrompt('Mẹ', 'Máy bay dừng hẳn rồi. Bây giờ mình mới mở dây nhé!');
  }, state.reducedMotion ? 700 : 2500);

  btn.onclick = () => {
    if (btn.disabled) return;
    if (window.binRenderer) window.binRenderer.setSeatbelt('none');
    sfx.clack();
    completeActivity(12);
    showFeedback(12);
  };
}

