args.ReplacementContent:
/* MÀN GIỚI THIỆU HOẠT ĐỘNG (INTRO VIEW) - KHÓA KÍCH THƯỚC CHUẨN */
.activity-intro-view {
    width: 100%;
    max-width: 860px;
    height: 88%;
    background: rgba(255, 255, 255, 0.96);
    backdrop-filter: blur(8px);
    border-radius: var(--radius-story);
    border: 3px solid #FFE082;
    box-shadow: 0 8px 0 #FFCA28, var(--shadow-chunky);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    padding: 14px 20px;
    text-align: center;
    margin: auto 0;
    z-index: 10;
}

.intro-header-badge {
    background: #E1F5FE;
    color: #0288D1;
    font-size: 12px;
    font-weight: 900;
    padding: 3px 14px;
    border-radius: var(--radius-round);
    border: 2px solid #B3E5FC;
}

.intro-activity-title {
    font-size: 20px;
    font-weight: 900;
    color: #E65100;
    margin: 2px 0;
}

.intro-art-frame {
    width: 100%;
    max-width: 660px;
    height: 240px;
    border-radius: 18px;
    overflow: hidden;
    box-shadow: 0 4px 14px rgba(0,0,0,0.1);
    border: 2px solid #FFF;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #FFF;
}

.intro-art-frame img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.intro-prompt-quote {
    font-size: 15px;
    font-weight: 800;
    color: #37474F;
    line-height: 1.3;
    padding: 0 10px;
}

.activity-gameplay-view {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
}

/* ==========================================================================
   LEVEL 1: PHÒNG NGỦ BÉ BIN (P0.3 - BIN ĐỨNG TRỰC TIẾP TRÊN NỀN PHÒNG)
   ========================================================================== */
.level1-room-scene {
    width: 100%;
    max-width: 860px;
    height: 88%;
    position: relative;
    border-radius: 24px;
    overflow: hidden;
    box-shadow: 0 8px 24px rgba(0,0,0,0.18), 0 0 0 4px #FFFFFF;
    background-size: cover;
    background-position: center;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 36px;
    margin: auto 0;
}

/* Kệ tủ đồ bên trái */
.room-wardrobe-grid {
    background: rgba(255, 255, 255, 0.88);
    backdrop-filter: blur(6px);
    border: 3px solid #FFE082;
    border-radius: 20px;
    padding: 8px;
    box-shadow: 0 6px 16px rgba(0,0,0,0.12);
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
    z-index: 10;
}

.clothes-tile-item {
    min-height: 78px;
    min-width: 105px;
    background: #FFFFFF;
    border-radius: 16px;
    border: 2px solid #CFD8DC;
    box-shadow: 0 3px 0 #B0BEC5, 0 4px 8px rgba(0,0,0,0.06);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 3px;
    cursor: pointer;
    transition: transform 0.16s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.clothes-tile-item:hover { transform: translateY(-2px) scale(1.04); }
.clothes-tile-item:active { transform: scale(1.12); }
.clothes-tile-item.shake-wobble {
    animation: springShake 0.45s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
    border-color: #E75B52 !important;
}

.clothes-tile-item img {
    width: 52px;
    height: 52px;
    object-fit: contain;
    pointer-events: none;
}

.clothes-tile-item span {
    font-size: 11px;
    font-weight: 800;
    color: var(--text-dark);
    margin-top: 2px;
    text-align: center;
}

/* Bé Bin đứng trực tiếp trên sàn phòng ngủ */
.room-bin-character-mount {
    width: 260px;
    height: 380px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    z-index: 10;
    margin-right: 30px;
    margin-top: 15px;
}

.bin-sprite-img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    pointer-events: none;
    filter: drop-shadow(0 6px 12px rgba(0,0,0,0.16));
}

/* ==========================================================================
   UNIFIED SCENE ART STAGE (CHUẨN 860px x 88%)
   ========================================================================== */
.unified-scene-stage {
    width: 100%;
    max-width: 860px;
    height: 88%;
    position: relative;
    border-radius: 24px;
    overflow: hidden;
    box-shadow: 0 8px 24px rgba(0,0,0,0.18), 0 0 0 4px #FFFFFF;
    background: #000;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: auto 0;
}

