/**
 * character-renderer.js
 * Renderer sử dụng trực tiếp các file ảnh JPG chuẩn Storybook từ thư mục Artifacts
 */

class BinCharacterRenderer {
    constructor() {
        this.currentOutfit = {
            shirt: null,
            pants: null,
            shoes: null,
            seatbelt: null
        };

        this.sprites = {
            base: 'assets/characters/bin/bin_base_neutral.svg',
            shirtOnly: 'assets/characters/bin/bin_yellow_shirt_only.svg',
            shirtPants: 'assets/characters/bin/bin_yellow_shirt_blue_pants.svg',
            fullOutfit: 'assets/characters/bin/bin_yellow_shirt_blue_pants_shoes.svg'
        };

        this.containers = new Set();

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => this.mountAll());
        } else {
            this.mountAll();
        }
    }

    mountAll() {
        document.querySelectorAll('[data-bin-character]').forEach(el => {
            this.renderTo(el);
        });
    }

    renderTo(containerOrId) {
        const container = typeof containerOrId === 'string' ? document.getElementById(containerOrId) : containerOrId;
        if (!container) return;

        this.containers.add(container);
        this.updateImage(container);
    }

    getCurrentImageSrc() {
        if (this.currentOutfit.shirt && this.currentOutfit.pants && this.currentOutfit.shoes) {
            return this.sprites.fullOutfit;
        } else if (this.currentOutfit.shirt && this.currentOutfit.pants) {
            return this.sprites.shirtPants;
        } else if (this.currentOutfit.shirt) {
            return this.sprites.shirtOnly;
        } else if (this.currentOutfit.pants) {
            return this.sprites.shirtPants;
        } else if (this.currentOutfit.shoes) {
            return this.sprites.fullOutfit;
        }
        return this.sprites.base;
    }

    updateImage(container) {
        if (!container) return;
        Object.assign(container.style, {
            background: 'transparent',
            backgroundColor: 'transparent',
            border: 'none',
            outline: 'none',
            boxShadow: 'none',
            borderRadius: '0',
            overflow: 'visible'
        });
        const src = this.getCurrentImageSrc();
        container.innerHTML = `
            <div style="position: relative; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; overflow: visible; background: transparent;">
                <img src="${src}" alt="Bé Bin" style="width: 100%; height: 100%; object-fit: contain; background: transparent; pointer-events: none;">
            </div>
        `;
    }

    setShirt(shirtKey) {
        this.currentOutfit.shirt = shirtKey;
        this.refreshAll();
    }

    setPants(pantsKey) {
        this.currentOutfit.pants = pantsKey;
        this.refreshAll();
    }

    setShoes(shoesKey) {
        this.currentOutfit.shoes = shoesKey;
        this.refreshAll();
    }

    setSeatbelt(seatbeltKey) {
        this.currentOutfit.seatbelt = seatbeltKey;
        this.refreshAll();
    }

    reset() {
        this.currentOutfit = { shirt: null, pants: null, shoes: null, seatbelt: null };
        this.refreshAll();
    }

    refreshAll() {
        this.mountAll();
        this.containers.forEach(c => this.updateImage(c));
    }
}

