function bindActivity2() {
  document.querySelectorAll('#act-2 [data-luggage-item="true"]').forEach(btn => {
    btn.addEventListener('click', () => {
      const cat = btn.dataset.category;
      const name = btn.dataset.name || 'Món đồ';
      const imgUrl = btn.dataset.img || '';

      if (cat === 'PACK') {
        btn.classList.add('runtime-packed');
        state.packed.add(name);

        // Thêm hình ảnh/badge đồ vật trực tiếp vào trong vali mở
        const targetSuitcase = el('suitcase-packed-items');
        if (targetSuitcase) {
          const badge = document.createElement('div');
          badge.className = 'packed-item-mini';
          badge.innerHTML = `
            <img src="${imgUrl}" alt="${name}">
            <span>${name} ✓</span>
          `;
          targetSuitcase.appendChild(badge);
        }

        sfx.good();
        showPrompt('Bố', `Đúng rồi! ${name} cần thiết mang theo!`);
        if (state.packed.size >= 4) {
          completeActivity(2);
          showFeedback(2);
        }
      } else {
        btn.classList.remove('wobble-shake');
        void btn.offsetWidth; // Trigger reflow for animation restart
        btn.classList.add('wobble-shake');
        sfx.bad();

        if (name.includes('Kéo')) {
          showPrompt('Bố', 'Kéo nhọn kim loại nguy hiểm, không được mang lên máy bay con nhé!');
        } else if (name.includes('Ô tô')) {
          showPrompt('Bố', 'Ô tô to quá cồng kềnh chiếm hết vali, mình để ở nhà về chơi sau nhé!');
        } else {
          showPrompt('Bố', 'Bình nước lớn hơn 100ml không qua được cổng an ninh, mình để ở nhà nhé!');
        }
      }
    });
  });
}

function bindSimpleActivities() {
  // Act 3: Kiểm tra vé & Khoanh tròn Đỏ Số Ghế 12A & Đóng dấu Boarding Pass
  const onTicketCheck = () => {
    const redCircle = el('seat-red-circle');
    if (redCircle) redCircle.style.display = 'block';
    const stamp = el('pass-stamp-overlay');
    if (stamp) stamp.style.display = 'block';

    sfx.good();
    setTimeout(() => sfx.stamp(), 200);

    showPrompt('Mẹ', 'Giỏi lắm! Ghế 12A là ghế cạnh cửa sổ của Bin đấy!');
    completeActivity(3);
    showFeedback(3);
  };

  el('seat-selection-btn')?.addEventListener('click', onTicketCheck);
  el('btn-show-ticket-3')?.addEventListener('click', onTicketCheck);
  el('boarding-pass-card')?.addEventListener('click', onTicketCheck);

  // Act 4: Soi hành lý
  document.querySelectorAll('#act-4 .xray-item-tile').forEach((tile, i) => {
    tile.addEventListener('click', () => {
      state.xrayChecked.add(i);
      tile.classList.add('runtime-checked');
      sfx.good();
      if (state.xrayChecked.size >= 3) {
        completeActivity(4);
        showFeedback(4);
      }
    });
  });

  // Act 5: Cổng an ninh
  el('btn-walk-gate-5')?.addEventListener('click', () => {
    sfx.good();
    showPrompt('Mẹ', 'Bíp boong! Bin qua cửa an toàn rồi!');
    completeActivity(5);
    showFeedback(5);
  });

  // Act 6: Tìm Cổng 03
  document.querySelectorAll('#act-6 .gate-hud-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      if (btn.dataset.gate === '03') {
        btn.classList.add('runtime-correct');
        sfx.good();
        showPrompt('Bố', 'Đúng rồi! Cổng 03 đây rồi!');
        completeActivity(6);
        showFeedback(6);
      } else {
        sfx.bad();
        showPrompt('Bố', 'Con nhìn lại số trên vé nhé!');
      }
    });
  });

  // XỬ LÝ TRẮC NGHIỆM HÌNH ẢNH (ACTS 7, 8, 10, 11, 12)
  document.querySelectorAll('.visual-quiz-card').forEach(btn => {
    btn.addEventListener('click', () => {
      const actNum = parseInt(btn.dataset.act, 10);
      const isCorrect = btn.dataset.choice === 'correct';

      if (isCorrect) {
        btn.classList.add('correct');
        sfx.good();

        if (actNum === 7) {
          if (window.binRenderer) window.binRenderer.setSeatbelt('fastened');
          showPrompt('Mẹ', 'CẠCH! Dây an toàn chắc chắn rồi! Máy bay chuẩn bị cất cánh!');
        } else if (actNum === 8) {
          showPrompt('Bin', 'Nuốt nước ực một cái, tai Bin hết khó chịu rồi!');
        } else if (actNum === 10) {
          showPrompt('Bin', 'Đúng rồi! Mình nói nhỏ vừa đủ nghe để giữ yên tĩnh cho mọi người!');
        } else if (actNum === 11) {
          showPrompt('Bố', 'Giỏi lắm! Bin ngồi rất ngoan, thu chân gọn gàng không chạm ghế phía trước!');
        } else if (actNum === 12) {
          showPrompt('Mẹ', 'Máy bay dừng hẳn rồi. Bây giờ mình mới mở dây nhé!');
        }

        completeActivity(actNum);
        showFeedback(actNum);
      } else {
        btn.classList.remove('incorrect');
        void btn.offsetWidth; // Trigger reflow for animation restart
        btn.classList.add('incorrect');
        sfx.bad();

        if (actNum === 7) {
          showPrompt('Mẹ', 'Đứng trên ghế rất nguy hiểm khi máy bay di chuyển con nhé. Bin cài dây an toàn lại nào!');
        } else if (actNum === 8) {
          showPrompt('Mẹ', 'Bịt tai khóc sẽ không làm hết khó chịu. Bin thử uống từng ngụm nước nhỏ nhé!');
        } else if (actNum === 10) {
          showPrompt('Mẹ', 'Nói to sẽ làm ồn mọi người xung quanh đấy. Bin nói nhỏ thì thầm nhé!');
        } else if (actNum === 11) {
          showPrompt('Bố', 'Đạp vào lưng ghế trước làm rung và phiền người ngồi trước con nhé. Mình thu chân gọn lại nào!');
        } else if (actNum === 12) {
          showPrompt('Bố', 'Đèn báo hiệu còn sáng, máy bay đang di chuyển, mình chưa được đứng dậy lấy đồ con nhé!');
        }
      }
    });
  });

  // Act 9: Ngắm mây
  document.querySelectorAll('#act-9 .morph-cloud-btn').forEach((btn, i) => {
    btn.addEventListener('click', () => {
      state.clouds.add(i);
      btn.classList.add('runtime-selected');
      sfx.good();
      showPrompt('Bin', `Bin thấy giống ${btn.dataset.name || 'một hình thật vui'}! Còn con thấy giống gì?`);
      if (state.clouds.size >= 3) {
        completeActivity(9);
        showFeedback(9);
      }
    });
  });

