if not exist "%DEST_DIR%" mkdir "%DEST_DIR%"
copy /Y "%SRC_DIR%\*.jpg" "%DEST_DIR%\" >nul
copy /Y "%SRC_DIR%\*.png" "%DEST_DIR%\" >nul
echo     -> Đã sao chép thành công toàn bộ hình ảnh vào: %DEST_DIR%
