    git init
    git branch -M main
)

git add .
git commit -m "Cập nhật ứng dụng Bé Bin Đi Máy Bay: Hoàn thiện 13 hoạt động tương tác, trắc nghiệm hình ảnh và 100%% minh họa JPG"

