git remote get-url origin >nul 2>&1
if %ERRORLEVEL% NEQ 0 (
    echo Chưa có liên kết GitHub repository (remote origin).
    set /p REPO_URL="Nhập đường dẫn GitHub repository của bạn (ví dụ: https://github.com/username/ten-repo.git): "
    if not "%REPO_URL%"=="" (
        git remote add origin %REPO_URL%
        git push -u origin main
    ) else (
        echo Bạn có thể thêm remote sau bằng lệnh: git remote add origin ^<link_github^>
    )
) else (
    echo Đang đẩy dữ liệu lên GitHub...
    git push origin main
)

echo.
echo ========================================================
echo   ✅ HOÀN TẤT! Dự án đã sẵn sàng trên GitHub!
echo ========================================================
pause

